import{ap as ge,ak as n,ab as c,C as s,cK as Vt,N as g,n as F,D as M,dd as T,cq as nr,cF as Ia,cE as or,dg as et,dk as xa,dl as P,dm as sr,dn as Wa,dp as ir,dq as hr,dr as lr,d3 as Ga,ds as Na,dt as dr,du as cr,dv as ur,ck as pr,bc as La,dw as _a,dx as Zt,bV as Ua,a as fr,b as mr,b4 as gr,dy as Jt}from"./index-BUImCUAB.js";import{j as Ba}from"./rideRuleAudience-CeTtaxDA.js";const Qt="2026-09-04",yr=["premium-suv-scottsdale","maybach-shuttle-sprinter-8","maybach-jet-sprinter-scottsdale","executive-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","limo-sprinter-16-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"].filter(ge),j=yr.map(e=>({slug:e,name:n[e],capacity:c[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours}));function Oa(e){return g(s[e].hourlyRateCents)}function qa(e,t,a){return g(Math.round(s[e].hourlyRateCents*t/a))}const br=[{href:"/services/wedding-transportation-scottsdale",label:"Scottsdale wedding transportation"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter van rental"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport group transportation"},{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published hourly pricing"}];function $e(e){const t=j.find(o=>o.slug==="executive-sprinter-scottsdale"),a=j.find(o=>o.slug==="motorcoach-56");return{path:e.path,title:`${e.name} Wedding Shuttle Guide | Scottsdale Sprinters`,description:`Plan ${e.name} wedding shuttles with published vehicle capacities, hotel pickup waves, venue arrival coordination, and an end-of-night return plan.`,metaDescription:"Hotel pickup waves, vehicle sizing and the end-of-night return",updatedAt:"2026-09-18",h1:`${e.name} wedding shuttle and guest transportation`,eyebrow:"Wedding venue transportation guide",intro:`A ${e.name} shuttle from Scottsdale Sprinters works best when one transportation lead owns the guest list, every pickup has a written address, and the venue confirms the final arrival point. This guide turns that into vehicle counts, pickup waves, driver notes, and a return schedule, without inventing a gate or loading zone.`,fleetTable:!0,sections:[{heading:`What should couples know about ${e.name} before planning transportation?`,answer:`${e.name} planning starts with 3 verified details: the venue address, the contracted event space, and the arrival instructions supplied by the venue team, because a property name alone is not enough for a driver brief and public websites do not always publish a wedding-specific loading point.`,paragraphs:[`${e.name} is at ${e.address}. ${e.venueFacts} That tells a transportation planner where the property is and what kind of celebration the venue supports, but it does not replace the instructions in the couple's venue contract. The final driver sheet should use the venue's current written directions and the event-space name exactly as the coordinator provides them.`,`${e.arrivalNote} We do not label an unverified driveway, gate, porte cochere, or service entrance as the wedding drop-off. The couple or planner should ask the venue which approach is approved for the booked space, whether a vehicle may wait, and where guests with mobility needs should be delivered. Those answers belong in the dispatch note before the wedding day.`,e.venueSpecific[0],"Treat the venue source linked below as a planning reference, then reconcile it with the banquet event order. Websites can change, private-event operations can differ from hotel arrivals, and another event may affect traffic flow. One confirmed instruction shared with the reservations team, planner, and venue contact is safer than several guests forwarding different map pins."]},{heading:`Which vehicle size fits the ${e.name} wedding guest count?`,answer:`For ${e.name}, use 10 published capacity bands from a 6-passenger luxury SUV through a 56-passenger motorcoach, then reserve seats for the people actually riding rather than the total attendance; a 120-guest reception may need transportation for only 42 hotel guests while the wedding party follows a separate schedule.`,paragraphs:[`The table on this page uses the same current capacities and hourly rates shown with each vehicle. The ${t.name} seats ${t.capacity} and starts at ${g(t.hourlyRateCents)} per hour, while the ${a.name} seats ${a.capacity} and starts at ${g(a.hourlyRateCents)} per hour. Those figures update with the published fleet information rather than relying on estimates copied into the article.`,"Build the rider count from RSVPs, hotel blocks, family assignments, and accessibility needs. Do not divide the full invitation list by the largest vehicle. Some guests will drive, some will stay on property, and some may need an earlier departure. A clean manifest groups people by pickup and return wave, which can reduce empty seats without putting the ceremony at risk.",e.venueSpecific[1],"Leave operational margin. A vehicle advertised for a maximum seated capacity is not a promise that every combination of passengers, dresses, mobility devices, gifts, and personal items will fit comfortably. Tell the reservations team what the group is carrying. Luggage and gear fit should be confirmed separately whenever airport arrivals, welcome bags, decor, or vendor materials are part of the ride."]},{heading:`How should hotel pickup waves for ${e.name} be organized?`,answer:`Plan at least 2 pickup waves for ${e.name} when guests are split across hotels or readiness times: an early family and wedding-party movement with schedule padding, followed by the main guest shuttle, while one named transportation lead confirms each vehicle's manifest instead of asking chauffeurs to reconcile a changing group chat.`,paragraphs:[`${e.hotelPlan} Start with exact hotel names and street addresses, because similarly named Scottsdale resorts can appear in search results. List a lobby contact for each property and tell guests whether they should wait inside or at a venue-approved pickup point. A chauffeur should never have to circle a resort while a guest finishes packing upstairs.`,"For each wave, publish one ready time and one departure time. The ready time is when guests are fully dressed, carrying everything they need, and physically present at the pickup point. The departure time is when the vehicle rolls. Put buffer between that departure and the ceremony's guest-seating deadline, not merely the invitation time, so normal loading and traffic variation do not consume the entire margin.",e.venueSpecific[2],"A transportation lead should check names against the manifest, call the designated guest contact when someone is missing, and make the go-or-hold decision. That role should not sit with the couple. Share the lead's number with the reservations team before service and choose a backup who can answer while the primary person is in the ceremony."]},{heading:`Where should a shuttle drop guests at ${e.name}?`,answer:`Use 1 venue-confirmed arrival point for each scheduled wave, written exactly as the ${e.name} event team provides it; where the venue publishes no wedding shuttle lane we confirm the live one with them instead of naming a gate, because a guessed entrance sends a full vehicle into the wrong traffic pattern.`,paragraphs:["Send the venue the vehicle type, approximate length, arrival window, and number of passengers. Ask whether the vehicle may dwell while guests unload, whether a coordinator will meet it, and whether the same point is used after the reception. If the answer changes by event space or time of day, place both instructions in the schedule with a clear effective time.","The chauffeur follows current property signage, traffic staff, and venue instructions on arrival. A static web guide cannot see a temporary barricade, private event, construction change, or emergency route. Guests should remain seated until the vehicle is in the approved unloading position, then move together toward the venue contact instead of scattering across a drive.",e.venueSpecific[3],"For older guests or anyone using a mobility device, ask the venue about its accessible route before assigning the vehicle. Vehicle capacity and property accessibility are different questions. Tell the reservations team about boarding needs early so the proposed fleet can be checked; never assume that a capacity number by itself confirms an accessible boarding setup."]},{heading:`How should ${e.name} wedding groups use separate movements?`,answer:`Separate a ${e.name} wedding day into 3 manifests when schedules differ: wedding party, immediate family, and general guests, because one all-purpose shuttle can be delayed by portraits or pre-ceremony duties while another group still needs to reach its seating time, hotel, rehearsal meal, or reception entrance.`,paragraphs:["The wedding party often carries garments, flowers, personal items, and timing responsibilities that the general guest group does not. Give that vehicle a direct contact who understands photography and ceremony cues. If partners are getting ready at different locations, write each movement as its own trip rather than describing the day as a round trip with several implied stops.","Immediate family may need a later pre-ceremony pickup and an earlier return after formal photographs. General guests benefit from the simplest possible instruction: one pickup place, one ready time, and one venue arrival. Keeping those flows separate makes the service easier to understand and gives the planner a clean way to adjust one group without rewriting every rider's plan.",e.venueSpecific[4],"If the ceremony and reception are in different spaces on the same property, confirm whether guests walk or require a vehicle transfer. Do not assume the distance or route from a property map. If off-property movement is required, schedule it explicitly and verify that every guest who arrived by shuttle also has a seat for the next leg."]},{heading:`What is the best end-of-night return plan from ${e.name}?`,answer:`Schedule 2 or 3 return windows from ${e.name} instead of one final departure: an early option for families, a primary option after major reception moments, and a last sweep after the contracted end, with every rider told which hotels are served and who authorizes an unscheduled stop.`,paragraphs:["Return demand is rarely even. Some guests want to leave after dinner, while others stay through the final song. A single departure can either strand early riders or leave a vehicle idle for hours. Staggered waves give guests a clear choice and let the planner protect the final pickup without turning the chauffeur into an on-demand dispatcher.","Write a destination list for every return wave. If multiple hotels are served, order them before the day and tell guests that the shuttle is not a private car making individual address changes. The transportation lead should record anyone who switches waves so the final sweep does not wait for a guest who already left.",e.venueSpecific[5],"Confirm where the vehicle may wait and when it should approach the pickup point. At properties with active resort traffic, arriving too early can be as disruptive as arriving late. The driver and venue contact should have each other's current instructions through the transportation lead, while guests receive a simple meeting-place description approved by the venue."]},{heading:`When should ${e.name} wedding transportation be reserved?`,answer:`Availability varies by date and by vehicle, so no fixed lead time applies: build the ${e.name} plan in 3 passes — settle the service window and pickup addresses, freeze the first manifest once RSVPs are in, then send a final update after the venue confirms access — and we confirm in writing what is open.`,paragraphs:["The first conversation should cover date, service window, pickup addresses, approximate riders, venue, and the kind of experience the couple wants. The reservations team can then identify a sensible capacity mix. A quote is more useful when it describes actual movements than when it contains only a guest total and a broad request for a shuttle.","At the RSVP checkpoint, reconcile replies with hotel lists and identify children, mobility needs, bulky items, and guests who require the early return. Confirm the venue contact and event-space name. This is also the moment to test every phone number, eliminate duplicate guest names, and make sure the planner's schedule matches the transportation schedule.",e.venueSpecific[6],`The final update should be short: approved addresses, ready and departure times, rider counts, contact hierarchy, and venue instructions. Avoid sending a fresh narrative to the driver on the wedding morning. If a true change occurs, route it through the transportation lead and reservations team so there is one acknowledged version. ${Vt}`]},{heading:`How do couples request a precise ${e.name} shuttle quote?`,answer:`A useful ${e.name} quote request includes 7 items: event date, contracted space, every pickup address, first pickup time, final return time, rider count by wave, and a transportation contact; send those details plus special boarding considerations to the reservations team at ${F} or ${M}.`,paragraphs:["Published rates provide the starting point, but the right schedule still depends on time and routing. Tell the reservations team whether the vehicle remains with the group, returns for later waves, or performs only defined transfers. Mention any airport luggage, coolers, decor, mobility devices, or oversized personal items so fit can be confirmed before a vehicle is selected.",`Ask the venue for written transportation instructions and attach them to the request. For ${e.name}, include the contracted event space and the venue coordinator's name. If the venue has not yet finalized access, say that clearly; the quote can use a planning assumption while the final dispatch sheet waits for verified directions.`,e.venueSpecific[7],"Compare the proposed seat count with the manifest, not with a rounded attendance number. A slightly larger vehicle can simplify a wave, while two smaller vehicles can protect groups with different timelines. The best answer is the one that makes the schedule resilient and understandable, not automatically the vehicle with the lowest hourly rate."]},{heading:`What are the most common ${e.name} shuttle questions?`,answer:`Most ${e.name} plans come down to 4 questions: how many people are actually riding, which hotel or home each wave leaves from, what arrival point the venue approves, and how many return times guests need; the answers below give a practical starting point for the planner.`,paragraphs:[]}],faqs:[{question:`Can a shuttle wait at ${e.name} during the wedding?`,answer:`Waiting depends on the venue's current instructions, the contracted service plan, and available staging. Ask the ${e.name} event team where a vehicle may stand, then give that direction to the reservations team before dispatch.`},{question:"Should every invited guest receive a shuttle seat?",answer:"No. Count guests who commit to each pickup and return wave, then add operational margin. Guests staying on property or driving themselves should not inflate the vehicle count."},{question:"Can airport arrivals and the wedding shuttle use the same vehicle?",answer:"Sometimes, but only when flight timing, luggage fit, and the wedding schedule align. Keep airport movements separate on the itinerary so a delayed flight cannot quietly endanger a ceremony departure."},{question:"Who should communicate with the chauffeur?",answer:"Choose one transportation lead and one backup. The couple should not manage guest calls or access changes during portraits, the ceremony, or the reception."}],links:br,sources:[{label:e.sourceLabel,href:e.sourceUrl},...e.secondarySource?[e.secondarySource]:[]]}}const wr=[$e({path:"/guides/venues/el-chorro",name:"El Chorro",address:"5550 East Lincoln Drive, Paradise Valley, Arizona 85253",venueFacts:"Its official weddings page presents multiple indoor and outdoor event spaces between Camelback and Mummy mountains.",arrivalNote:"The official site publishes the Lincoln Drive address but does not publish a named wedding-shuttle gate, so the exact unload point must come from the venue team.",hotelPlan:"Guests may be staying across Paradise Valley and Scottsdale rather than at the venue itself, so hotel consolidation matters.",sourceLabel:"El Chorro weddings and events",sourceUrl:"https://elchorro.com/weddings-and-events/",venueSpecific:["El Chorro identifies eight event spaces on its wedding materials, with indoor and outdoor choices between Camelback and Mummy mountains. Put the contracted space on every chauffeur note; the Lincoln Drive street address gets the vehicle to the property, but the space name gives the venue team the context needed to confirm the final approach.","Eight named spaces can support very different guest plans, so count riders for the actual ceremony and reception layout instead of treating El Chorro as one generic room. Ask whether the contracted spaces share an arrival area and whether guests move on foot between them before deciding that one capacity plan covers the entire celebration.","El Chorro is not a lodging property, so every guest who uses the shuttle begins somewhere else. Consolidate Paradise Valley and Scottsdale hotel riders into a small number of documented pickups, then keep private-home pickups separate when their timing or access instructions differ. This avoids turning the Lincoln Drive arrival into the first moment the manifest is reconciled.","For the Lincoln Drive approach, the useful venue answer is the approved wedding unload point for the contracted space, not a guessed entrance based on a public map. Give El Chorro the vehicle type and arrival window, record the response verbatim, and ask whether the same point remains available when the reception ends.","A wedding party assigned to one of El Chorro’s outdoor settings may have a different readiness cue from guests entering an indoor event space. Tie each manifest to a named coordinator cue and space, then state whether portraits occur before or after that movement. The chauffeur needs a departure instruction, not the entire photography schedule.","Return waves should name the destination hotels before the first vehicle approaches El Chorro. If guests are split between Paradise Valley and Scottsdale, group compatible stops and publish which wave serves each one. The last sweep should be tied to the contracted event end and the pickup instruction the venue confirms for that evening.","At the 14-day review, repeat the full El Chorro address and every contracted space name with the venue contact. Ask whether another event affects the approach, where the transportation lead should assemble riders, and when a vehicle may be called forward. Record changes in the final schedule rather than relying on an earlier email thread.","An El Chorro quote request is strongest when it names the eight-space choice actually booked, the hotel clusters, and the guest count for each direction. Include whether the ceremony and reception use different spaces and whether any passenger needs extra boarding time. Those details matter more than sending the reservations team the invitation total alone."]}),$e({path:"/guides/venues/clayton-house",name:"The Clayton House",address:"3719 North 75th Street, Scottsdale, Arizona 85251",venueFacts:"The official tourism listing describes separate event rooms, covered patios, and in-house catering and bar service.",arrivalNote:"The official tourism listing publishes the 75th Street address but does not name a wedding-shuttle curb or gate; confirm the approved unloading position with the venue.",hotelPlan:"Downtown hotels may look close on a map, yet formalwear, weather, and traffic make a scheduled pickup more dependable than asking guests to improvise.",sourceLabel:"Clayton House official venue page",sourceUrl:"https://www.wedgewoodweddings.com/venues/clayton-house",venueSpecific:["The Clayton House describes two indoor-outdoor event spaces plus in-house catering and bar service at its 75th Street property. Name the booked space in the transportation schedule so the venue can distinguish the wedding movement from a general arrival, especially when both parts of the property may be active.","A public address does not establish a shuttle loading position. Treat directions and commercial passenger unloading as separate questions: send the proposed vehicle type to The Clayton House, ask where it should approach, and keep unused seats available when formalwear, gifts, or mobility equipment affect the practical load.","Downtown Scottsdale lodging can produce several small guest clusters. Combine riders by exact hotel and ready time instead of scheduling an individual stop for every room block. A concise route into 3719 North 75th Street gives the transportation lead a realistic headcount at each pickup and leaves the chauffeur with a clear final destination.","Use the published 75th Street address as the routing anchor, then obtain the event team’s exact unloading instruction. Do not infer that the parking entrance, a nearby curb, or the closest door is approved for a larger vehicle. The venue contact should also state whether guests can remain under cover while waiting for a return wave.","Because The Clayton House offers two indoor-outdoor spaces, confirm whether wedding-party portraits, family arrival, and general guest seating all begin from the same side of the property. If they do not, write separate movements and contacts. A single vehicle can still serve multiple groups, but only when each handoff is explicit.","Do not treat nearby public parking as permission for a chauffeured vehicle to stage through the reception. Ask where an empty vehicle may wait, if waiting is allowed, and how the transportation lead should call it forward. That answer determines whether early and final return waves use one continuous booking or separate movements.","During the final review, confirm the event-space name, 75th Street address, authorized approach, and end-of-night assembly point with The Clayton House. Downtown activity can change the practical route even when the street address stays the same, so the current venue instruction and live traffic direction belong on the final chauffeur sheet.","For a Clayton House quote, list each event room only if the wedding actually uses it. Include downtown hotel names, private-home stops, and return-wave destinations, then attach the venue’s loading response. This gives the reservations team enough detail to compare one larger vehicle with coordinated smaller vehicles without assuming that a public address solves shuttle access."]}),$e({path:"/guides/venues/fairmont-scottsdale-princess",name:"Fairmont Scottsdale Princess",address:"7575 East Princess Drive, Scottsdale, Arizona 85255",venueFacts:"The official weddings page describes indoor and outdoor wedding settings and an on-property wedding planner.",arrivalNote:"Fairmont publishes driving directions that end at the lobby entrance; because a private event space may use different instructions, confirm whether the wedding shuttle should follow that public arrival route.",hotelPlan:"On-property guests and off-property guests need separate counts, and large resort grounds make the named event space especially important on the driver sheet.",sourceLabel:"Fairmont Scottsdale Princess weddings",sourceUrl:"https://www.fairmont.com/en/hotels/scottsdale/fairmont-scottsdale-princess/weddings.html",secondarySource:{label:"Fairmont location and public arrival directions",href:"https://www.fairmont.com/en/hotels/scottsdale/fairmont-scottsdale-princess/location-contact.html"},venueSpecific:["Fairmont’s public driving directions end with the lobby entrance on the right, while its wedding page describes multiple indoor and outdoor settings. Put both the contracted event space and the venue’s private-event arrival instruction on the schedule; a lobby route is useful context, but it is not automatically the wedding shuttle route.","Separate Fairmont guests staying at the resort from riders coming from other hotels or homes before choosing capacity. On-property guests may not need a seat for every movement, while an off-property party may need a fully assigned wave. The manifest should reflect committed riders rather than the total number of rooms or reception guests.","For an on-property resort wedding, the most important hotel-wave question is which guests are truly boarding off property. Give each outside hotel an exact lobby or approved pickup instruction, then create a separate note for any Fairmont guest who needs transportation within the wedding plan. Do not mix walkers into the shuttle count simply for symmetry.","Ask the Fairmont wedding planner whether the vehicle follows the published lobby approach or a different route for the contracted setting. Record the answer with the event-space name and arrival window. If staff direct the chauffeur elsewhere on the day, that current instruction controls and the transportation lead should update waiting guests before they move.","A wedding party using a Fairmont lawn or outdoor setting may have a different cue from guests entering a ballroom or other indoor space. Keep the getting-ready location and event-space name beside each movement. That prevents the driver sheet from reducing a large resort plan to the property address and one ambiguous arrival time.","For Fairmont return waves, identify which riders remain at the resort and which leave for off-property lodging. Publish only the destinations served by each departure. The transportation lead should assemble outbound guests at the venue-approved point and call the vehicle forward when the group is complete, rather than using the public lobby as an assumed waiting area.","Use the on-property wedding planner named in Fairmont’s materials as the source for the final private-event approach. Recheck the public directions and the booked-space instruction 14 days out, then confirm them again in the final update. A resort map can orient the group, but a named current instruction is what belongs in dispatch.","A Fairmont quote request should distinguish resort guests, off-property hotel riders, wedding-party movements, and end-of-night destinations. Add the contracted indoor or outdoor setting and state whether the public lobby route has been approved for the shuttle. That detail lets the reservations team price real movements instead of assuming every guest starts outside the resort."]}),$e({path:"/guides/venues/sanctuary-camelback-mountain",name:"Sanctuary Camelback Mountain",address:"5700 East McDonald Drive, Paradise Valley, Arizona 85253",venueFacts:"Its official wedding site describes mountainside indoor and outdoor settings, including lawns, terraces, a ballroom, and intimate villa options.",arrivalNote:"Sanctuary publishes its McDonald Drive address but does not name a public wedding-shuttle gate; use the event team's instructions for the booked space and arrival window.",hotelPlan:"Some guests may be staying in resort casitas or villas while others arrive from Scottsdale hotels, so identify who truly needs an off-property shuttle.",sourceLabel:"Sanctuary Camelback Mountain weddings",sourceUrl:"https://www.sanctuaryaz.com/weddings",secondarySource:{label:"Sanctuary contact and address",href:"https://www.sanctuaryaz.com/contact"},venueSpecific:["Sanctuary’s wedding materials describe lawns, terraces, a ballroom, and intimate villa options at the McDonald Drive property. Use the exact contracted setting in the vehicle notes because “Sanctuary” alone does not tell the venue team which guest path or arrival instruction applies to this wedding.","Count resort guests and off-property riders separately before selecting a vehicle for Sanctuary. A couple using a villa setting may have a smaller movement than a ballroom celebration, and some guests may already be on site. Capacity planning should follow the manifest for each wave, not a broad estimate based on the venue’s range of settings.","Paradise Valley and Scottsdale hotel pickups should be grouped by readiness and destination, while anyone already at Sanctuary remains off the inbound shuttle manifest unless a movement is specifically planned. Give each hotel one approved waiting point and keep the McDonald Drive venue arrival as the final instruction, not another place for guests to negotiate where to meet.","Sanctuary publishes 5700 East McDonald Drive but no permanent public wedding-shuttle gate. Ask the event team where the assigned vehicle should unload for the booked lawn, terrace, ballroom, or villa setting. Also ask whether the return pickup uses that same point, because arrival and late-evening traffic patterns may be handled differently.","When the wedding uses more than one Sanctuary setting, write whether guests walk between them or board for another movement. Do not infer the route or distance from a resort illustration. The wedding party may need a separate cue for portraits or preparation, while general guests should receive one simple ready time and venue-approved arrival instruction.","A Sanctuary return plan should separate guests staying on property from those returning to Paradise Valley or Scottsdale lodging. The early wave can serve family or guests leaving after dinner, while the final sweep follows the contracted event end. Each wave needs its own destination list and a venue-confirmed assembly point.","At the final planning review, repeat the booked Sanctuary setting, McDonald Drive address, arrival point, return point, and resort contact. If the ceremony moves between an outdoor and indoor option, ask whether the transportation instruction changes. Record only the answer that affects vehicle movement; do not burden the chauffeur with unrelated event details.","For a Sanctuary quote, include the contracted lawn, terrace, ballroom, or villa only as the venue identifies it, plus rider counts from each hotel and the number staying on property. Note any guest who needs extra boarding time. This creates a route-based request rather than a generic resort wedding inquiry."]}),$e({path:"/guides/venues/grand-hyatt-scottsdale-resort",name:"Grand Hyatt Scottsdale Resort",address:"7500 East Doubletree Ranch Road, Scottsdale, Arizona 85258",venueFacts:"Hyatt identifies the property as Grand Hyatt Scottsdale Resort and describes renovated ballrooms plus indoor and outdoor function space.",arrivalNote:"Hyatt publishes the Doubletree Ranch Road address but not a public wedding-shuttle gate on its event page; the booked space and arrival point should be confirmed with the resort team.",hotelPlan:"The property itself may house many guests, so separate in-resort walkers from riders coming from other hotels, homes, or the airport.",sourceLabel:"Hyatt announcement of the Grand Hyatt Scottsdale Resort name and event spaces",sourceUrl:"https://newsroom.hyatt.com/2024november11GrandHyattScottsdale",venueSpecific:["Hyatt now identifies the property as Grand Hyatt Scottsdale Resort and publishes 7500 East Doubletree Ranch Road. Use that current name on every manifest, map pin, and chauffeur note; older planning documents may still contain the former resort name, so the transportation lead should replace it before details are distributed.","Grand Hyatt lists ballrooms, lawns, gardens, and other event settings, making the contracted space essential to capacity and timing discussions. Separate guests staying at the resort from those riding in from other locations, then choose vehicles for the actual waves. The full reception attendance is not a substitute for that movement-by-movement count.","Begin hotel-wave planning by removing Grand Hyatt guests who will not ride inbound, then group off-property Scottsdale or Paradise Valley lodging by exact address and ready time. If airport luggage remains with any arriving guest, identify that movement separately. A wedding shuttle should not discover at the first pickup that a local guest wave also carries travel bags.","The Doubletree Ranch Road address routes the vehicle to Grand Hyatt, but Hyatt’s event page does not publish a wedding-shuttle gate. Ask the resort team for the approved arrival tied to the booked ballroom, lawn, or garden. Record whether the same location is used after the reception and whether a vehicle may wait nearby.","If the Grand Hyatt ceremony and reception use different settings, ask whether guests walk between them and whether the wedding party moves on a separate schedule. Keep any vehicle transfer as an explicit itinerary line with a rider count. Do not assume that every change of event space creates a transportation need or that every guest follows the wedding party.","For the return, divide guests who stay at Grand Hyatt from riders returning to other hotels, homes, or an airport-area property. A resort guest should not occupy a seat simply because their name appears on the reception list. Label each outbound wave by destination and have the transportation lead confirm who has already returned to a room.","At 14 days, verify the current Grand Hyatt name, Doubletree Ranch Road address, contracted setting, and vehicle instructions with the resort contact. Remove the former property name from guest messages unless it is needed to clarify an old document. The final update should use one naming convention so guests and chauffeurs search for the same destination.","A Grand Hyatt quote request should state how many guests stay at the resort, which off-property hotels need service, whether the ceremony and reception use separate settings, and the final return destinations. Attach the resort’s approved vehicle approach. These specifics let the reservations team evaluate the schedule without relying on the former name or a generic resort entrance."]})],vr={updatedAt:"2026-09-24",path:"/guides/scottsdale-bachelorette-weekend",title:"Scottsdale Bachelorette Party Weekend",description:"Plan a three-day Scottsdale bachelorette weekend with an Old Town crawl, published Sprinter pricing, airport transfers, and one mobile headquarters.",metaDescription:"A three-day plan: the Old Town crawl, group sizing and the nightly return",h1:"Scottsdale bachelorette party weekend: a practical 3-day itinerary",eyebrow:"Three-day Scottsdale itinerary",intro:"Scottsdale Sprinters plans a strong Scottsdale bachelorette weekend with one main plan per day, one transportation lead, and enough open time for the group to reset. This itinerary keeps Old Town stops walkable, uses a Sprinter as the mobile headquarters for longer moves, and prices the shared ride from published rates.",fleetTable:!0,itinerary:[{day:"Day 1",title:"Arrive, settle in, and start with dinner",plan:"Consolidate airport arrivals, stock the house or hotel, leave recovery time, and use one dinner reservation as the first fixed point."},{day:"Day 2",title:"Pool time, reset, and Old Town crawl",plan:"Keep the morning flexible, set one group-ready deadline, and stage the Sprinter before the first Old Town stop."},{day:"Day 3",title:"Brunch, a lighter activity, and departures",plan:"Choose one low-friction group activity, confirm luggage before pickup, and split airport waves by flight time."}],crawlStops:[{number:1,name:"A booked dinner anchor in Old Town",note:"One confirmed meal reservation before the entertainment-district portion of the night; confirm the address, time and reservation name directly with the restaurant."},{number:2,name:"The Entertainment District blocks",note:"The late venues cluster within a few blocks of Scottsdale Road and Stetson Drive; confirm current entry, cover and reservation details with each one directly."},{number:3,name:"One main celebration stop",note:"Choose a single venue for the centre of the night rather than a list, and check its current event calendar and dress guidance directly."},{number:4,name:"A quieter regrouping block",note:"The Fifth Avenue and Marshall Way shopping streets sit a short walk from the district and work as a meeting point when a line is long."},{number:5,name:"The late pickup point",note:"A lawful meeting place the chauffeur can reach, agreed before anyone leaves the last venue and sent to the whole group in writing."}],sections:[{heading:"What is the best shape for a 3-day Scottsdale bachelorette weekend?",answer:"Build the weekend around 3 anchors—arrival dinner, one main Old Town celebration, and a relaxed farewell—then protect at least 2 open blocks for pool time, getting ready, meals, and recovery, because a minute-by-minute schedule usually breaks as soon as one flight or reservation shifts.",paragraphs:["Day 1 should feel easy. Group arriving flights into a small number of airport pickup windows, give everyone time to check in, and make dinner the only hard deadline. Put the address, reservation name, ready time, and clothing plan in one shared note. Guests who land late should have a clear way to join without holding the entire group at the airport.","Day 2 carries the biggest celebration. Keep the morning optional, choose one pool or daytime reservation if the group wants it, then create a real reset window before Old Town. The transportation plan begins at the house or hotel, not at the first bar. Everyone boards together with charged phones, identification, and the items they need for the full evening.","Day 3 works best at a slower tempo. Brunch and one flexible activity give the group a final shared memory without creating another complex transfer. Organize luggage before the vehicle arrives and split airport departures by terminal timing rather than friendship groups. The person with the earliest flight should not wait through a late group brunch."]},{heading:"How does a Sprinter work as the weekend’s mobile headquarters?",answer:"A single Sprinter can serve as mobile headquarters for 8 to 16 guests by keeping the group on one departure clock, giving everyone the same pickup message, and creating a consistent regrouping point between the house, dinner, Old Town, and the final return without relying on several separate cars.",paragraphs:["“Mobile headquarters” means the transportation plan has one accountable schedule and one known vehicle; it does not mean the vehicle can wait anywhere or store unlimited belongings. The transportation lead keeps the manifest, confirms when everyone is aboard, and communicates changes to the reservations team. Guests receive the simple version: where to stand, when to be ready, and what return wave they chose.","Choose capacity from the fleet table, then discuss the real load. A nominal seat count does not describe dresses, coolers, welcome bags, airport luggage, or mobility devices. The reservations team can help check the proposed vehicle against those details. For a nightlife-only movement, a party-oriented Sprinter may fit the mood; for airport transfers, luggage can change the practical answer.","The vehicle is most valuable on the longer or less walkable legs: airport to lodging, lodging to Old Town, a planned daytime destination, and the final ride home. Inside a compact Old Town crawl, walking between confirmed nearby stops can be simpler than repeatedly loading the group. The chauffeur should use only legal, currently available loading places."]},{heading:"What does a Scottsdale Sprinter cost per person?",answer:`For 13 guests sharing the ${n["ultra-luxury-party-sprinter-scottsdale"]} for 5 billed hours, the published ${Oa("ultra-luxury-party-sprinter-scottsdale")}-per-hour rate works out to about ${qa("ultra-luxury-party-sprinter-scottsdale",5,13)} per person before tax for the shared ride; the live total depends on the selected vehicle, service duration, and confirmed itinerary.`,paragraphs:["The calculation is deliberately transparent: the published hourly rate is multiplied by 5 billed hours and divided by 13 riders. If fewer people split the same vehicle, the per-person amount rises; if the group chooses a different vehicle or service window, it changes. Use the fleet table as a planning comparison, then request a quote for the actual route.","Do not compare a group vehicle with a single app estimate shown before a surge, a stop, or a post-event pickup. The useful comparison includes how many separate cars the group would need, whether everyone departs together, and who is responsible for finding missing riders. A shared hourly plan buys coordination as well as seats.","The itinerary should separate airport service from the nightlife service when the timing or luggage profile differs. A vehicle that fits the celebration may not be the best airport loadout. Send flight waves and luggage notes to the reservations team so each portion can be priced against the right vehicle rather than forcing one assumption across the entire weekend."]},{heading:"How should a practical Old Town crawl be sequenced?",answer:"Sequence the night in 3 moves—a booked dinner anchor, one main stop inside the Entertainment District, and a late pickup point the chauffeur can legally reach—then confirm reservations, dress rules, event programming, and entry conditions directly with each venue, because those conditions change without notice.",paragraphs:["The numbered route below is a planning sequence, not a promise of admission or a claim that every stop belongs in one night. A dinner reservation works as the meal anchor when booked directly. The late venues sit in the Entertainment District and are listed in Old Town Scottsdale’s official nightlife directory. No district claim or operating hours are assigned to any stop here.","Book the most important reservation first, then build around it. If the group cares about dinner or a particular evening’s programming, confirm that directly with the venue. Keep confirmation emails and the reservation name in the shared plan. A transportation booking does not create venue admission, skip a line, or override dress and identification requirements.","Designate a regrouping point before entering a loud venue. The group should know what happens if someone leaves early or cannot be reached. Do not ask a chauffeur to stop in an unapproved travel lane while the group decides. The transportation lead should call the movement only after guests are together and the driver confirms the legal pickup position."]},{heading:"How should the Old Town pickup and return be planned?",answer:"Use 2 written meeting points: a venue-confirmed arrival location and a separate late-night pickup location that the chauffeur can legally reach, then set one primary departure time plus a backup contact, because crowded streets and changing traffic controls make an improvised curbside search unreliable.",paragraphs:["Old Town is compact, but the entertainment district can be busy. The exact pickup point should be confirmed on the service day based on current traffic and venue instructions. This guide does not invent a club gate or claim a permanent shuttle lane. Guests should expect a short walk to a lawful meeting point if streets are restricted or congested.","Share a map pin only after the chauffeur or dispatch contact has confirmed it. A pin dropped by a guest from inside a building can land on an alley, patio, or wrong side of the block. The transportation lead should send the final location to the group and collect everyone there before calling the driver forward.","Choose the return rule before the night begins. If the group books one final departure, say clearly that leaving earlier requires a separate plan. If two waves are scheduled, assign riders in advance and record switches. The bride should never be the person counting heads on a crowded sidewalk while also trying to enjoy the celebration."]},{heading:"What should the group pack, assign, and confirm?",answer:"Give 1 person the master itinerary and assign 3 backups—lodging contact, reservation contact, and transportation contact—while every guest carries identification, a charged phone, the lodging address, and weather-appropriate basics, so one lost device or delayed guest does not stop the entire weekend plan.",paragraphs:["Keep the master itinerary short enough to use. It should show addresses, reservation names, ready times, departure times, and the transportation lead. Put optional activities in a separate section so guests can distinguish the fixed plan from suggestions. Avoid a long group-chat thread as the only source of truth; important information disappears quickly once travel begins.","For airport day, label bags and tell the reservations team the real luggage count. For nightlife, reduce what guests carry and confirm each venue’s current bag rules directly. Do not leave valuables or essential medication in a vehicle on the assumption that the same vehicle will remain in the same place all night.","Scottsdale conditions vary by season and time of day. Check an official forecast close to the weekend and plan water, sun protection, or a layer as appropriate. The group should also agree on a buddy system and a simple decision rule: no one changes venue alone without telling the transportation lead or their assigned buddy."]},{heading:"When should the weekend transportation be booked?",answer:"Availability varies by date and by vehicle, so no fixed lead time applies: work the manifest in 3 passes — confirm the flight waves once the group has booked flights, recheck lodging and venue details as they are fixed, then send the final passenger list 48 hours before service.",paragraphs:["Start with the pieces that are unlikely to change: travel dates, lodging, the main celebration night, estimated group size, and desired service window. The reservations team can recommend a fleet option from those facts. You do not need every brunch selected before asking, but you do need honest timing and a realistic pickup area.","Once flights are booked, collect them in a spreadsheet and group arrivals by a useful window. Confirm the exact lodging address, including unit or building instructions that the property permits you to share. Recheck every major venue reservation and current entry guidance. This is the point to decide whether one airport vehicle can serve everyone or separate waves are necessary.",`Forty-eight hours out, send a clean operational summary rather than forwarding the whole planning chat. Include named contacts, rider count, luggage note, ready times, addresses, and the confirmed Old Town meeting plan. If something changes afterward, have one person notify the reservations team and wait for acknowledgement before telling the group the plan is final. ${Vt}`]},{heading:"What are the most common bachelorette transportation questions?",answer:"Most groups ask 4 things: whether one Sprinter can cover airport and nightlife service, how per-person pricing is calculated, where an Old Town pickup can happen, and how late changes are handled; the answers below keep those decisions tied to the real manifest and confirmed itinerary.",paragraphs:[]}],faqs:[{question:"Can one vehicle handle the whole weekend?",answer:"It can cover several scheduled movements, but airport luggage, service gaps, and different group sizes may make separate bookings more practical. Share the complete itinerary with the reservations team."},{question:"Does the transportation reservation include club admission?",answer:"No. Venue reservations, admission, identification, dress rules, and event passes are separate. Confirm them directly with each official venue."},{question:"Can the group add stops during the night?",answer:"Ask the reservations team before service and route day-of requests through the transportation lead. A new stop must fit the booked time, legal access, and driver instructions."},{question:"Where does the Sprinter pick up in Old Town?",answer:"The exact lawful meeting point is confirmed for the service plan and current conditions. This guide intentionally does not promise a permanent curb or invented venue gate."}],links:[{href:"/experiences/bachelorette-party",label:"Bachelorette party transportation"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter van rental"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:"Ultra Luxury Party Sprinter"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport Sprinter service"},{href:"/pricing",label:"Hourly and per-person pricing"}],sources:[{label:"Old Town Scottsdale nightlife directory",href:"https://oldtownscottsdaleaz.com/eat-drink/nightlife/"}]};function Xt(e){const t=e.article?`${e.article} ${e.name}`:e.name;return{path:e.path,updatedAt:e.updatedAt,title:`${e.name} Transportation Guide | Scottsdale Sprinters`,description:`Plan ${e.name} group transportation with the official date status, published fleet capacities, hotel pickup, arrival, and post-event pickup guidance.`,metaDescription:"Official date status, hotel pickup, venue arrival and the post-event pickup plan",h1:`${e.name} group transportation`,eyebrow:e.dateLine,intro:`A dependable ${e.name} ride from Scottsdale Sprinters begins with the official event information, a realistic rider count, and one transportation lead. This guide uses published organizer or venue facts, leaves unannounced details unguessed, and turns the day into a written pickup, arrival, communication and return plan.`,fleetTable:!0,sections:[{heading:`When is ${t}?`,answer:e.dateAnswer,paragraphs:["Use the official source linked below as the date authority. Artist schedules, participating teams, kickoff times, venue hours, and traffic instructions may arrive later than the date itself. Do not build a pickup plan around an unofficial calendar listing. The transportation lead should recheck the organizer page at booking, again as the date approaches, and on the service day.",e.eventSpecific[0],"Publishing early matters because a large-event route needs more than a car reservation. The group may still need admission passes, lodging, a meeting point, and agreement about who rides home. An article published ahead of the event gives planners time to compare vehicle sizes, collect guest commitments, and confirm current access rules without inventing details.","When a date or time remains unannounced, the quote request can still describe the expected city, group size, hotel area, and service pattern. Mark uncertain times as planning placeholders, not confirmed instructions. The reservations team can update the service window once the official organizer publishes the missing information."]},{heading:`Which vehicle size fits a ${e.name} group?`,answer:`For ${t}, compare the published capacity bands from ${j[0].capacity} through ${j[j.length-1].capacity} passengers, then choose from the committed rider count and what the group will carry; the largest seat number is not automatically the best choice when people have permitted gear, accessibility needs, or hotel luggage.`,paragraphs:[`The fleet table uses current published information for each displayed name, maximum seated capacity, hourly rate, and minimum. A ${n["executive-sprinter-scottsdale"]} seats ${c["executive-sprinter-scottsdale"]}; a ${n["motorcoach-56"]} seats ${c["motorcoach-56"]}. Larger groups can use multiple coordinated vehicles when one vehicle does not fit the rider count or what guests will carry.`,"Count the riders for each direction. The outbound group may be larger than the return group, especially when some guests camp, stay near the venue, or leave with family. Give every return rider a specific vehicle or wave. “We will decide later” is not a useful manifest when a large event crowd is leaving at once.",e.eventSpecific[1],"Tell the reservations team about permitted personal items before choosing the vehicle. Event bag and chair rules belong to the organizer, and vehicle fit belongs to the operator. Something allowed into the venue may still consume meaningful cabin space. Keep aisles and exits clear, and never use an advertised seat count as a substitute for a real load review."]},{heading:`How should a group arrive at ${e.venue}?`,answer:`Plan 1 documented arrival route to ${e.venue}, with the chauffeur following current event staff, traffic control, and the organizer's published instructions; a saved gate name from an earlier event is not reliable enough for dispatch, so this guide uses only access details supported by an official source.`,paragraphs:[`${e.verifiedAccess} The operational plan should record the venue as ${e.venueAddress}, plus any event-specific permit, lot, or loading instruction supplied for the booked vehicle. If an organizer later publishes a different route, that current instruction replaces the general address.`,e.eventSpecific[2],"Build arrival buffer before the first activity the group cares about, not merely before the headline start. Loading riders, traffic control, security screening, and the walk from the approved unload area all take time. The vehicle cannot bypass public safety instructions, and the group should not ask to unload in a travel lane because the schedule ran tight.","Keep admission passes, identification, and allowed personal items ready before the door opens. The transportation lead counts riders as they leave and identifies the return meeting plan once more. Nobody should assume that the arrival position will remain the pickup position after the event; traffic plans can reverse or move during egress."]},{heading:`What should the ${e.name} itinerary include?`,answer:`Write 7 lines into the ${e.name} itinerary: guest ready time, vehicle departure, venue arrival target, primary contact, official address, post-event meeting instructions, and final roll time, then keep optional meals or gatherings in a separate section so riders can immediately see the commitments that affect transportation.`,paragraphs:[`${e.dayPlan} Turn that outline into clock times only after official hours or kickoff information is available. A useful schedule works backward from the desired arrival, adding expected loading and a conservative traffic allowance. Avoid publishing a universal drive time because origin, closures, day of week, and event operations all change it.`,e.eventSpecific[3],"The ready time is when guests are physically at the pickup point with everything they will take. It is not the time they begin leaving hotel rooms. The transportation lead should arrive earlier, check the manifest, and contact missing riders. Decide in advance who has authority to hold the vehicle and how long the schedule can absorb that hold.","Include one contingency sentence: if the group becomes separated, each rider follows the written meeting instruction and contacts the transportation lead. Do not create multiple competing pins during the event. A simple, approved plan is easier to execute when cellular service is busy and the surrounding streets are controlled."]},{heading:`How should pickup after ${t} work?`,answer:`Use 2 checkpoints after ${t}: the group first gathers at a pedestrian meeting place permitted by venue instructions, then the transportation lead confirms the vehicle’s active pickup point before anyone walks toward it, preventing riders from chasing a moving vehicle through controlled traffic or crowd flow.`,paragraphs:["The chauffeur may be directed away from the arrival location or held until traffic staff release a lane. That is normal large-event operations, not a reason for guests to enter a roadway. The lead stays with the group, keeps a headcount, and waits for a confirmed message about where and when to move.","Set expectations before arrival: the vehicle cannot stop wherever a phone pin lands, and an event's official traffic team controls access. Guests should wear appropriate footwear for the walk they can reasonably expect around a large venue and keep enough phone charge for post-event messages. Anyone leaving separately tells the transportation lead.",e.eventSpecific[4],"For multiple return waves, label vehicles and destinations clearly. A hotel shuttle and a local-home shuttle should not rely on guests recognizing a driver in a crowd. Use the vehicle name, lead name, and destination list. The final sweep verifies the manifest before departure rather than waiting on people who changed plans without notice."]},{heading:`How far ahead should ${e.name} transportation be reserved?`,answer:`Availability for ${t} varies by date and by vehicle, so no fixed lead time applies: request a current quote with the rider count, hotel area and service pattern, and the reservations team confirms in writing what is open across the published capacity bands from ${j[0].capacity} to ${j[j.length-1].capacity} passengers, updating it as official information is announced.`,paragraphs:["The first request needs the event, lodging or pickup area, likely passenger count, desired arrival, and return concept. A group does not need every attendee name to begin, but it should distinguish committed riders from possible riders. The reservations team can compare a single larger vehicle with several coordinated smaller options using current published capacities.","Once the group is committed, close the manifest and collect mobility needs, allowed gear, and destination choices. Confirm the official event status and make sure every rider has an admission plan independent of transportation. If the organizer has not announced an important detail, mark it open and assign one person to monitor the official source.",e.eventSpecific[5],"During the final 48 hours, verify addresses, contact numbers, service times, and current venue directions. Send one final summary to riders. If official instructions change on the day, the chauffeur follows traffic personnel and the transportation lead relays the update; the group should not treat an older screenshot as authority over current controls."]},{heading:`How is ${e.name} transportation priced per person?`,answer:`For 12 ${e.name} riders sharing the ${n["executive-sprinter-scottsdale"]} across 5 billed hours, the published ${Oa("executive-sprinter-scottsdale")}-per-hour rate is about ${qa("executive-sprinter-scottsdale",5,12)} per person before tax for the complete shared ride; actual pricing changes with the vehicle, duration, itinerary, and confirmed service plan.`,paragraphs:["That example is arithmetic, not a flat event fare: hourly rate multiplied by billed hours, divided by riders. It gives a group a common basis for comparison while staying aligned with the published rate. If only ten people ride, divide across ten. If the group needs a larger vehicle or a longer service window, request the matching calculation.","A complete plan may include a continuous vehicle, separated inbound and outbound transfers, or several hotel waves. Each structure uses time differently. Describe the actual service pattern when asking for a quote instead of requesting “round trip” and leaving a many-hour gap unexplained. The reservations team can then price the schedule that the group expects.",e.eventSpecific[6],"Per-person math is most useful after the rider list stabilizes. Name one person to collect shares and one person to manage the manifest; they can be the same person, but neither job should fall to the chauffeur. The transportation service moves the confirmed group while the lead owns internal guest decisions."]},{heading:`What are the most common ${e.name} transportation questions?`,answer:`Most ${e.name} groups need 4 answers before booking: the official date status, the number of committed riders, the venue's current vehicle instructions, and the return meeting process; the FAQ below addresses those points without promising an unpublished time, access route, parking privilege, or gate.`,paragraphs:[]}],faqs:[{question:`Does a transportation booking include ${e.name} admission?`,answer:"No. Admission passes, wristbands, parking credentials, and venue entry are separate. Purchase and verify them only through the event’s official channels."},{question:"Can the vehicle wait next to the venue?",answer:"Only where current event operations permit it. Staging and pickup instructions can change, so the chauffeur follows venue staff and the transportation lead shares the confirmed meeting plan."},{question:"Can a group bring chairs, coolers, or bags?",answer:"Check the organizer’s current allowed-items policy first, then tell the reservations team exactly what the group will carry so vehicle fit can be reviewed."},{question:"What if the official event time changes?",answer:"Have the transportation lead contact the reservations team promptly. A revised service window is not assumed until the change is acknowledged and the updated plan is confirmed."}],links:[...e.links,{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:[e.source,e.accessSource,...e.additionalSources??[]]}}const kr=[Xt({updatedAt:"2026-09-18",path:"/guides/country-thunder-transportation",name:"Country Thunder Arizona",titleName:"Country Thunder Arizona 2027",dateLine:"Official dates: April 8–11, 2027",dateAnswer:"Country Thunder Arizona is officially scheduled for April 8–11, 2027—4 festival days at AZ Talio Ranch in Florence—and the organizer says 2027 hours will be announced closer to the festival, so build transportation around the published dates but wait for official daily times before locking departures.",venue:"AZ Talio Ranch",venueAddress:"20585 East Water Way, Florence, Arizona 85132",verifiedAccess:"Country Thunder’s official information page publishes the ranch address, advises fans that onsite parking is limited, and directs everyone to follow current event information.",dayPlan:"For a festival day, the outline is hotel pickup, comfort stop if scheduled, venue arrival, a written post-show regrouping process, and the return to the named lodging stops.",source:{label:"Country Thunder Arizona official 2027 event page",href:"https://www.countrythunder.com/az"},accessSource:{label:"Country Thunder Arizona official festival information",href:"https://www.countrythunder.com/az-info"},links:[{href:"/experiences/country-thunder",label:"Country Thunder transportation experience"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/fleet/party-bus-28-scottsdale",label:"28-passenger party bus"}],eventSpecific:["Country Thunder publishes four festival dates but says the 2027 hours will be announced closer to the event. Keep each daily departure in draft until those hours appear, and do not assume that one day’s timing applies to the next. The transportation lead should recheck the Arizona event page for every day the group plans to attend.","A Country Thunder group may carry only items allowed by the festival, and any permitted chair, bag, or personal item still consumes vehicle space. Count those items before selecting from the published capacities. A vehicle that fits riders for a Scottsdale night out may require a different load review for a four-day festival plan in Florence.","The official destination is AZ Talio Ranch at 20585 East Water Way in Florence, and the festival warns that onsite parking is limited. That statement does not create a commercial drop-off privilege. Send the current event instructions to the reservations team, document the assigned arrival process, and follow staff direction when the vehicle reaches the ranch.","A four-day Country Thunder plan should be written as four separate service days even if the same group attends each one. Rider counts, readiness, permitted items, and return choices can change by day. Label every schedule with the correct date so an unannounced daily hour can be inserted later without silently changing another day’s plan.","After each Country Thunder day, the group should assemble at the pedestrian point allowed by current festival instructions before the vehicle is called forward. Ranch access and event traffic may keep a vehicle away from the place used at arrival. The lead should send one confirmed group-status message and prevent separate riders from distributing competing map pins.","At the 14-day review, check whether Country Thunder has published the 2027 daily hours and any updated transportation or allowed-items information. If a detail remains unannounced, leave it clearly open and tell riders when it will be checked again. The official Arizona page, not a recycled itinerary from an earlier festival, controls the planning facts.","Price each Country Thunder service window from the lodging pickup through the confirmed return plan. A group attending multiple days should not multiply one day’s estimate without checking whether the hours, riders, and vehicle remain the same. Send the reservations team a date-by-date outline so the written quote reflects the actual festival schedule requested."]}),Xt({updatedAt:"2026-09-24",path:"/guides/fiesta-bowl-transportation",name:"Fiesta Bowl",article:"the",titleName:"Fiesta Bowl 2026-27",dateLine:"Official date: December 30, 2026",dateAnswer:"The 2026-27 Vrbo Fiesta Bowl is the CFP quarterfinal on Wednesday, December 30, 2026, at 5:30 pm Arizona time at State Farm Stadium in Glendale, so planners can anchor the service date now and should recheck the official page before confirming pickup times.",venue:"State Farm Stadium",venueAddress:"1 Cardinals Drive, Glendale, Arizona 85305",verifiedAccess:"The official 2026-27 Fiesta Bowl parking map and State Farm Stadium’s directions page both identify the Black Lot for rideshare. That published rideshare point is a planning reference, not a commercial-vehicle assignment; a charter drop-off for this game is announced closer to the date, and traffic staff remain controlling.",dayPlan:"For game day, the outline is hotel pickup, an optional pregame stop only if scheduled, arrival ahead of the 5:30 p.m. Arizona kickoff, a security and admission buffer, a postgame pedestrian regrouping point, and the confirmed vehicle pickup.",source:{label:"College Football Playoff Fiesta Bowl schedule",href:"https://collegefootballplayoff.com/sports/2021/9/7/fiesta-bowl"},accessSource:{label:"State Farm Stadium directions and parking",href:"https://www.statefarmstadium.com/plan-your-visit/directions-parking"},additionalSources:[{label:"Fiesta Sports Foundation 2026-27 CFP dates",href:"https://www.fiestasportsfoundation.org/news/2026/7/9/vrbo-fiesta-bowl-announces-dates-to-host-college-football-playoff-matchups-through-2032.aspx"},{label:"Fiesta Sports Foundation 2026-27 parking map",href:"https://www.fiestasportsfoundation.org/documents/2026/8/14/26-27_VFB_Parking_Map_FINAL.pdf"},{label:"Fiesta Sports Foundation Fiesta Bowl Parade",href:"https://www.fiestasportsfoundation.org/sports/2019/10/22/fiesta-bowl-parade.aspx"}],links:[{href:"/services/scottsdale-executive-minibus-group-shuttle",label:"Scottsdale group shuttle service"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter rental"},{href:"/fleet/executive-mini-bus-26-scottsdale",label:"24-passenger mini bus"}],eventSpecific:["Fiesta Sports Foundation schedules this game as the CFP quarterfinal on Wednesday, December 30, 2026, at 5:30 pm Arizona time at State Farm Stadium. The College Football Playoff lists that same kickoff as 7:30 p.m. ET, because Arizona does not observe daylight saving time. Recheck both official pages if the organizer updates event information.","A Fiesta Bowl group usually needs one count for the stadium arrival and another for the return. Remove anyone using a separate postgame plan before assigning seats, and ask about mobility devices or personal items that affect fit. The vehicle choice should follow those confirmed movements, not the number of people included in a broader game-day gathering.","The official 2026-27 parking map places rideshare on the Black Lot, and the stadium directions page also names the Black Lot south of the stadium for rideshare and family-or-friend pickup. A limo or charter drop-off for this game is announced closer to the date. Use the Black Lot as rideshare orientation until the reservations team confirms the instruction for the booked vehicle.","Build the December 30 itinerary backward from the 5:30 p.m. Arizona kickoff at 1 Cardinals Drive in Glendale. If the group also wants the parade, schedule it as its own service: Saturday, January 2, 2027, at 10 a.m., starting at Central and Montebello in Phoenix, after the game. The 2027 parade route, grandstands, and street closures are announced closer to the date.","Postgame traffic at State Farm Stadium can be directed differently from arrival, so the lead should not send the group toward the Black Lot until the active pickup instruction is confirmed. Assemble first in a safe pedestrian place permitted by venue guidance, complete the headcount, and move only after the vehicle location and route are understood.","Before the Fiesta Bowl, confirm the December 30 date, the 5:30 p.m. Arizona kickoff, hotel addresses, the rider list, and the 2026-27 parking map. During the final 48 hours, recheck the Fiesta Sports Foundation and stadium pages. Live direction from stadium staff takes precedence over a saved map. January 2 parade closures are announced closer to the date.","A Fiesta Bowl quote should state whether the vehicle remains with the group, performs separate inbound and outbound transfers, or serves more than one hotel wave. Price examples based on five hours are comparisons only; the written quote must reflect the December 30 schedule, confirmed stadium access, rider count, and actual time requested."]})],Sr=[vr,...wr,...kr];function Ar(e){return{path:e.path,title:e.h1,metaTitle:e.title,description:e.description,intro:e.intro,metaDescription:e.metaDescription,lastUpdated:e.updatedAt??Qt,lastUpdatedLabel:T(e.updatedAt??Qt),sections:e.sections.map(t=>({question:t.heading,answer:t.answer,paragraphs:[...t.paragraphs,...t.bullets??[]]})),faqs:e.faqs,links:e.links,sources:e.sources,eyebrow:e.eyebrow,fleetRows:e.fleetTable?j:void 0,itinerary:e.itinerary,crawlStops:e.crawlStops}}const Ns=Sr.map(Ar),ea="2026-09-24",Tr="https://www.barrett-jackson.com/2027-scottsdale",$r="https://calendar.westworldaz.com/scottsdaleaz_westworld/260203141",st={collectors:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],crews:["executive-sprinter-scottsdale","limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],corporate:["executive-luxury-bus-29-scottsdale","executive-mini-bus-26-scottsdale","party-bus-28-scottsdale"]},Cr=[...st.collectors,...st.crews,...st.corporate].filter(ge),Ha=Cr.map(e=>({slug:e,name:n[e],capacity:c[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),se="executive-sprinter-scottsdale",I="maybach-jet-sprinter-scottsdale",He="motorcoach-56",ta="ultra-luxury-party-sprinter-scottsdale",We="maybach-shuttle-sprinter-8",Ge="premium-suv-scottsdale",Pr="limo-sprinter-13-scottsdale",Fr="limo-sprinter-16-scottsdale",Mr="executive-luxury-bus-29-scottsdale",Er="executive-mini-bus-26-scottsdale",Dr="party-bus-28-scottsdale",Rr=Math.max(...Ha.map(e=>e.capacity)),za="Your chauffeur waits; extra time is billed hourly at the vehicle’s rate — just call or text us to extend.";function it(e){return g(s[e].hourlyRateCents)}function Ir(e,t,a){return g(Math.round(s[e].hourlyRateCents*t/a))}function K(e,t,...a){return{question:e,answer:t,paragraphs:a}}const xr=[{label:"Barrett-Jackson 2027 Scottsdale official event page",href:Tr},{label:"City of Scottsdale WestWorld calendar, Barrett-Jackson 2027",href:$r}],Wr=[K("When is Barrett-Jackson Scottsdale 2027?","Barrett-Jackson Scottsdale runs Saturday, January 23 through Sunday, January 31, 2027, which is 9 public days at WestWorld of Scottsdale, with gates, food courts and sponsor displays open from 8:00 a.m. until auction close, plus an invitation-only Opening Night Gala on Friday, January 22, 2027, from 7:00 to 10:00 p.m.","Use the Barrett-Jackson 2027 Scottsdale page as the date authority. The City of Scottsdale WestWorld calendar lists the same Saturday, January 23 through Sunday, January 31 window. The city calendar shows a 10:00 a.m. start; the organizer’s own schedule says gates, food courts and sponsor displays open at 8:00 a.m. until auction close every day of those 9 days. Plan departures from the organizer’s 8:00 a.m. gate time, and recheck that page before the service day.","The Opening Night Gala is Friday, January 22, 2027, from 7:00 to 10:00 p.m., by invitation only in the Auction Arena. It is not a public gate day. A group attending the gala needs its own invitation and a separate service window from the public days that start the next morning. Do not treat January 22 as a day the general-admission crowd can enter.","The organizer says 2027 is 9 days of live auction action, with over 2,000 collector vehicles on display, an exhibitor marketplace, thrill rides and more. Daily auction close times, and which days the docket runs, are announced closer to the date. The venue map, travel notes, featured list and sponsors tab are also announced closer to the date. Mark those as open items rather than copying a prior year’s schedule.","A quote can still name the city, the hotel area, the rider count and whether the group is attending one day or several of the 9. Unannounced close times stay placeholders until Barrett-Jackson publishes them. The reservations team updates the service window from that page, not from a recycled itinerary."),K("Which vehicle fits a Barrett-Jackson collector or hospitality group?",`Collectors and VIP groups lead with the ${n[I]}, which seats ${c[I]}, then the ${n[ta]}, the ${n[We]} and the ${n[Ge]}; friends and bidder crews ride the ${n[se]} or a Limo Party Sprinter; corporate hosts and big groups take the mini coach, the mini bus or the party bus.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Collectors and VIP: the ${n[I]}, our pick for Barrett-Jackson, seats ${c[I]} at ${it(I)}/hr, then the ${n[ta]}, the ${n[We]} and the ${n[Ge]}. Friends and bidder crews: the ${n[se]}, the ${n[Pr]} and the ${n[Fr]}. Corporate hosts and big groups: the ${n[Mr]}, the ${n[Er]} and the ${n[Dr]}.`,`A VIP party larger than the ${n[I]} rides in two vehicles, one booking each for the same day and times: the ${n[I]} with the ${n[We]} seats ${c[I]+c[We]}, and with the ${n[Ge]} it seats ${c[I]+c[Ge]}. The largest vehicle in the table seats ${Rr}; for a bigger party the reservations team quotes two or more vehicles together.`,"Count riders for each direction. A morning arrival at the 8:00 a.m. gate and an evening return after auction close are often different lists. Someone who leaves with another host, or who stays for a later lot, should come off the return manifest before seats are assigned. “We will decide at the arena” is not a useful count when the grounds are releasing traffic.","Tell the reservations team which group is riding, collectors and VIP, a bidder crew or a corporate host party, so the written quote starts from that group’s vehicles.","Tell the reservations team what the group will carry before the vehicle is chosen. The organizer checks every bag and screens guests. A clear bag that the gate allows can still take a seat or an aisle. Seat counts are seated capacities, not a promise that coolers, display materials or extra coats will fit. Coolers are prohibited on the grounds."),K("How does parking work at Barrett-Jackson Scottsdale 2027?","Barrett-Jackson Scottsdale 2027 has plenty of complimentary public parking at WestWorld of Scottsdale, 16601 North Pima Road, with shuttles to and from the main gate and valet for a fee; rideshares use the McDowell Mountain Ranch Road lot, and with a chauffeured ride nobody in the group drives or parks: the chauffeur unloads where event staff direct.","Barrett-Jackson publishes plenty of complimentary public parking. Follow the road signs to parking. Shuttles run to and from the Scottsdale auction’s main gate. Valet parking is available for a fee. That is the official parking plan: complimentary public parking with shuttles, plus paid valet. It is not a statement that a booked commercial vehicle may unload at the arena door.","Rideshare drop-off and pick-up use the parking lot west of Thompson Peak Parkway on McDowell Mountain Ranch Road. Follow the signs to the rideshare area. That lot is the published rideshare point. It is not, by itself, a commercial-vehicle privilege. A chauffeured coach or Sprinter still needs the current event instruction, which for a limo, charter or commercial drop-off is announced closer to the date.","No city traffic plan or Pima Road closure list for 2027 is published yet. Those controls are announced closer to the date. Until then the address is the routing anchor: 16601 North Pima Road, Scottsdale, AZ 85260. If Barrett-Jackson or the city later publishes a credential, a lot or a loading lane, that current instruction replaces this general address for the booked vehicle.","Build the buffer before the group wants to be inside, not merely before the property line. Gates open at 8:00 a.m. Loading, the approach, security screening and the walk from the authorized unload point all take time. The vehicle cannot bypass traffic staff, and the group should not ask to unload in a travel lane because the schedule ran tight."),K("What should the Barrett-Jackson day plan include?","Write 7 lines into the Barrett-Jackson day plan: guest ready time, vehicle departure, the 8:00 a.m. gate target, a primary contact, the WestWorld address, the return meeting rule, and a final roll time, and keep meals or client entertainment on separate lines so riders can see what actually moves the vehicle.","A public day runs from the 8:00 a.m. gate until auction close. Auction close itself is announced closer to the date, so the return clock stays a placeholder until the organizer publishes that day’s end. Work backward from the arrival the group wants, add loading time, and do not print one drive time for every Scottsdale hotel. Origin, day of week and event operations all change it.","The ready time is when guests are at the pickup point with tickets, identification and the bag they will carry through screening. It is not the moment they start getting dressed. The transportation lead arrives earlier, checks the manifest and calls anyone missing. Decide in advance who may hold the vehicle and for how long.","Most of the site is climate-controlled. The Performance Track thrill rides and hot laps are outdoors, for ages 8 and up or guests at least 48 inches tall. If the group includes children who will ride, say so on the itinerary so the return is not planned around an activity they cannot enter. General-admission tickets are sold online and at the on-site AXS box office, and general admission does not guarantee arena seating.","One contingency line belongs on the sheet: if the group splits, each rider follows the written meeting instruction and contacts the transportation lead. Do not create several competing pins during the auction. A single approved plan is easier to run when the grounds are busy and cellular service is uneven."),K("How should pickup after Barrett-Jackson work?","Use 2 checkpoints after Barrett-Jackson: the group gathers first at a pedestrian point the current instructions allow, then the transportation lead confirms the vehicle’s active pickup before anyone walks toward traffic, because a commercial loading lane is announced closer to the date and the arrival curb may not be the departure curb.",`What if the auction runs late? ${za}`,"The published rideshare lot, west of Thompson Peak Parkway on McDowell Mountain Ranch Road, is the official place rideshare guests request a car. A booked Sprinter, Maybach or motorcoach follows venue staff and the instruction confirmed for that vehicle. Guests should not walk into a roadway to chase a phone pin. The lead keeps the headcount and waits for a confirmed place to move.","Set the expectation before arrival. The vehicle cannot stop wherever a pin lands, and event traffic staff control access. Comfortable shoes matter for the walk from the shuttle or the authorized curb. Anyone leaving separately tells the transportation lead so the return manifest stays accurate.","For more than one return wave, label the vehicle, the lead and the hotel. A collector group heading to one resort and a hospitality group heading to another should not rely on recognizing a driver in a crowd. The final sweep checks the manifest before the vehicle rolls, rather than waiting on people who changed plans without notice."),K("What can guests bring, and what is the gate like?","The 2027 gate allows 3 bag shapes: a clutch up to 6.5 by 4.5 inches, a clear bag up to 12 by 6 by 12 inches, or a 1-gallon clear bag, and every bag is checked while guests are screened; weapons, video cameras, skateboards, drones, coolers and animals are prohibited, with licensed service animals allowed.","One sealed water bottle under 17 ounces per person is the published drink allowance. The event is cashless except for certain food concessions and valet parking. Bring the payment method those concessions and the valet booth will take, and do not plan to pay the gate or a food stand with cash unless that stand is one of the exceptions the organizer names.","Admission is separate from transportation. General-admission tickets are sold online and at the on-site AXS box office. General admission does not guarantee a seat in the arena. Buy and verify tickets only through Barrett-Jackson’s official channels. A vehicle booking does not include a credential, a parking pass or an invitation to the January 22 gala.","If an allowed-items rule changes, the organizer’s current page replaces this summary. Send the reservations team the exact list the group will carry so vehicle fit can be reviewed against that list. Something the gate permits can still be a poor fit in the cabin."),K("How far ahead should Barrett-Jackson transportation be requested?","Availability for Barrett-Jackson varies by date and by vehicle, so no fixed lead time applies: request a current quote with the rider count, hotel area and which of the 9 days you need, and the reservations team confirms what is open across the vehicles listed, updating the plan as Barrett-Jackson announces the remaining details closer to the date.","The first request needs the days, the lodging or pickup area, the likely passenger count, the desired arrival against the 8:00 a.m. gate, and the return concept. A group does not need every name to begin. It does need to separate committed riders from possible ones, and to say which group is riding: collectors and VIP, a bidder crew, or a corporate host party.","Once the group is committed, close the manifest and collect mobility needs and the bags that will go through screening. Confirm that every rider has an admission plan of their own. If the docket, the auction close or the commercial loading lane is still announced closer to the date, leave that line open and name one person to recheck the official page.",`During the final 48 hours, verify addresses, contact numbers and the newest Barrett-Jackson directions. Send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${F} or ${M}. An older screenshot does not outrank the current control.`),K("How is Barrett-Jackson transportation priced per person?",`For 12 Barrett-Jackson riders sharing the ${n[se]} across 5 billed hours, the published ${it(se)}-per-hour rate is about ${Ir(se,5,12)} per person before tax for the complete shared ride; actual pricing changes with the vehicle, the duration, the itinerary and the confirmed service plan.`,"That example is arithmetic, not a flat auction fare: hourly rate multiplied by billed hours, divided by riders. If only ten people ride, divide across ten. If the group needs the motorcoach or a longer window that waits through auction close, request that calculation instead of stretching the 5-hour illustration.","A complete plan may be a continuous vehicle, separate inbound and outbound transfers, or several hotel waves across the 9 days. Each shape uses time differently. Describe the actual pattern. A many-hour gap between drop-off and pickup is not a round trip until the quote says how those hours are billed.",`The same arithmetic on the ${n[He]} uses its own published rate of ${it(He)}/hr and its own seated capacity of ${c[He]}. Per-person math is useful after the rider list settles. One person collects shares and one person owns the manifest. Neither job belongs to the chauffeur.`)],Gr=[{question:"What are the dates for Barrett-Jackson Scottsdale 2027?",answer:"Saturday, January 23 through Sunday, January 31, 2027, at WestWorld of Scottsdale: nine days of live auction action with over 2,000 collector vehicles on display. The invitation-only Opening Night Gala is the evening before, Friday, January 22."},{question:"Where is Barrett-Jackson Scottsdale held?",answer:"At WestWorld of Scottsdale, 16601 North Pima Road, Scottsdale, AZ 85260. Barrett-Jackson’s 2027 venue map is announced closer to the date."},{question:"What time does Barrett-Jackson open?",answer:"Gates, food courts and sponsor displays open at 8:00 a.m. every day from January 23 to 31 and stay open until auction close. Daily auction close times are announced closer to the date, so plan the ride home as a window rather than a fixed time."},{question:"Is parking free at Barrett-Jackson?",answer:"Yes. Barrett-Jackson publishes plenty of complimentary public parking for Scottsdale 2027: follow the road signs to parking. Shuttles run to and from the main gate, and valet parking is available for a fee."},{question:"Is there a shuttle at Barrett-Jackson?",answer:"Yes. Barrett-Jackson says shuttles run to and from the Scottsdale auction’s main gate. With a chauffeured ride nobody in the group drives or parks; the vehicle unloads where event staff direct, and a limo, charter or commercial drop-off zone is announced closer to the date."},{question:"Where do rideshares drop off at Barrett-Jackson?",answer:"Use the parking lot west of Thompson Peak Parkway on McDowell Mountain Ranch Road and follow the signs to the rideshare area. A chauffeured commercial drop-off zone is announced closer to the date."},{question:"How do I buy Barrett-Jackson tickets?",answer:"General-admission tickets are sold online and at the on-site AXS box office, and general admission does not guarantee arena seating. Buy only through Barrett-Jackson’s official channels. A ride booking does not include admission, valet or an invitation to the Opening Night Gala."},{question:"What if the auction runs late?",answer:za},{question:"What is the Barrett-Jackson Opening Night Gala?",answer:"An invitation-only evening in the Auction Arena on Friday, January 22, 2027, from 7:00 to 10:00 p.m., the night before the public auction days begin. Invited guests who want a chauffeured ride book it as its own evening service."}],Va={path:"/guides/barrett-jackson-transportation",title:"Barrett-Jackson Scottsdale 2027: parking and getting there",metaTitle:"Barrett-Jackson 2027: Parking & Rides",description:"Barrett-Jackson Scottsdale 2027 runs January 23–31 at WestWorld of Scottsdale. The official dates, complimentary public parking and main-gate shuttles, valet, the rideshare lot, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Official Jan 23–31 dates, free parking and shuttles, valet, or a chauffeured ride",lastUpdated:ea,lastUpdatedLabel:T(ea),eyebrow:"Official dates: January 23–31, 2027",intro:`A Barrett-Jackson ride from Scottsdale Sprinters starts with the official 2027 page, a realistic rider count and one transportation lead. Collectors and VIP groups lead with the ${n[I]}; friends and bidder crews ride the ${n[se]} or a Limo Party Sprinter; corporate hosts and big groups take the mini coach, the mini bus or the party bus. This guide uses only published organizer facts, leaves unannounced details for closer to the date, and turns each day into a written pickup, arrival and return plan.`,sections:Wr,faqs:Gr,links:[{href:"/fleet/executive-sprinter-scottsdale",label:n[se]},{href:"/fleet/maybach-jet-sprinter-scottsdale",label:n[I]},{href:"/fleet/motorcoach-56",label:n[He]},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:xr,fleetRows:Ha},Ls=[Va],Je="2026-09-24";function v(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Nr=nr.filter(e=>ge(e)).map(e=>({slug:e}));function jt(e,t){const a=or(Nr,{occasionClass:e,headcount:t});if(a.mismatch)throw new Error(`Venue parking guide: no ${e} unit fits ${t??"any"} riders`);const o=[a.featured,a.companion,...a.rest].flatMap(h=>h?[h.slug]:[]);if(o.length<2)throw new Error(`Venue parking guide: fewer than 2 ${e} units are listed`);return o}const me=jt(Ia({occasion:"game day party"})),ke=jt(Ia({occasion:"corporate outing"})),tt=Math.max(...me.map(e=>c[e])),Se=jt("large_group",tt+1),A=e=>n[e],Bt=e=>c[e];function Lr(e){return e.length<=1?e.join(""):`${e.slice(0,-1).join(", ")} and ${e[e.length-1]}`}const _r=4;function ht(e){return Lr(e.slice(0,_r).map(t=>`${A(t)} up to ${Bt(t)}`))}function Ur(e){const t=s[e],a=Ga({hourlyRateCents:t.hourlyRateCents,minimumHours:t.minimumHours,capacity:Bt(e)},et);return`The ${A(e)} is ${g(t.hourlyRateCents)} an hour with a ${t.minimumHours}-hour minimum, so ${a.billedHours} billed hours come to ${a.fareLabel} before tax, about ${a.perPersonLabel} each when all ${Bt(e)} seats are filled.`}const Ja=[me[0],ke[0],Se[0]];function ja(){return Ja.map(e=>({href:`/fleet/${e}`,label:A(e)}))}function Ya(){const e=Ja;return[`Seats come from the published fleet. For game-day groups: ${ht(me)}. For client outings: ${ht(ke)}. For more than ${tt} riders: ${ht(Se)}.`,`Every rate prices the whole vehicle by the hour, and here is a ${et}-hour booking in each lead vehicle. ${e.map(Ur).join(" ")}`,"Those figures are arithmetic from the published rates, not a quote. An hourly booking keeps the vehicle for the whole outing, so the drive each way counts toward the hours. A ride there and a separate ride back can be booked as a transfer instead of by the hour; the written quote shows how the drive is priced."]}const x="https://www.mlb.com/dbacks/ballpark",Br=[{label:"Arizona Diamondbacks — Where to Park at Chase Field",href:`${x}/transportation/parking`},{label:"Arizona Diamondbacks — Chase Field A-to-Z Guide",href:`${x}/information/guide`},{label:"Arizona Diamondbacks — Chase Field Disability Access Guide",href:`${x}/disability-access-guide`},{label:"Arizona Diamondbacks — Know Before You Go",href:`${x}/information/know-before-you-go`},{label:"Arizona Diamondbacks — Driving Directions",href:`${x}/transportation/driving-directions`},{label:"Arizona Diamondbacks — Additional Traffic Information",href:`${x}/transportation/additional-information`},{label:"Arizona Diamondbacks — Valley Metro Rail",href:`${x}/transportation/valley-metro-rail`},{label:"Arizona Diamondbacks — Clear Bag Policy",href:`${x}/information/bag-policy`},{label:"Valley Metro — Destinations",href:"https://www.valleymetro.org/how-to-ride/destinations"},{label:"City of Phoenix — ParkPHX downtown parking tool",href:"https://www.phoenix.gov/newsroom/convention-center-news/3371.html"},{label:"Arizona Diamondbacks — 2027 Regular Season Schedule",href:"https://www.mlb.com/dbacks/schedule/2027-03"},{label:"MLB.com — MLB releases 2027 regular-season schedule",href:"https://www.mlb.com/dbacks/news/mlb-2027-schedule-released"},{label:"Arizona Diamondbacks — Chase Field Events",href:`${x}/events`},{label:"Arizona Diamondbacks — The Hondo Rodeo Fest at Chase Field",href:`${x}/events/upcoming/hondo-rodeo-fest`},{label:"MLB.com — Commissioner Rob Manfred on initial CBA proposals",href:"https://www.mlb.com/news/mlb-commissioner-rob-manfred-on-initial-cba-proposals"}],Pe=["January","February","March","April","May","June","July","August","September","October","November","December"],Or={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"};function lt(e){const t=P(e);return`${Or[Na(e)]}, ${Pe[t.month]} ${t.day}, ${t.year}`}function qr(e,t){const a=P(e),o=P(t);return e===t?`${Pe[a.month]} ${a.day}`:a.month===o.month?`${Pe[a.month]} ${a.day}–${o.day}`:`${Pe[a.month]} ${a.day} – ${Pe[o.month]} ${o.day}`}function Ee(e){return e.label.replace(/^.*\bvs\. /,"")}function Hr(e){const t=[],a=o=>{const h=P(o);return Date.UTC(h.year,h.month,h.day)/864e5};for(const o of e){const h=t[t.length-1];h&&a(o.date)-a(h.last)<=2?(h.last=o.date,h.visitors.includes(Ee(o))||h.visitors.push(Ee(o))):t.push({first:o.date,last:o.date,visitors:[Ee(o)]})}return t}function zr(e){return e.length<=1?e.join(""):`${e.slice(0,-1).join(", ")} and ${e[e.length-1]}`}function Vr(){const e=xa({items:dr}),t=e[0],a=e[e.length-1],o=e.filter(f=>f.startsAt),h=o.length===e.length?"each with its first-pitch time below":o.length>0?"with first-pitch times announced for some of them so far":"and the team has not announced first-pitch times yet",$=Hr(e).map(f=>`${qr(f.first,f.last)} (${zr(f.visitors)})`),Y=P(t.date).year;return v("When are the D-backs home games and concerts at Chase Field?",`The Arizona Diamondbacks play ${e.length} home games at Chase Field in ${Y}, from the home opener against the ${Ee(t)} on ${lt(t.date)} to the last home game against the ${Ee(a)} on ${lt(a.date)}, ${h}.`,`The home stands, in order: ${$.join("; ")}. Opening Day, Thursday, March 25, ${Y}, is on the road in San Diego, so the first game at Chase Field is the home opener.`,o.length>0?`Announced first pitches, in Arizona time: ${o.map(f=>`${lt(f.date)}, ${f.label}, ${Wa(f.startsAt)}`).join("; ")}. The rest are added here as the Diamondbacks announce them. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, so give the reservations team your game date when you book and the chauffeur plans the pickup around it.`:"The Diamondbacks announce first-pitch times closer to the season, and they are added here as they are. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, so give the reservations team your game date when you book and the chauffeur plans the pickup around it.",`The one concert the Diamondbacks list for Chase Field as of ${T(sr)} is the Hondo Rodeo Fest, November 13–15, 2026: each night a full rodeo, then a full-length concert, with Tim McGraw and Miranda Lambert on Friday, Blake Shelton and Turnpike Troubadours on Saturday, and Parker McCollum and Lynyrd Skynyrd on Sunday. Shows for ${Y} are announced by the ballpark closer to the date.`,"One caveat for the season: Major League Baseball’s labor agreement expires on December 1, 2026. If a new agreement is not in place in time, games can move, and this list follows the official schedule as MLB and the Diamondbacks publish it.")}const Jr=[v("Where do you park for Chase Field?","Chase Field has an attached 1,500-car garage just south of the ballpark on 4th Street that works first come, first served, and the Diamondbacks also offer pre-booked spaces through ParkWhiz, their preferred parking partner, so you can hold a spot before driving to the game.","The ballpark is at 401 East Jefferson Street in downtown Phoenix, bounded by 7th Street on the east, 4th Street on the west, Jefferson Street on the north and the Southern Pacific Railroad tracks on the south. The Diamondbacks’ traffic advice is to park in the same quadrant you drive in from. Arriving from the south, for example, means parking between 3rd Avenue and 9th Street, from Lincoln Street to Jefferson Street.","Payment is not the same everywhere. The Diamondbacks warn that some garages and lots around Chase Field take only credit cards while others take only cash, so carry both unless the space is prepaid. The City of Phoenix’s ParkPHX tool lists every public downtown parking facility in one place, with height limits, accessible spaces and reservations at participating facilities.","Downtown parking is not one system. The City of Phoenix runs its own garages through the Phoenix Convention Center, and the Diamondbacks’ pre-booking runs through ParkWhiz, so rates and payment rules differ by facility. Book or choose the space before you leave, not at the last light before the ballpark."),v("What should you know about the Chase Field Garage?","The Chase Field Garage is attached to the ballpark just south of it on 4th Street, holds 1,500 cars, takes high-profile vehicles at every entrance, sets aside 31 accessible spaces, and has its own entrance on Level 3 for Suite and 200-level seats, with accessible turnstiles.","All of its parking, the accessible spaces included, is first come, first served. When demand is high, the Diamondbacks say some garages accept only special parking passes, so a driver without one may need another garage. A sign at the booth shows when accessible parking in the Chase Field or Jefferson Street garage is full, before you pull in.","The Jefferson Street Garage is the second garage the team names. Both garages have bicycle racks at street level, which the Diamondbacks list among the places to lock a bike, because bicycles are not allowed inside the ballpark.","If the plan depends on the attached garage, pre-book or arrive early. The City of Phoenix, which runs the city-owned downtown garages, says spaces are in high demand during peak events."),v("Where is the Chase Field rideshare drop-off and pickup?","The Diamondbacks publish 2 rideshare points for pickup and drop-off, 5th Street north of Washington Street and Jackson Street east of 9th Street, plus a staffed drop-off on the south side of Jefferson Street just west of 7th Street, near Gate K, listed in the ballpark’s accessibility guide.","One rideshare point is north of the ballpark, past Washington Street; the other is east of it, beyond 9th Street on Jackson Street. Pick the one on the side you are heading home from and agree on it before the game. A group that splits between the two points is waiting in two places.","The Jefferson Street drop-off is staffed and has shaded benches for guests waiting on a ride. The driver who drops a guest there should ask for a Pick-Up Pass, which carries a map and directions back to the same spot after the game. Hold it up when traffic control detours you, so staff can direct you back to that lot.","None of these points is reserved for chauffeured vehicles: the Diamondbacks publish no separate limo or charter zone. A booked vehicle works from the published points and the instruction confirmed for the booking. The team also warns that traffic around the ballpark can be rerouted as conditions dictate, as it does for southbound 3rd Street at Washington Street."),v("Can you take light rail to Chase Field?","Yes, Valley Metro’s A line stops at 2 stations near the ballpark, 3rd Street and Washington and 3rd Street and Jefferson, with trains every 15 to 20 minutes, and the Diamondbacks list 13 light rail Park-and-Ride locations for fans who drive part of the way.","Buy the fare at any station with cash, credit or debit, or load the Valley Metro app or a Copper card before the game. The Diamondbacks suggest paying in advance to skip the lines after the game, and a daily fare cap means you stop paying once you reach it.","Valley Metro also lists 2 bus connections for Chase Field: Route 1 on Washington Street and Route 7 on 7th Street. The Diamondbacks’ Park-and-Ride list runs from 19th Avenue and Dunlap to Gilbert Road and Main Street, and the Valley Metro app plans the trip from any of them.","Rail suits a couple or a small party staying near a station. A larger group coming from Scottsdale resorts has more steps: getting everyone to a Park-and-Ride, onto one train and back again after the final out."),v("How much time and hassle does parking at Chase Field add?","Driving yourself adds 3 jobs to the game: getting a space before the garage or lot fills, paying the way that facility accepts, and leaving by the Diamondbacks’ quadrant exit routes after the final out, alongside everyone else leaving the ballpark at the same time.","Arrival comes first. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, and the city says downtown garages are in high demand during peak events. Pre-booking through ParkWhiz or ParkPHX removes the search, not the drive.","Then comes the exit. The Diamondbacks route traffic by quadrant after the game. From the southeast quadrant, south of Jefferson and east of 4th Street, drivers go south to Lincoln Street and then east to 7th Street. From the southwest quadrant they go south to Lincoln, which becomes Grant, and west to 7th Avenue. North of Washington, 3rd and 7th Avenues lead to the freeways.","The drive in has its own warnings. From north central Phoenix the team calls 7th Street the least preferred route because of heavy use, and it calls the 3rd Street HOV exit the least preferred during arrival. None of it is hard, but all of it falls on whoever drives, who also has to stay fit to drive home."),v("Why does a chauffeured drop-off beat parking at Chase Field?","A chauffeured drop-off removes 3 costs of driving: the group steps out at the drop-off point confirmed for the booking instead of walking in from wherever a space was found, nobody sits in a garage exit line after the game, and one vehicle carries everyone, so nobody has to be the designated driver.","It is not a way around traffic control. After the game every vehicle, ours included, moves with the downtown traffic plan, and the chauffeur meets the group at the agreed point once it is reachable. What changes is who does the work: the chauffeur handles the route in, the drop-off, the timing of the pickup and the route out.","One vehicle also keeps a group together. Separate cars mean separate garages, separate exits and separate arrival times. A Sprinter or bus arrives with everyone at once, which matters when the plan includes dinner or a hotel pickup before first pitch.","The trade-off is timing. A pickup runs on the traffic plan and the chauffeur’s approach, not on the minute you walk out, so agree on the pickup point in advance and message the chauffeur once the whole group is together."),v("Which vehicle fits a Chase Field group, and what does it cost?",`Match the vehicle to the group: game-day friends start with the ${A(me[0])} or the ${A(me[1])}, a client outing starts with the ${A(ke[0])} or the ${A(ke[1])}, and a group larger than ${tt} moves up to the ${A(Se[0])} or the ${A(Se[1])}.`,...Ya()),v("How should a group plan the Chase Field arrival and pickup?","Plan 4 things before leaving the hotel: an arrival inside the gate window, which opens 90 minutes before first pitch Sunday through Friday and 2 hours before on Saturday, one agreed pickup point, one person who messages the chauffeur, and bags that pass the clear bag policy.","The clear bag policy decides what leaves the vehicle. It allows one clear bag up to 12 by 6 by 12 inches or a one-gallon clear bag, plus a small clutch up to 4.5 by 6.5 inches, and no backpacks. A group that is dropped off has no car in the garage to leave a bag in, so settle bags at the hotel. The Diamondbacks’ locker partner, Mobile Locker Company, stores non-approved bags for a fee.","For the return, choose the rideshare point on the side you will leave from, or the Jefferson Street drop-off when a guest needs the accessible entrance, and share it with the whole group before first pitch. When the game ends, gather first, then message the chauffeur once with the group count, rather than having several people send pins.",`Guests who have difficulty walking to their seats can ask any Chase Field staff member for a complimentary wheelchair escort from the gates or drop-off areas to their seats; the Diamondbacks say no advance request is needed. For a change of plan on the day, call the reservations team at ${F} or email ${M}.`),Vr()],jr=[{question:"How much is parking at Chase Field?",answer:"The Diamondbacks do not publish one parking price. Garages and lots around the ballpark set their own rates, and some take only cards while others take only cash. To see a price before you go, pre-book through ParkWhiz, the team’s preferred parking partner, or compare downtown garages on the City of Phoenix’s ParkPHX."},{question:"Where is the best place to park for Chase Field?",answer:"The Chase Field Garage is attached to the ballpark, just south of it on 4th Street, with 1,500 spaces on a first come, first served basis. Otherwise the Diamondbacks advise parking in the same quadrant you drive in from, and pre-booking through ParkWhiz holds a space before you leave."},{question:"Is there free parking near Chase Field?",answer:"The Diamondbacks publish no free parking. Their alternative to a garage is light rail: they list 13 Park-and-Ride locations, and trains stop at 3rd Street and Washington or 3rd Street and Jefferson, within walking distance of the ballpark."},{question:"Where is the rideshare pickup at Chase Field?",answer:"At 5th Street north of Washington Street, or Jackson Street east of 9th Street. Agree on one with your group before the game."},{question:"Where is accessible parking and drop-off at Chase Field?",answer:"The attached garage has 31 spaces for a valid disabled plate or placard, first come, first served. The staffed drop-off is on the south side of Jefferson Street, just west of 7th Street, near Gate K. Ask for a Pick-Up Pass to get back to it after the game."},{question:"What time do Chase Field gates open?",answer:"90 minutes before first pitch Sunday through Friday, and 2 hours before first pitch on Saturday. The Diamondbacks post special gate times for some dates in their A-to-Z guide."},{question:"Can a chauffeured Sprinter drop our group at Chase Field?",answer:"Yes, at a point the live traffic plan allows. The Diamondbacks publish two rideshare points and a staffed drop-off on Jefferson Street but no separate limo or charter zone, so the chauffeur confirms the drop-off for your booking and vehicle."}],Yr={path:"/guides/venues/chase-field",title:"Chase Field Parking Guide: Garages, Rideshare & Drop-Off",metaTitle:"Chase Field Parking & Drop-Off Guide",description:"Where to park for Chase Field: the attached 1,500-car garage, ParkWhiz pre-booking, the two rideshare points, light rail stations and gate times, and how a chauffeured group drop-off compares.",metaDescription:"The 1,500-car garage, ParkWhiz pre-booking, light rail stops and gate times",lastUpdated:Je,lastUpdatedLabel:T(Je),intro:"Scottsdale Sprinters’ short answer on Chase Field parking: use the attached 1,500-car Chase Field Garage on 4th Street, which is first come, first served, or pre-book a nearby space through ParkWhiz, the Diamondbacks’ preferred parking partner, and carry a card and cash because some lots take only one. Rideshare pickups use 5th Street north of Washington Street or Jackson Street east of 9th Street, and light rail stops at 3rd Street and Washington or 3rd Street and Jefferson. For a group, one chauffeured vehicle replaces the garage, the payment and the drive out after the final out.",sections:Jr,faqs:jr,links:[...ja(),{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:Br},re="https://www.statefarmstadium.com",Kr=[{label:"State Farm Stadium — Directions and Parking",href:`${re}/plan-your-visit/directions-parking`},{label:"State Farm Stadium — 2025 Cardinals parking map",href:`${re}/assets/img/2025-Cardinals-Parking-Map-db3cd0d2f1.png`},{label:"State Farm Stadium — 2025 event parking map (concerts, soccer, dirt shows)",href:`${re}/assets/img/2025-Stadium-Event-Parking-Map-fb2439fd59.png`},{label:"State Farm Stadium — A-Z Guide",href:`${re}/a-z-guide`},{label:"State Farm Stadium — ADA and Accessibility",href:`${re}/ada-accessibility`},{label:"State Farm Stadium — Safety and Clear Bag Policy",href:`${re}/clear-bag-policy`},{label:"Fiesta Sports Foundation — 2026-27 Vrbo Fiesta Bowl parking map",href:"https://www.fiestasportsfoundation.org/documents/2026/8/14/26-27_VFB_Parking_Map_FINAL.pdf"},{label:"Fiesta Sports Foundation — Vrbo Fiesta Bowl A-Z Guide",href:"https://www.fiestasportsfoundation.org/sports/2019/12/6/vrbo-fiesta-bowl-a-z-guide.aspx"},{label:"Valley Metro — West Valley destinations",href:"https://www.valleymetro.org/how-to-ride/destinations/destinations-west-valley"},{label:"State Farm Stadium — Upcoming events",href:`${re}/events`}],Ka=["January","February","March","April","May","June","July","August","September","October","November","December"],Zr={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"};function ve(e){const t=P(e);return`${Ka[t.month]} ${t.day}, ${t.year}`}function Ot(e){if(!e.orDate)return`${Zr[Na(e.date)]}, ${ve(e.date)}`;const t=P(e.date),a=P(e.orDate);return t.month===a.month&&t.year===a.year?`${Ka[t.month]} ${t.day} or ${a.day}, ${a.year}`:`${ve(e.date)} or ${ve(e.orDate)}`}function aa(e,t){if(t.length===1)return`${e} on ${Ot(t[0]).replace(/^\w+, /,"")}`;if(t.length===2&&P(t[0].date).year===P(t[1].date).year){const[h,$]=t.map(Y=>ve(Y.date));return`${e} on ${h.replace(/, \d{4}$/,"")} and ${$}`}const a=t[t.length-1],o=a.orDate?Ot(a):ve(a.date);return`${t.length} ${e} from ${ve(t[0].date)} to ${o}`}function ra(e){return`${Ot(e)}, ${e.label}, ${cr(e).replace(/^Day and /,"day and ")}`}function Qr(){const e=xa({items:ur}),t=ir.map(f=>({series:f,items:e.filter(ot=>ot.series===f.id)})).filter(f=>f.items.length>0),[a,...o]=t,h=hr({items:e}),$=o.map(({series:f,items:ot})=>aa(f.article?`${f.article} ${f.label}`:f.label,ot)),Y=$.length>1?`${$.slice(0,-1).join(", ")} and ${$[$.length-1]}`:$.join("");return v("When are the Cardinals home games and concerts at State Farm Stadium?",`Our ${P(h.start).year}-${String(P(h.end??h.start).year).slice(2)} date list for State Farm Stadium has ${aa(a.series.label,a.items)}${Y?`, plus ${Y}`:""}, each with its kickoff or show time below.`,`${a.series.label}, in Arizona time: ${a.items.map(ra).join("; ")}.`,...o.length?[`Also at the stadium: ${o.flatMap(({items:f})=>f.map(ra)).join("; ")}.`]:[],`These dates and times are as State Farm Stadium and the Arizona Cardinals listed them on ${T(lr)}. Start times can change, so check the event’s own page before the day. Give the reservations team your date when you book, and the chauffeur plans the pickup around that start: on Cardinals game days the lots open 4 hours before kickoff, and the gates open 2 hours before kickoff for NFL games.`)}const Xr=[v("Where do you park at State Farm Stadium?","State Farm Stadium recommends buying parking in advance through SeatGeek and describes event-day parking in 2 colors, red Preferred Parking entered only at Maryland Avenue and 95th Avenue and blue General Parking, where staff fill lots by capacity and traffic flow, and every parking area takes credit cards only.","On the stadium’s 2025 Cardinals parking map, the red Preferred lots, West Preferred and North Preferred, sit beside the stadium, and East Preferred is marked as its own lot on the east side. For the red lots, leave Loop 101 at Cardinals Way when coming from the south. From the north, leave at Glendale Avenue, head west to 99th Avenue and then east on Maryland Avenue. The stadium suggests searching Red Lot - State Farm Stadium on Waze.","General Parking is reached from Glendale Avenue or Cardinals Way off Loop 101, or from 91st and 99th Avenues. You do not pick the lot: parking staff and Glendale police direct each car to the closest lot with room, so follow the message boards and their instructions.","On Cardinals game days the lots open 4 hours before kickoff. Parking in Sportsman’s Park, the lots around the stadium, serves pre-sold permit holders and single-game visitors, and the Black Lot is set aside for same-day parking without a pre-sold permit. Other events set their own hours, so check that event’s page."),v("Which lots are on the State Farm Stadium parking map?","The stadium’s 2025 Cardinals parking map names its lots by area and color, among them West Preferred, North Preferred, East Preferred, West, Great Lawn, East, Lot F, Oversized, Yellow, Blue, Pink and the Black lot, and it prints exit routes to Northern Avenue and Indian School Road.","Exits depend on where you came from. Guests in the Pink, Blue, Yellow, Grey and Green lots who arrived from the north leave by Northern Avenue, and guests in the Green and Grey lots who arrived from the south leave by Indian School Road. Southbound Loop 101 drivers heading for the Black lot follow its own route, entering from Camelback Road onto Montebello Avenue.","RVs and other oversized vehicles park only in the designated oversized lot, on event days only, and never overnight. On Cardinals game days that is Lot F. It opens 4 hours and 30 minutes before kickoff, needs a Lot F Oversized Vehicle mobile pass, takes one vehicle per space and fits vehicles up to 45 feet.","Some events publish a map of their own. The 2026-27 Vrbo Fiesta Bowl map labels the Black and Blue lots gameday only and shows a West Bus area; our Fiesta Bowl guide covers that game’s parking and transportation."),v("Where is the State Farm Stadium rideshare drop-off and pickup?","Rideshare drop-off and pickup, and drop-offs by family or friends, all use the Black Lot south of the stadium across Cardinals Way, and on Cardinals game days the stadium’s 2025 map marks that rideshare lane westbound only, with the eastbound lane of Cardinals Way closed.","The stadium asks guests to check the event’s own page for updates. The Fiesta Bowl’s guide for last season’s game told guests to walk back to the Black Lot after the game, request the ride there and meet the car in the lot. Build that walk into the plan, and remember that every rideshare guest is using the same point.","No limo or charter lane is published. The Black Lot is the stadium’s named point for drop-off and pickup, so it is the planning anchor for a chauffeured group. The exact spot for your vehicle, and especially for a bus, comes from the event’s traffic plan and the instruction confirmed for the booking.","Guests with mobility needs have another option. Every Sportsman’s Park lot has ADA spaces, and a courtesy cart runs from designated ADA parking to the plaza security checkpoints. It runs from 3 hours before kickoff to 1 hour after on Cardinals days, and from 2 hours before major events to 1 hour after."),v("Can you get to State Farm Stadium without driving?","Valley Metro lists 1 connection for the Westgate Entertainment District beside the stadium, bus Route 70 on Glendale Avenue, and no light rail, so without your own car the practical options are rideshare to the Black Lot, a taxi or a booked vehicle.","The Fiesta Bowl’s guide also points to a bus stop at Glendale Avenue and 95th Avenue and to Valley Metro’s schedules. Check the current Route 70 timetable for your date before relying on it for the ride home.","Parking in the neighborhoods is not an option either. The same guide notes that the City of Glendale prohibits parking in undesignated areas or on residential streets, and that police do not let event traffic reach the stadium through local neighborhoods, so use the arterial streets.","The stadium’s own A-Z guide is direct about the ride home: never drink and drive, and use a designated driver, a rideshare service or a taxi. A booked vehicle follows that advice for a whole group at once."),v("What are the State Farm Stadium tailgating rules?","Tailgating is allowed in the carparks once they open, 4 hours before kickoff on Cardinals game days, with these rules: stay in 1 stall, keep the tailgate behind your vehicle, weight tents above ground, do not save spaces, arrive together, and pack up before carparks close 1 hour after the event.","Keep equipment out of neighboring stalls, walkways and aisles, and use above-ground weights rather than stakes for tents. Saving a space for friends who come later is not allowed: a group that wants to tailgate together has to arrive together.","On Cardinals game days the team adds its own guidelines, and post-game tailgating is prohibited. Events such as the Fiesta Bowl publish their own rules for game day, so read the current version for the date you are going.","Tailgating is built around a parked vehicle, one stall and the space behind it. A group arriving by drop-off has no stall. If the plan includes a tailgate, tell the reservations team, because the vehicle then has to stay parked, which needs its own parking arrangement and, for a bus, the oversized-lot rule above."),v("How much time and hassle does parking at State Farm Stadium add?","On a Cardinals game day, the stadium’s map encourages fans to arrive within the first 2 hours after the lots open, which is 4 to 2 hours before kickoff, then staff direct each car to a lot with room, parking is card-only, and the map sets exit routes by lot after the game.","Arriving early is the stadium’s advice, not a rule, but the gates open 2 hours before kickoff for NFL games. A car that arrives when the lots open therefore waits about 2 hours before anyone can go in.","After the game, carparks close 1 hour after the event, and the 2025 Cardinals map sends drivers out by Northern Avenue or Indian School Road depending on the lot and the direction they came from. On game day, dial 511 and press star 7 for Cardinals traffic information from the Arizona Department of Transportation.","All of that falls on whoever drives, who also has to stay fit to drive home after the game."),v("Why does a chauffeured drop-off beat parking at State Farm Stadium?","A chauffeured drop-off removes 3 parts of the day: the group steps out at the Black Lot or the point confirmed for the booking instead of walking from an assigned lot, nobody waits in a lot exit line after the game, and one vehicle carries everyone, so nobody has to be the designated driver.","It does not skip traffic. Every vehicle leaving the stadium, ours included, moves with the event traffic plan, and the chauffeur meets the group at the agreed point when the plan allows. The difference is that the group walks to one meeting point and rides home, instead of walking to a lot, finding the car and joining the exit.","It also changes the timing. A group that is dropped off does not have to be there when the lots open, so it can plan from the gate time, 2 hours before kickoff for NFL games, instead of the 4-hour lot window.","The trade-off is that no car in the lot means nowhere to leave a bag. The clear bag policy allows clear plastic, vinyl or PVC bags up to 12 by 6 by 12 inches, including clear backpacks and fanny packs, and small non-clear bags up to 4.5 by 6.5 inches. Coolers are prohibited, and once you leave the stadium there is no re-entry."),v("Which vehicle fits a State Farm Stadium group, and what does it cost?",`Match the vehicle to the group: a game-day group of friends starts with the ${A(me[0])} or the ${A(me[1])}, client hospitality starts with the ${A(ke[0])} or the ${A(ke[1])}, and anything over ${tt} riders moves up to the ${A(Se[0])} or the ${A(Se[1])}.`,...Ya(),"State Farm Stadium is in Glendale, on the far side of Phoenix from Scottsdale, so the drive each way is longer than a trip downtown. Tell the reservations team your pickup address and kickoff time, and the quote will show the hours that trip needs."),Qr()],en=[{question:"How much is parking at State Farm Stadium?",answer:"It depends on the event and the lot. The stadium recommends buying parking in advance through SeatGeek, its official parking maps print the rates, and every parking area takes credit cards only."},{question:"Where is the best place to park at State Farm Stadium?",answer:"The red Preferred lots, West Preferred and North Preferred, sit beside the stadium and are entered only at Maryland Avenue and 95th Avenue. General Parking is assigned by staff to the closest lot with room, and on Cardinals days the Black Lot takes same-day parking without a pre-sold permit."},{question:"What time does parking open at State Farm Stadium?",answer:"On Cardinals game days, 4 hours before kickoff, with the oversized Lot F at 4 hours and 30 minutes. Other events list their own times on the event page, and stadium gates open 2 hours before kickoff for NFL games."},{question:"Where is rideshare pickup at State Farm Stadium?",answer:"In the Black Lot, south of the stadium across Cardinals Way. It is also the drop-off and pickup point for family and friends."},{question:"Can you tailgate at State Farm Stadium?",answer:"Yes, in the carparks once they open: one stall per vehicle, tailgate behind your vehicle, weight tents above ground, no saved spaces, and arrive together. Carparks close 1 hour after the event, and post-game tailgating is prohibited at Cardinals games."},{question:"Is there free parking near State Farm Stadium?",answer:"The stadium publishes no free parking, and the Fiesta Bowl’s official guide notes that the City of Glendale prohibits parking in undesignated areas or on residential streets. A drop-off at the Black Lot is the way to arrive without a parking space."},{question:"Where do RVs and oversized vehicles park at State Farm Stadium?",answer:"In the designated oversized lot, on event days only. On Cardinals game days that is Lot F, which opens 4 hours and 30 minutes before kickoff, needs a Lot F Oversized Vehicle mobile pass and fits vehicles up to 45 feet."},{question:"Can a chauffeured Sprinter drop our group at State Farm Stadium?",answer:"Yes, at the point the event’s traffic plan allows. The Black Lot is the stadium’s published drop-off and pickup point, and no separate limo or charter zone is published, so the chauffeur confirms the drop-off for your booking and vehicle."}],tn={path:"/guides/venues/state-farm-stadium",title:"State Farm Stadium Parking Guide: Lots, Rideshare & Drop-Off",metaTitle:"State Farm Stadium Parking & Drop-Off",description:"Where to park at State Farm Stadium: Preferred and General lots, the Black Lot rideshare drop-off, Cardinals lot hours, tailgating rules and oversized parking, and how a chauffeured group drop-off compares.",metaDescription:"Preferred and General lots, the Black Lot drop-off, hours and tailgating rules",lastUpdated:Je,lastUpdatedLabel:T(Je),intro:"Scottsdale Sprinters’ short answer on State Farm Stadium parking: buy a space in advance through SeatGeek, as the stadium recommends, pay by credit card because every parking area is cashless, and expect staff to direct you to a lot unless you hold Preferred Parking, which is entered only at Maryland Avenue and 95th Avenue. Rideshare and family drop-off and pickup use the Black Lot south of the stadium, and on Cardinals game days the lots open 4 hours before kickoff. For a group, one chauffeured vehicle replaces the lot, the card reader and the drive out.",sections:Xr,faqs:en,links:[{href:"/guides/fiesta-bowl-transportation",label:"Fiesta Bowl parking and transportation guide"},{href:"/guides/venues/desert-diamond-arena",label:"Desert Diamond Arena parking and concerts, across Maryland Avenue"},...ja(),{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:Kr},na="2026-09-24",Ce="https://mortgagematchupcenter.com";function B(e,t,...a){return{question:e,answer:t,paragraphs:a}}const je="executive-sprinter-scottsdale",Ye="limo-sprinter-16-scottsdale",Ke="ultra-luxury-party-sprinter-scottsdale",fe=e=>n[e],oa=e=>c[e];function an(e){const t=s[e],a=Ga({hourlyRateCents:t.hourlyRateCents,minimumHours:t.minimumHours,capacity:oa(e)},et);return`The ${fe(e)} is ${g(t.hourlyRateCents)} an hour with a ${t.minimumHours}-hour minimum, so ${a.billedHours} billed hours come to ${a.fareLabel} before tax, about ${a.perPersonLabel} each when all ${oa(e)} seats are filled.`}const rn=[{label:"Mortgage Matchup Center — Transportation & Parking",href:`${Ce}/plan-your-visit/transportation-parking/`},{label:"Mortgage Matchup Center — Accessibility and ADA Information",href:`${Ce}/venue/accessibility-ada-information/`},{label:"Mortgage Matchup Center — official venue site (bag policy, door times, parking)",href:`${Ce}/`},{label:"Mortgage Matchup Center — naming rights announcement (October 2, 2025)",href:`${Ce}/news/phoenix-suns-and-phoenix-mercury-announce-landmark-naming-rights-partnership-with-mortgage-matchup/`},{label:"Mortgage Matchup Center — Private Events",href:`${Ce}/private-events/`},{label:"Phoenix Suns — 2026-27 schedule",href:"https://www.nba.com/suns/schedule"},{label:"NBA — Phoenix to host NBA All-Star 2027",href:"https://pr.nba.com/phoenix-to-host-nba-all-star-2027/"},{label:"Live Nation — Mortgage Matchup Center events",href:"https://www.livenation.com/venue/KovZpZAE617A/mortgage-matchup-center-events"}],nn=[B("Where do you park for Mortgage Matchup Center?","Mortgage Matchup Center points guests to the several garages and lots within walking distance and asks them to buy parking in advance through ParkWhiz; event parking generally opens about 30 minutes before doors, parking has no in-and-out privileges, and availability, pricing and access vary by event.","The arena is at 201 E. Jefferson Street, on the southeast corner of 1st Street and Jefferson in downtown Phoenix. Its site also lists more than 700 on-site parking spaces, including designated parking for guests with disabilities, with rates that vary by event, and it sends guests to the Mortgage Matchup Center Parking Office at 602-379-2003 for event pricing.","Public garages downtown are typically open all day, but for an event the arena says to plan on parking from about 30 minutes before doors open, unless that event says otherwise. Because parking has no in-and-out privileges, a group that parks early for dinner nearby cannot move the car and come back.","Valet is not open to the public. The arena reserves it for select guests and membership areas, from about 2 hours before the event, at the Ra Ra Room Valet on Jackson Street between 1st and 2nd Streets, the Annexus Valet on Jackson Street between 2nd and 3rd Streets, and inside the Jefferson Street Garage on the 2nd floor, reached from the garage’s 4th Street entrance. Everyone else is asked to buy parking in advance through ParkWhiz."),B("Where is the drop-off and pickup at Mortgage Matchup Center?","The arena publishes one drop-off and pickup for a game or event: 3rd Street just south of Jefferson, at the green curb; the will-call drop-off is on 1st Street just north of Madison, and no vehicle may be parked or left unattended in a drop-off zone.","For rideshare, the arena lists four Lyft drop-off points: 1st Street and Jefferson at the arena plaza, S 2nd Street by The Ryan, S 3rd Street by the Phoenix Convention Center, and E Jefferson Street by Hotel Palomar and the Arrogant Butcher. After the event, Lyft pickups are at S 3rd Street and E Jefferson Street, by the Phoenix Convention Center.","No separate limo or charter zone is published. A chauffeured group uses the published drop-off on 3rd Street or the point event staff direct on the night. Because no vehicle may wait in a drop-off zone, the chauffeur clears the curb after unloading and comes back when the group is together.","Agree on the pickup before the game or show, and share it with everyone. After the final buzzer or the encore, gather first, then message the chauffeur once with the group count, rather than several people sending pins from inside the arena."),B("Can you take light rail to Mortgage Matchup Center?","Yes: Valley Metro Rail stops at 3rd St/Jefferson, right by the arena, and the arena’s own directions also use the Downtown Phoenix Hub, about 0.3 mile’s walk away, and 3rd St/Washington for riders coming west from Gilbert Rd/Main St.","Southbound from Metro Parkway, the arena says to exit at the Downtown Phoenix Hub’s 1st Ave platform and walk about 0.3 mile, or transfer at the Hub’s Jefferson St platform and exit at 3rd St/Jefferson. Northbound from Baseline/Central Ave, exit at the Hub’s Central Ave platform and walk, or make the same transfer. Eastbound from the Hub, board at the Jefferson St platform and exit at 3rd St/Jefferson.","The arena adds that its bus stops and light rail stations are all on accessible routes to and from the building.","Rail suits a couple staying near a station. A group coming from a Scottsdale resort has more steps: getting everyone to a station, onto one train, and back again together after the game or the show."),B("How do you drive to Mortgage Matchup Center from Scottsdale?","From North Phoenix and Scottsdale, the arena’s own route is State Route 51 south to the Interstate 10 East interchange, the Washington/Jefferson Street exit, right on Washington Street to 3rd Street, then left on 3rd Street to the arena and its drop-off.","From the East Valley and Tempe, take Interstate 10 west to Washington/Jefferson Street, turn left on Washington Street to 3rd Street, then left on 3rd Street. From the west, the arena routes drivers along Jefferson Street to 1st Street, where the arena stands on the corner.","The drive is the easy part. The parking, the no in-and-out rule and the walk back to the car after the game fall on whoever drives, who also has to stay fit to drive home."),B("What is the bag policy at Mortgage Matchup Center?","The arena asks guests to arrive without bags when they can: small clutches and crossbody bags are permitted, purses, medical bags and diaper bags are allowed within 14 x 14 x 6 inches with extra screening, and standard backpacks are not permitted inside.","Guests without bags, or with a clutch smaller than 4 x 6 inches, can use the Evolv express entry lanes, which the arena recommends for the quickest way in. Some concerts and special events run modified item rules, so check your event, or ask the arena at feedback@phxses.com before you go.","A group that is dropped off has no car in a garage to leave a backpack in, so settle bags before pickup. Door times vary by event as well: the arena posts them on each event’s page."),B("Is Footprint Center now Mortgage Matchup Center?","Yes: on October 2, 2025, the Suns and the Mercury announced that their downtown Phoenix arena, home to more than 100 sporting and entertainment events a year, is named Mortgage Matchup Center; before that it was Footprint Center, and it is the same building.","The address is unchanged: 201 E. Jefferson Street. The NBA’s 2024 release awarding Phoenix the 2027 All-Star Game still names it Footprint Center, home of the Phoenix Suns, and guests search for it under both names, so this guide uses both.","On its private-events page the arena calls itself the newly renovated, 18,000 capacity arena."),B("What is on at Mortgage Matchup Center this season?","The Suns open their 2026-27 home schedule against the Golden State Warriors on Saturday, October 24, 2026, their last regular-season home game is Friday, April 9, 2027, and the NBA All-Star Game comes to the arena on Sunday, February 21, 2027, with concerts on the nights between.","The home opener tips off at 7 p.m. Most Suns home games do too, and a few start in the afternoon or at another evening time, so check the tip-off for your game. Concerts fill the nights between games. The arena’s calendar includes Kacey Musgraves on October 17, Gorillaz on October 23, Doja Cat on October 29, Don Omar on November 8, Banda MS on November 28 and Trans-Siberian Orchestra on December 6, then Hans Zimmer on March 30 and Niall Horan on May 20, 2027.","The Mercury’s 2027 home dates and the All-Star weekend schedule are announced closer to the date. Door times vary by event, so check the event’s own page before you set a pickup time."),B("Which vehicle fits a Mortgage Matchup Center group, and what does it cost?",`Match the vehicle to the night: a game-night crew or a company outing starts with the ${fe(je)}, a concert crew with the ${fe(Ye)}, and a courtside or suite party with the ${fe(Ke)}.`,`Every rate prices the whole vehicle by the hour. Here is a ${et}-hour booking in each lead vehicle. ${[je,Ye,Ke].map(an).join(" ")}`,"Those figures are arithmetic from the published rates, not a quote. An hourly booking keeps the vehicle for the whole night, so the drive each way counts toward the hours. A ride there and a separate ride back can be booked as a transfer instead; the written quote shows how the drive is priced."),B("How should a group plan the night at Mortgage Matchup Center?","Plan 4 things before pickup: a ready time worked back from the event’s door time, one agreed pickup point on 3rd Street after the game or show, one person who messages the chauffeur for the group, and bags that pass the arena’s bag policy.","Guests who need a wheelchair escort can ask any guest service representative at the entrances or the guest services office in the main north pavilion, or text 602-379-7668 from 30 minutes before doors until the end of the event. Mobility devices can be checked in the Guest Services Office.",`For a change of plan on the day, call the reservations team at ${F} or email ${M}.`)],on=[{question:"How much is parking at Mortgage Matchup Center?",answer:"The arena publishes no single price: parking rates vary by event. Buy in advance through ParkWhiz to see the price before you drive, or call the Mortgage Matchup Center Parking Office at 602-379-2003."},{question:"Where do you park for Mortgage Matchup Center?",answer:"In the garages and lots within walking distance, bought in advance through ParkWhiz, as the arena recommends. Event parking generally opens about 30 minutes before doors, with no in-and-out privileges."},{question:"Where is the drop-off at Mortgage Matchup Center?",answer:"On 3rd Street just south of Jefferson, at the green curb, for games and events. Vehicles cannot be parked or left unattended in the drop-off zone."},{question:"Where is the rideshare pickup at Mortgage Matchup Center?",answer:"At S 3rd Street and E Jefferson Street, by the Phoenix Convention Center."},{question:"Where is Mortgage Matchup Center?",answer:"At 201 E. Jefferson Street, Phoenix, AZ 85004, on the southeast corner of 1st Street and Jefferson in downtown Phoenix."},{question:"What was Mortgage Matchup Center called before?",answer:"Footprint Center. The Suns and the Mercury announced the Mortgage Matchup Center name on October 2, 2025."},{question:"How many people does Mortgage Matchup Center hold?",answer:"The arena describes itself as an 18,000 capacity arena on its private-events page."},{question:"Can a chauffeured Sprinter drop our group at Mortgage Matchup Center?",answer:"Yes, at the published drop-off on 3rd Street or where event staff direct. No separate limo or charter zone is published, and no vehicle may wait at the curb, so the chauffeur returns when your group is ready."}],sn={path:"/guides/venues/footprint-center",title:"Mortgage Matchup Center Parking Guide: Drop-Off & Rides at the Former Footprint Center",metaTitle:"Mortgage Matchup Center Parking Guide",description:"Where to park for Mortgage Matchup Center, formerly Footprint Center: garages and ParkWhiz, the 3rd Street drop-off, rideshare and light rail, the bag policy, the Suns schedule, and how a chauffeured group ride compares.",metaDescription:"Garages, the 3rd Street drop-off and rideshare",lastUpdated:na,lastUpdatedLabel:T(na),intro:"Scottsdale Sprinters’ short answer on Mortgage Matchup Center, formerly Footprint Center: buy parking ahead through ParkWhiz for the garages and lots within walking distance, plan on parking from about 30 minutes before doors, and remember there is no in-and-out. The arena’s drop-off and pickup for games and events is on 3rd Street just south of Jefferson, at the green curb, and light rail stops at 3rd St/Jefferson. For a group, one chauffeured vehicle replaces the garage, the walk back to the car and the drive home.",sections:nn,faqs:on,links:[{href:`/fleet/${je}`,label:fe(je)},{href:`/fleet/${Ye}`,label:fe(Ye)},{href:`/fleet/${Ke}`,label:fe(Ke)},{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:rn},sa="2026-09-24",hn="/guides/asu-gcu-graduation-transportation",be="executive-sprinter-scottsdale",Ze="executive-white-sprinter-scottsdale",Ne="executive-luxury-bus-29-scottsdale",dt="executive-mini-bus-26-scottsdale",Qe="limo-sprinter-13-scottsdale",ia="limo-sprinter-16-scottsdale",ct="party-bus-28-scottsdale",ut="maybach-jet-sprinter-scottsdale",pt="ultra-luxury-party-sprinter-scottsdale",ft="maybach-shuttle-sprinter-8",mt="premium-suv-scottsdale",u=e=>n[e],W=e=>c[e],ln="https://graduation.asu.edu/undergraduate-commencement",dn="https://graduation.asu.edu/graduate-commencement",cn="https://graduation.asu.edu/ceremonies/schedule",un="https://graduation.asu.edu/guests/parking",pn="https://graduation.asu.edu/know-before-you-go",fn="https://graduation.asu.edu/ceremonies/inclement-weather-plan-mountain-america-stadium",mn="https://graduation.asu.edu/ceremonies/futuredates",gn="https://traditionalcommencement.gcu.edu/",yn="https://traditionalcommencement.gcu.edu/files/2026/09/WN26-Trad-Parking-Updated.pdf",bn="https://traditionalcommencement.gcu.edu/files/2026/09/24EVT0093-WN26TradFAQ-FLY_FINAL_WORD.pdf",wn=[{label:"ASU Undergraduate Commencement, Fall 2026",href:ln},{label:"ASU Graduate Commencement, Fall 2026",href:dn},{label:"ASU Fall 2026 ceremony schedule",href:cn},{label:"ASU graduation parking and transportation",href:un},{label:"ASU graduation: know before you go",href:pn},{label:"ASU inclement weather plan, Mountain America Stadium",href:fn},{label:"ASU future commencement dates and live streams",href:mn},{label:"GCU traditional commencement, Winter 2026",href:gn},{label:"GCU Winter 2026 commencement parking instructions (PDF)",href:yn},{label:"GCU Winter 2026 commencement FAQ (PDF)",href:bn}];function Z(e,t,...a){return{question:e,answer:t,paragraphs:a}}const vn=[Z("When is ASU graduation in December 2026?","ASU’s fall 2026 University Commencement is Monday, December 14, 2026, on the Tempe campus: Graduate Commencement at 9:00 a.m. in Desert Financial Arena, and Undergraduate Commencement at 2:00 p.m. at Mountain America Stadium, on Frank Kush Field. Neither ceremony needs tickets.","For the undergraduate ceremony, graduates should arrive no later than 1:30 p.m. to sit with their college, and seating is released to the general public at 1:45 p.m. ASU lists the ceremony as ending at 3:30 p.m., and the graduate ceremony at 11:00 a.m.","The same week holds the other ceremonies: celebrations on December 11 and 12, Barrett, The Honors College Convocation at 11:00 a.m. on December 14 at ASU Gammage, The College of Liberal Arts and Sciences Convocation at 7:30 p.m. on December 14 at the stadium, and college convocations on December 15, 16 and 17, most of them in Desert Financial Arena or ASU Gammage. The ASU Online Celebration is December 16 at 11:30 a.m. in the Student Pavilion.","ASU says times and locations are subject to change; the schedule was last updated on August 26, 2026. Recheck it the week before, and plan the ride around the ceremony your graduate is actually walking in.","Spring 2027 University Commencement is May 10, 2027, by ASU’s future-dates calendar, which also says dates can change. This page is updated for May when ASU posts that schedule."),Z("Where do you park for ASU graduation, and where can you be dropped off?","ASU’s commencement parking is complimentary and first come, first served: Lot 58, Lot 59 and the Packard Drive Structure for Mountain America Stadium, and Lot 59 and the Packard Drive South Garage for Desert Financial Arena. The overflow for both is the Novus Parking Structure, which takes payment on the way out.","ASU warns that large attendance creates traffic around both venues and that exits from the lots and structures will be delayed, and it strongly encourages public transportation. ASU Gammage and the Student Pavilion use Lot 3.","Mountain America Stadium is at 500 E Veterans Way, Tempe, AZ 85287, and Desert Financial Arena at 600 E Veterans Way, Tempe, AZ 85281. Accessible parking is available at each venue with a placard or plate, and ASU publishes an ADA courtesy shuttle map for the arena and the stadium.","ASU publishes no drop-off lane for limousines, charters or rideshare at commencement; its maps mark only the ADA courtesy shuttle stop. So your chauffeur drives the approach and unloads where campus event staff and police direct, and you agree the pickup point before the ceremony, not after it. When ASU publishes more for December, that replaces this paragraph.","The parking maps on ASU’s page were last updated in December 2025 for the stadium and April 2026 for the arena. Recheck them the week of the ceremony."),Z("When is GCU graduation in December 2026?","GCU’s Winter 2026 traditional commencement is Thursday, December 17 and Friday, December 18, 2026, with ceremonies at 10 a.m. and 4 p.m. each day in Global Credit Union Arena, Phoenix. Each ceremony runs about an hour to an hour and a half.","December 17 at 10 a.m.: the College of Engineering and Technology and the College of Natural Sciences. December 17 at 4 p.m.: the College of Arts and Media, the College of Education, and the College of Humanities and Social Sciences.","December 18 at 10 a.m.: the Colangelo College of Business and the College of Theology. December 18 at 4 p.m.: the College of Engineering and Technology, the College of Natural Sciences, and the College of Nursing and Healthcare Professions.","Doors open two hours before each ceremony, and GCU asks ticketed guests to be seated at least 30 minutes before the start. Guests need general admission tickets: each registered graduate can reserve up to six, children three and under sit on a lap, and an overflow area shows the live stream.","GCU says its spring 2027 traditional commencement will be announced shortly after the winter ceremonies."),Z("Where do you park or get dropped off for GCU graduation?","GCU parks commencement guests in the 33rd Avenue garage beside Global Credit Union Arena, 3300 W. Camelback Road, with more parking in the 31st Avenue garage at 3050 W. Camelback Road. Its rideshare drop-off and pickup address is 3300 W. Camelback Road.","Phoenix police officers direct traffic during the ceremonies and may send drivers to another lot. Classes are in session that week, so GCU expects traffic to and on campus to be exceptionally busy, and asks guests to allow 30 to 45 minutes more for parking and the walk into the arena.","From the north on I-17, exit at Camelback Road and head to 33rd Avenue. From the south, exit at Bethany Home Road, take 35th Avenue south, then Camelback Road east to the garage. GCU estimates 30 to 45 minutes from Scottsdale and 45 minutes to an hour from Mesa, Gilbert and Chandler, before parking.","GCU names no separate lane for limousines or charters, so your chauffeur follows the officers on the day and meets the family at the pickup point you agreed."),Z("What can you bring into the ceremony?","Both universities enforce a clear bag policy. At GCU the limit is 12 by 12 by 6 inches, with metal detectors and bag checks, and there is no storage. At ASU the policy covers Mountain America Stadium and every ASU venue, and umbrellas are not allowed in the stadium.","GCU does not allow balloons, flags or banners, wrapped packages or gifts, noisemakers, alcohol, glass, strollers, wagons or car seats. Flowers are sold at a booth near the arena. ASU does not allow banners, flags or signs inside any venue, and allows clear, factory-sealed water bottles up to 1.5 liters at the stadium.","Book the vehicle by the hour and the flowers, balloons and gifts can stay on board during the ceremony, ready for the photos after."),Z("What happens if it rains on ASU commencement day?","ASU’s undergraduate commencement is outdoors and takes place rain or shine. If weather forces a delay, ASU may hold the start for up to an hour; if the ceremony cannot be held in the stadium, it is canceled, because no indoor space on campus holds the graduates and 30,000 or more guests.","ASU advises guests to bring ponchos or rain gear, since umbrellas are not allowed, and to prearrange a meeting place outside the stadium in case the ceremony is canceled.","Make that meeting place your pickup point. The chauffeur knows where it is before the ceremony starts, and nobody has to find the family in a crowd leaving at once."),Z("How long is graduation day, and how many hours should you book?","Plan the ceremony, the photos and a meal. ASU lists its undergraduate ceremony as starting at 2:00 p.m. and ending at 3:30 p.m., and GCU’s ceremonies last about an hour to an hour and a half, with doors open two hours before. A ceremony and a family dinner fit a four-hour block; an airport pickup or a party after needs more.","Book by the hour and the vehicle and chauffeur stay with you for the whole block: the pickup, the wait during the ceremony, the photos, dinner and the ride home. Or book a ride there and a ride back.","Every vehicle has a minimum number of hours, shown with its price on this page. Longer bookings earn free hours on the same published ladder as every other ride.",`Reach the reservations team at ${F} or ${M} with the ceremony, the pickup area, the number of riders and the plan after.`),Z("Which vehicle fits which graduation group?",`Graduates and their families ride the ${u(be)} or the ${u(Ze)}, or the ${u(Ne)} or the ${u(dt)} for a big family. The grad party crew takes a Limo Party Sprinter or the ${u(ct)}. A VIP family celebration takes the ${u(ut)}, the ${u(pt)}, the ${u(ft)} or the ${u(mt)}.`,`Our pick for graduation day is the ${u(be)}: black-on-black leather shuttle seats that each recline, room for the whole family, and space for forty bags, so the flowers, gifts and gowns ride along. It delivers on every metric without the limo styling, which is what a day in caps and gowns calls for.`,`Seat counts are seated capacities from the fleet: the ${u(be)} and the ${u(Ze)} seat ${W(be)} each, the ${u(Ne)} ${W(Ne)}, the ${u(dt)} ${W(dt)}, the ${u(Qe)} ${W(Qe)}, the ${u(ia)} ${W(ia)}, the ${u(ct)} ${W(ct)}, the ${u(ut)} ${W(ut)}, the ${u(pt)} ${W(pt)}, the ${u(ft)} ${W(ft)} and the ${u(mt)} ${W(mt)}.`,`When a family outgrows its row, the page never offers it a party vehicle; for a group bigger than the ${u(Ne)}, we plan two vehicles and quote them together. If anyone riding is under 21, no alcohol comes on board for the whole trip.`)],kn=[{question:"Where do you park for ASU graduation?",answer:"ASU’s commencement parking is free and first come, first served: Lot 58, Lot 59 and the Packard Drive Structure for Mountain America Stadium, and Lot 59 and the Packard Drive South Garage for Desert Financial Arena. The Novus Parking Structure is the paid overflow. ASU warns that exits will be delayed and encourages public transportation."},{question:"Is there a drop-off area for ASU commencement?",answer:"ASU publishes no drop-off lane for limousines, charters or rideshare at commencement; its maps mark only the ADA courtesy shuttle stop. A chauffeur unloads where campus event staff and police direct."},{question:"Where is the GCU graduation rideshare drop-off?",answer:"GCU’s rideshare drop-off and pickup address is 3300 W. Camelback Road, Phoenix, beside Global Credit Union Arena. Guest parking is the 33rd Avenue garage there, with more in the 31st Avenue garage. Phoenix police direct traffic during the ceremonies."},{question:"When is ASU graduation 2026?",answer:"Monday, December 14, 2026: Graduate Commencement at 9:00 a.m. in Desert Financial Arena and Undergraduate Commencement at 2:00 p.m. at Mountain America Stadium, both in Tempe. College convocations run December 14 to 17."},{question:"When is GCU graduation 2026?",answer:"Thursday, December 17 and Friday, December 18, 2026, at 10 a.m. and 4 p.m. each day, in Global Credit Union Arena, Phoenix. Doors open two hours before each ceremony."},{question:"Do you need tickets for ASU graduation?",answer:"Not for University Commencement: neither the graduate nor the undergraduate ceremony requires tickets, and stadium guest seating is first come, first served. Some convocations and celebrations do require tickets; ASU’s schedule marks which."},{question:"How many guest tickets do you get for GCU graduation?",answer:"Each registered graduate can reserve up to six general admission guest tickets. Children three and under do not need one but sit on a ticketed guest’s lap, and an overflow area shows the live stream."},{question:"How long is the ASU graduation ceremony?",answer:"ASU lists Undergraduate Commencement as starting at 2:00 p.m. and ending at 3:30 p.m., and Graduate Commencement as starting at 9:00 a.m. and ending at 11:00 a.m. Allow time before for the crowd and after for photos."},{question:"What is the ASU graduation bag policy?",answer:"Mountain America Stadium and every ASU venue have a clear bag policy, and umbrellas are not allowed in the stadium. Guests with a bag that does not comply are asked to return it to their car."},{question:"Can you watch ASU graduation online?",answer:"Yes. ASU streams its ceremonies live; each one’s link is on the ceremony schedule and in the ASU Mobile app. GCU streams every ceremony too, and posts the videos on its YouTube channel afterward."},{question:"When is ASU graduation in spring 2027?",answer:"ASU’s future-dates calendar lists Spring 2027 University Commencement on May 10, 2027, subject to change. GCU will announce its spring 2027 ceremonies after the winter ones."}],Sn={path:hn,title:"ASU & GCU graduation 2026: dates, parking and rides",metaTitle:"ASU & GCU Graduation 2026 Parking",description:"ASU commencement is Monday, December 14, 2026, at Desert Financial Arena and Mountain America Stadium; GCU’s ceremonies are December 17 and 18 at Global Credit Union Arena. Official times, parking, drop-off and bag rules, and a chauffeured ride for the family.",metaDescription:"ASU on December 14, GCU on December 17 and 18: times, parking, drop-off and a ride",lastUpdated:sa,lastUpdatedLabel:T(sa),eyebrow:"Graduation: ASU December 14 · GCU December 17 and 18, 2026",intro:"A graduation ride from Scottsdale Sprinters starts with the ceremony your graduate is walking in: ASU’s commencement in Tempe or GCU’s in Phoenix. This guide uses only what the two universities have published, and says plainly what they have not.",sections:vn,faqs:kn,links:[{href:`/fleet/${be}`,label:u(be)},{href:`/fleet/${Ze}`,label:u(Ze)},{href:`/fleet/${Qe}`,label:u(Qe)},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/service-areas/phoenix",label:"Phoenix service area"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport Sprinter van service"},{href:"/pricing",label:"Published hourly pricing"}],sources:wn},ha="2026-09-24",An="/guides/cactus-league-spring-training",De="maybach-jet-sprinter-scottsdale",Re="ultra-luxury-party-sprinter-scottsdale",la="maybach-shuttle-sprinter-8",da="premium-suv-scottsdale",ca="limo-sprinter-13-scottsdale",Xe="limo-sprinter-16-scottsdale",gt="party-bus-28-scottsdale",Ie="executive-sprinter-scottsdale",Tn="executive-white-sprinter-scottsdale",ua="executive-mini-bus-26-scottsdale",yt="executive-luxury-bus-29-scottsdale",y=e=>n[e],E=e=>c[e],$n="https://cactusleague.com/schedule.php",Cn="https://www.mlb.com/giants/spring-training/a-z-guide",Pn="https://saltriverfields.com/welcome-to-salt-river-fields/",Fn="https://saltriverfields.com/parking/",Mn="https://www.mlb.com/camelback-ranch/your-visit/information-and-policies",En="https://www.mlb.com/cubs/sloan-park/transportation",Dn="https://www.mlb.com/athletics/spring-training/guide",Rn="https://www.mlb.com/angels/spring-training/ballpark",In="https://www.mlb.com/brewers/spring-training/trip-planning",xn="https://www.peoriasportscomplex.com/spring-training/find-info/maps-directions",Wn="https://www.surprisestadium.com/stadium-info/stadium-a-z",Gn="https://www.goodyearbp.com/Ballpark-Visitors/Directions-and-Parking",Nn="https://www.mlb.com/guardians/spring-training/a-to-z-guide",Ln="https://www.mlb.com/news/mlb-commissioner-rob-manfred-on-initial-cba-proposals",_n=[{label:"Cactus League 2027 schedule",href:$n},{label:"Scottsdale Stadium spring training A to Z (San Francisco Giants)",href:Cn},{label:"Welcome to Salt River Fields: rideshare and address",href:Pn},{label:"Salt River Fields parking and directions",href:Fn},{label:"Sloan Park transportation (Chicago Cubs)",href:En},{label:"Camelback Ranch information and policies",href:Mn},{label:"Hohokam Stadium spring training guide (Athletics)",href:Dn},{label:"Tempe Diablo Stadium ballpark information (Angels)",href:Rn},{label:"American Family Fields of Phoenix trip planning (Brewers)",href:In},{label:"Peoria Sports Complex maps and directions",href:xn},{label:"Surprise Stadium A to Z",href:Wn},{label:"Goodyear Ballpark directions and parking",href:Gn},{label:"Goodyear Ballpark spring training A to Z (Cleveland Guardians)",href:Nn},{label:"MLB.com: the collective bargaining agreement’s expiry date",href:Ln}];function Q(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Un={head:["Ballpark (teams)","Drop-off or rideshare","Parking and gates"],rows:[["Camelback Ranch-Glendale (Dodgers, White Sox)","None published; staff direct","Free, no overnight parking; gates 60 minutes before first pitch"],["Hohokam Stadium, Mesa (Athletics)","None published; staff direct","Cash only; gates 1.5 hours before game time"],["Tempe Diablo Stadium (Angels)","Just outside the Alameda Drive entrance to the west lot, never inside it","Cashless; lots open 2.5 hours before home games"],["American Family Fields of Phoenix (Brewers)","Along 53rd Avenue and Indian School, outside the lot","Sold on the day, card only, more for larger vehicles; lots open 3 hours before"],["Peoria Sports Complex (Padres, Mariners)","Stadium Way and Paradise Lane, west of Gate D; buses at Mariners Way","Free, no overnight parking; gates about 90 minutes before"],["Surprise Stadium (Rangers, Royals)","Loading zone just north of the Surprise Aquatic Center","Free, more than 1,600 spaces; gates 1.5 hours before"],["Goodyear Ballpark (Guardians, Reds)","VIP lot off Wood Boulevard, or the Third Base Entrance","Free with a game ticket; gates 1.5 hours before"]]},Bn=[Q("Is there parking at Scottsdale Stadium, and where is the drop-off?","Very little. The Giants say parking at Scottsdale Stadium is very limited, with a select number of spaces at the Scottsdale Library and Civic Center, and they encourage fans to walk, bike or take rideshare. The drop-off zones are at Gate A on 75th Street and Gate E on Drinkwater Boulevard, and gates open 2 hours before game time.","The Osborn Road lot is reserved for Giants and City of Scottsdale personnel only, so it is not a place to park or to wait. The stadium has four gates: Home Plate Plaza at Drinkwater Boulevard and Osborn Road, Gate A in centerfield facing 75th Street, Gate E on the third-base side along Drinkwater Boulevard, and Gate F in the left-field corner.","The Giants list the Gate A and Gate E drop-off zones under accessibility. We treat them as the stadium’s published drop-off points, never as a spot reserved for us: the chauffeur unloads at the zone, or where stadium and city staff direct, and the group walks in from there. A 2027 spring training trolley has not been announced.","The chauffeured alternative is the simple one: we pick the group up at the hotel or home, nobody hunts for one of the few spaces, and the vehicle comes back for the ride home after the last out. Game times are announced closer to the date, so the pickup is set once the league posts them."),Q("Where do you park at Sloan Park, and where do rideshares drop off?","Sloan Park’s lots open 4 hours before Cubs spring training games, and gameday parking is first come, first served and cashless, by credit card. Rideshares drop off and pick up outside the Right Field Gate, across Sheffield Avenue, and a free shuttle runs from Mesa Riverview, across from the park, to Cubs home games.","Tempe Marketplace also runs a trolley to and from Cubs home games at Sloan Park. Both shuttles drop off at the First Base Gate. Parking prices depend on the lot, and the Cubs sell a limited number of pre-sale single-game and group spaces in the Purple Lot.","Sloan Park is the Cubs’ spring home in Mesa, and the league’s last game of 2027, the Brewers at the Cubs on Tuesday, March 23, is played there. A chauffeured group uses the published rideshare point outside the Right Field Gate, or unloads where staff direct, and meets the vehicle at the same side of Sheffield Avenue after the game."),Q("Where do rideshares and drop-offs go at Salt River Fields?","Salt River Fields at Talking Stick, at 7555 North Pima Road in Scottsdale, suggests the access road along the grass-field parking lots, or the Centerfield Parking Lots, for pickup and drop-off. There are 3 entrances off Pima Road. It is the spring home of the Diamondbacks and the Rockies.","The ballpark’s 2027 lot prices and its accessible drop-off are not yet published: its A to Z still describes the 2026 season, so this page prints neither. Our Salt River Fields arrival guide keeps the venue’s own sources in one place.","Salt River Fields and Scottsdale Stadium are the two Scottsdale ballparks. For the ride back, the group gathers at one pedestrian point first and the trip lead confirms the vehicle’s position before anyone walks toward traffic; event-day signs and staff direct the actual vehicle movement."),{...Q("Where do you park and get dropped off at the other Cactus League ballparks?","Each park sets its own rules. Camelback Ranch, Peoria Sports Complex and Surprise Stadium park free, and Goodyear Ballpark is free with a game ticket; Hohokam Stadium is cash only, and Tempe Diablo and American Family Fields are cashless or card only. Only Peoria publishes a bus drop-off, at Mariners Way off 83rd Avenue.","Camelback Ranch-Glendale (the Dodgers and the White Sox): parking is free, with no overnight parking, and the gates open 60 minutes before first pitch. No rideshare or drop-off zone is published, so the chauffeur unloads where ballpark staff direct.","Hohokam Stadium in Mesa (the Athletics): on-site parking is cash only, and the gates open 1.5 hours before game time. No rideshare or drop-off zone is published.","Tempe Diablo Stadium (the Angels): rideshare drop-off and pickup is just outside the Alameda Drive entrance to the west parking lot, and no pickup or drop-off is allowed inside that lot. Both lots are entered from Alameda Drive and open 2.5 hours before home games, and the venue is cashless.","American Family Fields of Phoenix (the Brewers): drop-offs and rideshares use the designated space along 53rd Avenue and Indian School, outside the parking lot. Parking is sold on the day only, by card, with more charged for oversized and larger vehicles, and the lots open 3 hours before the game.","Peoria Sports Complex, 16101 North 83rd Avenue (the Padres and the Mariners): rideshare pickup and drop-off is near Stadium Way and Paradise Lane, just west of the Gate D entrance. Buses enter at Mariners Way off 83rd Avenue, where the bus passenger drop-off is. Parking is free, with no overnight parking, and the gates typically open 90 minutes before the published game time.","Surprise Stadium (the Rangers and the Royals): the designated rideshare and drop-off loading zone is just north of the Surprise Aquatic Center. Parking is free, with more than 1,600 spaces, and the gates open 1.5 hours before game time.","Goodyear Ballpark, 1933 South Ballpark Way (the Guardians and the Reds): rideshare pickup and drop-off is in the VIP parking lot, reached from Wood Boulevard north of Lower Buckeye Road, and drop-off is also available at the Third Base Entrance. Parking is free with a game ticket, with no overnight parking, and the gates open 1.5 hours before game time."),table:Un},Q("When is spring training in Arizona in 2027?","As scheduled by the Cactus League, Opening Day is Friday, February 19, 2027, with 8 games, and the last Cactus League game is Tuesday, March 23, 2027. That is 229 games in about five weeks. Game times are announced closer to the date: the league lists every one of them as to be determined.","One date to know before you book: Major League Baseball’s collective bargaining agreement with its players is set to expire on December 1, 2026. The dates on this page are the Cactus League’s published schedule. We recheck them after December 1 and update this page if the league changes anything.",`If a game you planned around moves, every booking allows one free date change when you ask ${La} or more hours before pickup, subject to availability: the deposit travels to the new date and the new date’s rate applies.`,`Saturday and Sunday games in the Cactus League window, February 19 to March 23, 2027, are major-event dates on our booking calendar, so they run on the ${pr}-day major-event cancellation window, with the deposit non-refundable. Weekday games follow the standard or large-group terms, depending on the size of the group. The booking step flags a major-event date before anything is paid.`),Q("Where is spring training in Arizona, and which teams play where?","Fifteen Major League teams train at 10 ballparks around Phoenix: Scottsdale Stadium and Salt River Fields in Scottsdale, Sloan Park and Hohokam Stadium in Mesa, Tempe Diablo Stadium, Camelback Ranch-Glendale, American Family Fields of Phoenix, Peoria Sports Complex, Surprise Stadium and Goodyear Ballpark.","Scottsdale Stadium: the Giants. Salt River Fields at Talking Stick: the Diamondbacks and the Rockies. Sloan Park: the Cubs. Hohokam Stadium: the Athletics. Tempe Diablo Stadium: the Angels. Camelback Ranch-Glendale: the Dodgers and the White Sox. American Family Fields of Phoenix: the Brewers. Peoria Sports Complex: the Padres and the Mariners. Surprise Stadium: the Rangers and the Royals. Goodyear Ballpark: the Guardians and the Reds.","The two Scottsdale parks, the two Mesa parks and Tempe Diablo are in the East Valley; Camelback Ranch, American Family Fields, Peoria, Surprise and Goodyear are in the West Valley. A two-ballpark day is simplest between neighbours, and it is one hourly booking: the first game, lunch, the second park and the ride home, confirmed once both game times are posted.","Which team plays where on a given day is the league’s to publish. Check the official Cactus League schedule for the game, buy the tickets from the teams, and send us the game or games; we build the pickup, the wait and the return around them in writing."),Q("Which vehicle fits a spring training group?",`Match the vehicle to the day: ballpark crews and bachelor groups ride a Limo Party Sprinter or the ${y(gt)}, families and fan clubs take the ${y(Ie)} or an executive coach for up to ${E(yt)}, and VIP groups ride the ${y(De)} or the ${y(Re)}.`,`Ballpark crews and bachelor groups: the ${y(ca)} is a nightclub on wheels with a wet bar for ${E(ca)}, the ${y(Xe)} is our most spacious Sprinter, a lounge for ${E(Xe)} with four wet bars, and the ${y(gt)} puts ${E(gt)} on limo seating on a wood floor when the whole crew comes. These are party rides, for a group out to celebrate.`,`Families and fan clubs: the ${y(Ie)} and the ${y(Tn)} seat ${E(Ie)} each in reclining leather, a cup holder at every seat and room for the gear. The ${y(ua)} (${E(ua)} seats) and the ${y(yt)} (${E(yt)} seats) carry a fan club or a company outing in one pickup.`,`VIP groups: the ${y(De)} leads, ${E(De)} seats with four Maybach massage recliners and a wet bar. The ${y(Re)} seats ${E(Re)} in a fiber-optic lounge with ultra-premium sound, our pick for a ballpark day that ends in Old Town. The ${y(la)} seats ${E(la)} in custom Maybach seats, and the ${y(da)} carries up to ${E(da)}.`,"Count riders for each direction. A group that arrives together for first pitch does not always leave together, and anyone leaving with another group comes off the return list before the chauffeur plans the pickup."),Q("Can a party bus, limo or charter drop off at a spring training ballpark?","Only Peoria Sports Complex publishes a bus rule: buses enter at Mariners Way off 83rd Avenue, where the bus passenger drop-off is. None of the 10 ballparks publishes a permit rule for limos or party buses, so our chauffeur uses the park’s published drop-off or rideshare zone, or unloads where staff direct.","Two other published rules matter for a bigger vehicle. American Family Fields charges more for oversized and larger vehicles that park, and Tempe Diablo Stadium allows no pickup or drop-off inside its west lot. Where the vehicle waits during the game is confirmed with the reservations team before the day, not decided at the gate.","For the ride back, name one meeting point and one trip lead before the group goes in. After the last out the lead counts heads, confirms the vehicle’s position with the chauffeur and walks the group there together, rather than everyone chasing a map pin at once.",`We are a chauffeured transportation service. We do not sell tickets, parking passes or admission, and a ride includes none of them. Questions this page does not answer go to the reservations team at ${F} or ${M}.`)],On=[{question:"When is spring training in Arizona in 2027?",answer:"As scheduled by the Cactus League, Opening Day is Friday, February 19, 2027, with eight games, and the last Cactus League game is Tuesday, March 23, 2027. Game times are announced closer to the date."},{question:"Where is spring training in Arizona?",answer:"At ten ballparks around Phoenix: Scottsdale Stadium and Salt River Fields in Scottsdale, Sloan Park and Hohokam Stadium in Mesa, Tempe Diablo Stadium, Camelback Ranch-Glendale, American Family Fields of Phoenix, Peoria Sports Complex, Surprise Stadium and Goodyear Ballpark."},{question:"What teams have spring training in Arizona?",answer:"Fifteen: the Giants, the Diamondbacks and Rockies, the Dodgers and White Sox, the Cubs, the Athletics, the Angels, the Brewers, the Padres and Mariners, the Rangers and Royals, and the Guardians and Reds."},{question:"What is the Cactus League?",answer:"Major League Baseball’s spring training in Arizona. In 2027, as scheduled by the Cactus League, 15 teams play 229 games at 10 ballparks from February 19 to March 23."},{question:"Is there parking at Scottsdale Stadium?",answer:"Very little. The Giants say parking is very limited, with a select number of spaces at the Scottsdale Library and Civic Center, and encourage walking, biking or rideshare. The drop-off zones are at Gate A on 75th Street and Gate E on Drinkwater Boulevard."},{question:"Where do you park at Sloan Park?",answer:"The lots open four hours before Cubs spring training games; parking is first come, first served and cashless. Rideshares use the point outside the Right Field Gate, across Sheffield Avenue, and a free shuttle runs from Mesa Riverview."},{question:"Where do rideshares drop off at Salt River Fields?",answer:"On the access road along the grass-field parking lots, or at the Centerfield Parking Lots. Salt River Fields is at 7555 North Pima Road, with three entrances off Pima Road."},{question:"Where do you park at Camelback Ranch?",answer:"Parking at Camelback Ranch-Glendale is free, with no overnight parking, and the gates open 60 minutes before first pitch. No rideshare or drop-off zone is published."},{question:"Could the MLB labor talks change the 2027 dates?",answer:`MLB’s collective bargaining agreement with its players is set to expire on December 1, 2026. The dates here are the Cactus League’s published schedule; we recheck them after December 1, and every booking allows one free date change ${La} or more hours before pickup.`},{question:"Do you sell spring training tickets or parking?",answer:"No. We sell chauffeured transportation only. Tickets come from the teams and the league, and parking from the ballparks; with a chauffeured ride, nobody in the group needs a parking space."}],qn={path:An,title:"Spring Training 2027 in Arizona: ballpark drop-off, parking and rides",metaTitle:"Spring Training 2027: Parking & Rides",description:"Cactus League spring training 2027 runs February 19 to March 23 at ten ballparks around Phoenix. The official dates, the fifteen teams, each ballpark’s parking, rideshare and drop-off rules, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Feb 19 – Mar 23 dates, parking and drop-off at all 10 ballparks",lastUpdated:ha,lastUpdatedLabel:T(ha),eyebrow:"As scheduled: February 19 to March 23, 2027",intro:"A spring training ride from Scottsdale Sprinters starts with the day your group is having: a ballpark crew or a bachelor weekend at the game, a family or a fan club with a few games on the list, or a VIP day in the Maybach Jet. This guide covers the ten Cactus League ballparks with only what the league, the teams and the ballparks publish, and says plainly what is announced closer to the date.",sections:Bn,faqs:On,links:[{href:"/experiences/spring-training",label:"Spring training group transportation: rates and two-game days"},{href:"/guides/venues/salt-river-fields",label:"Salt River Fields group arrival guide"},{href:"/guides/scottsdale-event-transportation",label:"Scottsdale event transportation guide"},{href:"/services/bachelor-party-transportation-scottsdale",label:"Bachelor party transportation"},{href:`/fleet/${Re}`,label:y(Re)},{href:`/fleet/${Xe}`,label:y(Xe)},{href:`/fleet/${Ie}`,label:y(Ie)},{href:`/fleet/${De}`,label:y(De)},{href:"/pricing",label:"Published hourly pricing"}],sources:_n},pa="2026-09-25",Hn="/guides/venues/desert-diamond-arena",ie="ultra-luxury-party-sprinter-scottsdale",bt="maybach-jet-sprinter-scottsdale",zn="maybach-shuttle-sprinter-8",Vn="premium-suv-scottsdale",we="limo-sprinter-13-scottsdale",fa="limo-sprinter-16-scottsdale",wt="executive-sprinter-scottsdale",he="party-bus-28-scottsdale",Le="executive-luxury-bus-29-scottsdale",vt="executive-mini-bus-26-scottsdale",p=e=>n[e],X=e=>c[e],kt=e=>`${g(s[e].hourlyRateCents)} an hour with a ${s[e].minimumHours}-hour minimum`,Ae="https://www.desertdiamondarena.com",Jn=`${Ae}/venue-info/`,jn=`${Ae}/venue-info/parking/`,Yn="https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/asm-glendale/Parking_Map_0b35a191-a8e4-47e1-bca1-e73b26128e02.jpg",Kn=`${Ae}/venue-info/azguide/`,Zn=`${Ae}/events-tickets/`,Qn=`${Ae}/events-tickets/seat-map/`,Xn=`${Ae}/events-tickets/box-office/`,eo="https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/asm-glendale/DDA_Private_Event_Deck_2026_91290cc0-c10b-4ec7-b259-f9be05e09cf7.pdf",to="https://www.pbr.com/news/2026/05/pbr-world-finals-championship-to-be-held-in-glendale-arizona-may-20-23-2027/",ao="https://westgateaz.com/",ro="https://www.valleymetro.org/how-to-ride/destinations/destinations-west-valley",Yt=_a.filter(e=>e.featured),at=Yt.find(e=>e.label==="Jonas Brothers"),Kt=Yt.find(e=>e.label==="Pentatonix"),xe=Yt.find(e=>e.kind==="sports"),no=[{label:"Desert Diamond Arena, venue information",href:Jn},{label:"Desert Diamond Arena, parking and directions",href:jn},{label:"Desert Diamond Arena, official parking map",href:Yn},{label:"Desert Diamond Arena, A to Z guide and bag policy",href:Kn},{label:"Desert Diamond Arena, event calendar",href:Zn},{label:"Desert Diamond Arena, seat map",href:Qn},{label:"Desert Diamond Arena, box office",href:Xn},{label:"Desert Diamond Arena, Jonas Brothers event page",href:at.url},{label:"Desert Diamond Arena, PBR World Finals 2027 event page",href:xe.url},{label:"PBR, World Finals Championship in Glendale, May 20–23, 2027",href:to},{label:"Desert Diamond Arena, 2026 private events guide (capacity)",href:eo},{label:"Westgate Entertainment District",href:ao},{label:"Valley Metro, West Valley destinations",href:ro}],oo={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"},Fe=["January","February","March","April","May","June","July","August","September","October","November","December"];function St(e){const[t,a,o]=e.split("-").map(Number),h=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][new Date(Date.UTC(t,a-1,o)).getUTCDay()];return`${oo[h]}, ${Fe[a-1]} ${o}, ${t}`}function U(e){const[t,a,o]=e.dates.start.split("-").map(Number);if(!e.dates.end||e.dates.end===e.dates.start)return`${Fe[a-1]} ${o}, ${t}`;const[,h,$]=e.dates.end.split("-").map(Number);return h===a?`${Fe[a-1]} ${o} to ${$}, ${t}`:`${Fe[a-1]} ${o} to ${Fe[h-1]} ${$}, ${t}`}function so(e){const t=e.dates.end&&e.dates.end!==e.dates.start?`${St(e.dates.start)} to ${St(e.dates.end)}`:St(e.dates.start),a=[e.doors?`doors ${Zt(e.doors)}`:null,e.starts?`${e.dates.end&&e.dates.end!==e.dates.start?"first show":"show"} ${Zt(e.starts)}`:null].filter(Boolean);return`${t}: ${e.title}${a.length?` (${a.join(", ")})`:""}.`}function O(e,t,...a){return{question:e,answer:t,paragraphs:a}}const io=[O("Where is Desert Diamond Arena?","Desert Diamond Arena is at 9400 West Maryland Avenue, Glendale, AZ 85305, in the Westgate Entertainment District off Loop 101. State Farm Stadium is directly south across Maryland Avenue, and Westgate’s shops and restaurants are directly north across Entertainment Boulevard.","From Loop 101, exit 7A is Maryland Avenue and exit 7B is Glendale Avenue; the arena’s own parking map routes cars into its lots from both. The arena sits on 13.5 acres, is managed by Legends Global, and says it entertains over one million visitors a year with concerts, family shows and sporting events.","By Google’s typical drive time, measured on September 24, 2026 without event traffic, the arena is 23 minutes from downtown Phoenix, 28 minutes from Phoenix Sky Harbor, and 36 minutes from Old Town Scottsdale or Kierland. Show nights add the arena’s own traffic to the last mile.","Valley Metro lists no light rail to the Westgate area. Its West Valley destinations page gives the Westgate Entertainment District one bus connection, Route 70."),O("How does parking work at Desert Diamond Arena?","Arena parking lots open one hour before doors. On the day, spaces are in lots G, J, L, Yellow, the Garage and VIP, as each event allows, and the entrances take credit or debit cards only, no cash. A pre-paid space, bought on the event page up to an hour before the event, is guaranteed until 30 minutes after the start.","Pre-paid parking is shown at the entrance from the Ticketmaster app, the ParkWhiz confirmation email or a ParkWhiz account. The arena says it gives faster entry and exit and closer spaces. Its VIP parking, sold on the event pages, is reserved front-row parking with an express lane in and out, in limited numbers.","Every pass covers one standard 12 by 18 foot space, and oversized vehicles must buy additional spaces. Overnight parking and camping are not permitted. Accessible parking is first come, first served in Lots G, J and the Garage for a valid placard or plate, with a pre-purchased permit or a day-of fee.","The arena’s pages publish no parking price: it is set by event and shown when you buy the space through the event page. Pay by card, and pre-pay when the lot matters to your group."),O("Where do rideshare and chauffeured groups drop off at Desert Diamond Arena?","Desert Diamond Arena publishes no rideshare, limo, charter or bus drop-off zone on its parking page, its A to Z guide or its event pages, so a chauffeured group unloads where arena staff and police direct on the night, and agrees one pickup point for the ride home before the show.","Nothing here is a reserved lane for booked vehicles. The chauffeur drives the approach the event’s traffic allows, lets the group out where staff direct, and meets it at the agreed point once the crowd clears. If the arena publishes a drop-off plan for a show, that plan replaces this paragraph.","A group that splits across cars also splits across lots and exits. One vehicle arrives with everyone at once and leaves with everyone at once, which matters most on a night that starts with dinner at Westgate."),O("What’s coming up at Desert Diamond Arena?",`Coming up at Desert Diamond Arena: the Jonas Brothers on ${U(at)}, Rush on December 1 and 3, 2026, Pentatonix on ${U(Kt)}, and the PBR World Finals Championship on ${U(xe)}. The arena’s calendar lists these shows from October 21, 2026, as read on September 24, 2026:`,..._a.map(so),"Los Tigres del Norte moved from September 12 to October 24, and the arena says tickets for the original date are valid for the new one. The Hot Wheels Stunt Show has three performances: noon and 7 p.m. on Saturday, March 6, and 2 p.m. on Sunday, March 7.","The PBR World Finals Championship comes to Glendale after its opening rounds in Fort Worth on May 6 to 9, 2027. Session times are announced closer to the date. New shows are added to the arena’s calendar through the year, and it is the place to check before you book."),O("How many people does Desert Diamond Arena hold?","Desert Diamond Arena’s own 2026 private events guide lists the arena at a capacity of 20,000, with a 24,400 square foot floor. The number sold for a show depends on its stage and seating layout, which the arena’s seat map shows event by event.","For a group, capacity decides the traffic, not the ride: a sold-out night means full lots, lines at the card readers and one long exit. That is the night to leave the driving to a chauffeur and the parking to the lot."),O("What is the Desert Diamond Arena bag policy?","Bags and purses must be 12 by 12 by 6 inches or smaller to enter Desert Diamond Arena, clear or not. Laptop bags, briefcases, camera bags, coolers, luggage of any kind and seat cushions are not allowed at any size.","Outside food, drinks, cans, bottles and flasks are not allowed either; a factory-sealed water bottle under 17 ounces is. Every guest is screened on entry, with Evolv scanners at some entrances.","Settle bags at the hotel. A group that is dropped off has no car in the lot to go back to during the show."),O("Which hotels and restaurants are near Desert Diamond Arena?","The arena’s parking map shows the Renaissance Hotel, the Hampton Inn & Suites, Home2 Suites by Hilton and the Tru Hotel just west of the arena, between 95th Avenue and Loop 101, and the Westgate Entertainment District’s restaurants directly north across Entertainment Boulevard.","Westgate describes itself as specialty shops, eateries and entertainment in the heart of Glendale, at 6770 North Sunrise Boulevard. On the arena’s own map it sits across one street from the arena.","Our Westgate Dinner + Show package is built for that night: pickup, dinner at Westgate, the show and the ride home, in one booking."),O("Which vehicle fits a Desert Diamond Arena group?",`Concert crews ride a Limo Party Sprinter or the ${p(wt)}. A VIP night out takes the ${p(bt)}, the ${p(ie)}, the ${p(zn)} or the ${p(Vn)}. Big groups and fan clubs take the ${p(he)}, the ${p(Le)} or the ${p(vt)}.`,`Seat counts are seated capacities from the fleet: the ${p(ie)} seats ${X(ie)}, the ${p(we)} ${X(we)}, the ${p(fa)} ${X(fa)}, the ${p(wt)} ${X(wt)} and the ${p(bt)} ${X(bt)}. The ${p(he)} seats ${X(he)}, the ${p(Le)} ${X(Le)} and the ${p(vt)} ${X(vt)}.`,`Our pick for an arena night is the ${p(ie)}, ${kt(ie)}: fiber-optic lighting with eighteen modes, lasers and a fog machine, an ultra-premium sound system and a full partition with an intercom to your chauffeur. The ${p(we)} is ${kt(we)}, and the ${p(he)} is ${kt(he)}. Every rate prices the whole vehicle, before tax.`,`For a group bigger than the ${p(Le)}, we plan two or more vehicles and quote them together. Count riders for the ride home as well as the ride there; the late list is the one that matters.`),O("How should a group plan the ride to a Desert Diamond Arena show?","Plan backwards from the doors. At every listed concert the doors open an hour before the show, and the arena lots open an hour before the doors, so a pickup that lands the group at the arena around the doors time leaves room for the lines and the bag check.","Arena guests with the paid Bassline Bar upgrade get in 60 minutes before general doors, between Gates 3 and 4; plan that pickup earlier still. It is an add-on to a ticket, not a ticket.",`Book by the hour and the vehicle is yours for the whole night, dinner at Westgate included, or book a ride there and a ride back. Reach the reservations team at ${F} or ${M} with the show, the date, the pickup area and the rider count.`)],ho=[{question:"Where do you park at Desert Diamond Arena?",answer:"In the arena’s own lots: on the day, lots G, J, L, Yellow, the Garage and VIP, as each event allows. They open one hour before doors, take cards only, and a pre-paid space bought on the event page is held until 30 minutes after the start."},{question:"How much is parking at Desert Diamond Arena?",answer:"The arena’s pages publish no parking price: it is set by event and shown when you pre-pay on the event page through Ticketmaster or ParkWhiz. At the entrance it is credit or debit card only, no cash, and oversized vehicles must buy additional spaces."},{question:"What time do Desert Diamond Arena parking lots open?",answer:"One hour before the event’s doors. At every listed concert the doors open an hour before the show."},{question:"What concerts are coming to Desert Diamond Arena?",answer:`Among the listed shows: the Jonas Brothers on ${U(at)}, Rush on December 1 and 3, 2026, and Pentatonix on ${U(Kt)}, then the PBR World Finals Championship on ${U(xe)}. The arena’s calendar has the full, current list.`},{question:"How many people does Desert Diamond Arena hold?",answer:"The arena’s own 2026 private events guide lists a capacity of 20,000. A show’s capacity depends on its stage and seating layout."},{question:"Where is Desert Diamond Arena?",answer:"At 9400 West Maryland Avenue, Glendale, AZ 85305, in the Westgate Entertainment District off Loop 101, across Maryland Avenue from State Farm Stadium."},{question:"What is the Desert Diamond Arena bag policy?",answer:"Bags up to 12 by 12 by 6 inches, clear or not. No laptop bags, briefcases, camera bags, coolers, luggage or seat cushions at any size."},{question:"When is the PBR World Finals at Desert Diamond Arena?",answer:`The PBR World Finals Championship is ${U(xe)}, after the opening rounds in Fort Worth on May 6 to 9. Session times are announced closer to the date.`},{question:"Can a limo or party bus drop off at Desert Diamond Arena?",answer:"Yes, where arena staff and police direct on the night. The arena publishes no rideshare, limo or charter zone, so the chauffeur confirms the drop-off for your show and agrees one pickup point for the ride home."},{question:"Is there light rail to Desert Diamond Arena?",answer:"No. Valley Metro lists no light rail to the Westgate area; its one listed connection there is bus Route 70."}],lo={path:Hn,title:"Desert Diamond Arena: Parking, Upcoming Shows and Concert Rides",metaTitle:"Desert Diamond Arena Parking & Shows",description:"Desert Diamond Arena in Glendale: how the arena’s parking works, the upcoming concerts and the PBR World Finals, capacity, the bag policy, the hotels and Westgate next door, and a chauffeured ride so nobody drives or parks.",metaDescription:"Lots, doors, the upcoming shows and a chauffeured ride",lastUpdated:pa,lastUpdatedLabel:T(pa),eyebrow:"Glendale · Westgate Entertainment District",intro:`Scottsdale Sprinters’ short answer on Desert Diamond Arena: it is at 9400 West Maryland Avenue in Glendale, in the Westgate Entertainment District beside State Farm Stadium. Arena lots open one hour before doors and take cards only, and a pre-paid space is held until 30 minutes after the start. Coming up: the Jonas Brothers on ${U(at)}, Rush on December 1 and 3, Pentatonix on ${U(Kt)} and the PBR World Finals on ${U(xe)}. For a group, one chauffeured vehicle replaces the lot, the card reader and the drive home.`,sections:io,faqs:ho,links:[{href:"/guides/venues/state-farm-stadium",label:"State Farm Stadium parking, across Maryland Avenue"},{href:"/service-areas/glendale",label:"Glendale service area"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:`/fleet/${ie}`,label:p(ie)},{href:`/fleet/${we}`,label:p(we)},{href:`/fleet/${he}`,label:p(he)},{href:"/pricing",label:"Published hourly pricing"}],sources:no},ma="2026-09-25",co="https://www.inningsfestival.com/",rt="https://help.inningsfestival.com/article",uo=`${rt}/224-what-are-the-dates-hours-of-innings-festival`,po=`${rt}/229-community-information-page`,fo=`${rt}/250-how-do-i-get-home-from-the-festival`,mo=`${rt}/196-what-is-the-bag-policy`,go="https://www.downtowntempe.com/get-around/parking",yo="https://www.valleymetro.org/how-to-ride/destinations/destinations-tempe",At={crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],big:["executive-sprinter-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"]},Tt={oldTown:15,kierland:28},bo=[...At.crews,...At.vip,...At.big].filter(ge),wo=bo.map(e=>({slug:e,name:n[e],capacity:c[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),L="ultra-luxury-party-sprinter-scottsdale",ne="maybach-jet-sprinter-scottsdale",_e="maybach-shuttle-sprinter-8",$t="premium-suv-scottsdale",Me="limo-sprinter-13-scottsdale",vo="limo-sprinter-16-scottsdale",qt="party-bus-28-scottsdale",ga="executive-sprinter-scottsdale",ko="executive-mini-bus-26-scottsdale",So="executive-luxury-bus-29-scottsdale",ya="motorcoach-56",l=e=>n[e],q=e=>c[e];function ba(e){return g(s[e].hourlyRateCents)}function wa(e,t,a){return g(Math.round(s[e].hourlyRateCents*t/a))}function G(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Ao="At 10:30 p.m. the whole crowd leaves at once, the festival asks everyone to head to the nearest exit, and rideshare prices and waits can climb when that many people request a car together.",To=[{label:"Innings Festival official site: dates and venue",href:co},{label:"Innings Festival help center: dates and hours",href:uo},{label:"Innings Festival help center: community information and road closures",href:po},{label:"Innings Festival help center: getting home from the festival",href:fo},{label:"Innings Festival help center: bag policy",href:mo},{label:"Downtown Tempe: parking in Downtown Tempe",href:go},{label:"Valley Metro: Tempe destinations (Tempe Beach Park/Town Lake)",href:yo}],$o=[G("Where do you park for Innings Festival 2027?","Innings Festival has published no festival parking for 2027, so drivers use Downtown Tempe’s paid garages, lots and meters, more than 20,000 public spaces, some posting special event rates during events; with a chauffeured ride nobody in the group drives, parks or walks back to a garage after the 10:30 p.m. close.","The festival’s own help center covers entrances, re-entry, transit and the ride home, but for 2027 it lists no parking lot of its own. Its accessibility page says accessible parking locations, drop-off areas and entry procedures will be available closer to the festival. Until then, parking means the city’s downtown supply, not a festival lot.","Downtown Tempe, where the City of Tempe’s parking link leads, counts more than 20,000 paid public parking spaces across garages, lots and on-street zones, and more than a dozen paid garages and surface lots. During certain events some garages and lots post special event parking; where none is posted, standard rates apply. On-street meters are free on Sundays. Tempe TRiP shows availability in real time.","The catch is not the number of spaces. It is the closures around the park (the next answers), a walk from the garage to the entrance at Mill Avenue and Rio Salado Parkway, and the same walk back after close with everyone else. A chauffeured ride skips all three: the chauffeur drops the group near the entrance, as far as the closures and traffic staff allow, and is booked for the ride home."),G("Where is the Innings Festival rideshare and drop-off area?","The 2027 rideshare zone is not announced yet: the official help center says the 2027 information is not yet available, so no pickup spot is confirmed for February 26 to 28; a chauffeured ride unloads at a legal curb outside the closed streets, where police and event staff direct, and meets the group at a set time.","The festival publishes its rideshare instructions in the “How do I get home from the festival?” article. For 2027 that section reads, in effect, check back shortly. When it is posted, that zone is for rideshare cars. It is not a commercial-vehicle privilege, and no limo, charter or party-bus drop-off zone is published.","So a booked Sprinter, party bus or coach follows the current closures and the directions of Tempe police and event staff. The main entrance is at the northwest corner of Mill Avenue and Rio Salado Parkway; the secondary entrance is on West Rio Salado Parkway at West Lakeside Drive. The chauffeur unloads as close to those as the open streets allow, and the group walks the last stretch.","For the ride home, agree on one meeting point before anyone goes in, away from the exit crush. The festival names the Main Guest Services Tent as the meeting point for anyone separated inside. Outside, the transportation lead confirms where the vehicle is waiting before the group walks toward traffic."),G("When is Innings Festival 2027, and what time do the gates open?","Innings Festival 2027 runs Friday, February 26 through Sunday, February 28, 2027, at Tempe Beach Park & Arts Park; the gates open at 12 p.m. and the festival closes at 10:30 p.m. each of the 3 days, and guests may leave and re-enter as often as they like until 7 p.m.","The dates and daily hours come from the festival’s own help center, updated in September 2026: Friday, February 26, Saturday, February 27 and Sunday, February 28, 2027, opening at noon and closing at 10:30 p.m. each day. The countdown on this page counts to the first gate time, 12 p.m. on Friday, February 26, Arizona time.","The 2027 lineup and set times are not announced yet. The festival’s lineup and schedule pages still show last year’s, and its schedule article says 2027 information will come closer to the festival date. This guide names no artist. Plan the pickup around the gates and the close, then adjust once the schedule is out.","Re-entry is allowed until 7 p.m., local time. Each time, the wristband is scanned and the guest goes back through security. After 7 p.m., leaving means leaving for the night, so a group that wants dinner outside and the late sets inside should plan to be back through the gate before then."),G("Which roads close for Innings Festival, and where is it?","Innings Festival is at Tempe Beach Park & Arts Park, 80 West Rio Salado Parkway, Tempe, AZ 85281; for 2027 the festival lists Mill Avenue southbound closed between Washington Street and 2nd Street on all 3 festival days, starting at 10:30 a.m., and East Rio Salado Parkway closed between Ash Avenue and Mill Avenue.","The festival’s 2027 community page lists these closures. North Mill Avenue southbound, between Washington Street and West 2nd Street, closes on Friday, February 26, Saturday, February 27 and Sunday, February 28, starting at 10:30 a.m. and reopening at 11:59 p.m. East Rio Salado Parkway, between Ash Avenue and South Mill Avenue, closes on the same 3 days, starting at 8 a.m. and reopening at 11:59 p.m.","West Rio Salado Parkway eastbound, between South Hardy Drive and East Rio Salado Parkway, closes from 8 a.m. on Friday, February 26 until 5 a.m. on Monday, March 1. The westbound side of the same stretch closes earlier, from Wednesday, February 24; its reopening time is announced closer to the date. The walking and bike path between Tempe Center for the Arts and Hayden Ferry Lakeside closes from Monday, February 22 to Monday, March 1.","The City of Tempe posts its own event traffic notices closer to each event; its 2027 notice for the festival is not out yet. Your chauffeur plans the approach around the published closures and follows police and event staff on the day. Anyone driving themselves should expect the streets nearest the park to be closed and should not plan to reach the entrance by car."),G("Can you take the light rail or streetcar to Innings Festival?","Yes: Valley Metro’s A line stops at the Mill Ave/3rd St station for Tempe Beach Park, the Tempe streetcar stops at Tempe Beach Park/Rio Salado Parkway, and bus Route 48 stops at Ash Avenue/Rio Salado Parkway; the festival also points to 11 free park-and-rides, with no overnight parking.","The festival’s getting-home article lists Valley Metro rail, the local bus and the streetcar, and 11 free park-and-rides that reach rail stations in Phoenix, Tempe and Mesa. Overnight parking is not allowed at the park-and-rides. Valley Metro fares apply; the festival’s article and valleymetro.org list them.","Transit is a good answer for two or three people who are staying near a station. It is a harder answer for a group of 10 coming from a Scottsdale resort, or for a crew that wants to arrive together and leave together after a 10:30 p.m. close. That is where a chauffeured ride earns its keep."),G("Is a chauffeured ride worth it when Scottsdale is so close?",`The drive is short, about ${Tt.oldTown} minutes from Old Town Scottsdale without event traffic, so the ride is not about distance: it is no parking, no rideshare wait at the 10:30 p.m. close, 1 vehicle that keeps the group together, and a set pickup, with nobody in the group driving.`,`From Old Town Scottsdale to Tempe Beach Park is about ${Tt.oldTown} minutes by Google’s typical time, and about ${Tt.kierland} from Kierland. Nobody needs a chauffeur for the miles. The value is what the evening does to those minutes: closed blocks around the park, a garage to find and pay for, and a walk back to it.`,Ao,"A booked vehicle turns that into a plan. One cabin carries everyone, so nobody is split across 3 rideshares or left to find their own way. The pickup time and place are set before the gates open. Nobody in the group has to drive, so nobody has to stop at one drink or leave early to get the car.","The honest limit: we cannot drive past closed streets or unload in a travel lane, and we cannot make the exit crowd move faster. The chauffeur is waiting where the open streets and traffic staff allow, and the group walks to it. For two people staying next to a station, the light rail may be the simpler choice."),G("What is the Innings Festival bag policy?","The 2027 bag policy allows a clutch or fanny pack up to 6 by 9 inches with no more than one pocket, a clear bag smaller than 12 by 6 by 12 inches, or an emptied hydration pack; every bag is searched, entry is an airport-style screening, and outside food, drinks, coolers and chairs are prohibited.","Hydration packs need not be clear, but they must be emptied of all liquid and have no more than two main compartments and one smaller one. The festival’s advice is to leave the bag at home for the quickest entry. All fans are subject to an airport-style search, which may include a pat-down and magnetometer screening. The policy is marked subject to change.","Prohibited items include outside food or beverage of any kind, alcohol included, coolers, glass, aerosols, chairs of any kind, umbrellas, tents and shade structures, selfie sticks and drones. Empty reusable water bottles, blankets, portable battery packs and non-aerosol sunscreen up to 3.4 ounces are allowed. The park is smoke free, and the festival is 100% cashless.","Anything the gate will not take can stay in the vehicle for the ride home when the vehicle is booked by the hour. Tell the reservations team what the group will carry, so the vehicle fits the bags as well as the people."),G("Which vehicle fits an Innings Festival group?",`Festival crews ride a Limo Party Sprinter or the ${q(qt)}-seat party bus; VIP guests lead with the ${l(ne)}, then the ${l(L)}, our pick for the festival, the ${l(_e)} and the Suburban; big groups and company outings take the ${l(ga)}, the mini bus, the mini coach or the ${q(ya)}-seat motorcoach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Festival crews: the ${l(Me)}, the ${l(vo)} and the ${l(qt)}. VIP guests: the ${l(ne)}, the ${l(L)}, which seats ${q(L)} at ${ba(L)}/hr, the ${l(_e)} and the ${l($t)}. Big groups and company outings: the ${l(ga)}, the ${l(ko)}, the ${l(So)} and the ${l(ya)}.`,`A VIP party larger than the ${l(ne)} rides in two vehicles, one booking each for the same day and times: the ${l(ne)} with the ${l(_e)} seats ${q(ne)+q(_e)}, and with the ${l($t)} it seats ${q(ne)+q($t)}.`,"Count riders for each direction. The group that arrives at the noon gates is not always the group that leaves at 10:30 p.m. Anyone heading elsewhere after the festival comes off the return list before seats are assigned.",`Each booking covers one festival day. For all 3 days, book each day as its own ride; the same vehicle can be requested for each. For a per-person view: 13 riders sharing the ${l(Me)} for 5 billed hours at ${ba(Me)}/hr is about ${wa(Me,5,13)} each before tax; ${q(L)} riders in the ${l(L)} for 6 hours is about ${wa(L,6,q(L))} each. That is arithmetic, not a flat festival fare.`),G("How should the pickup after Innings Festival work?","Use 2 checkpoints after Innings Festival: the group gathers at the meeting point it chose before going in, then the transportation lead confirms where the vehicle is waiting before anyone walks toward traffic, because at the 10:30 p.m. close the streets nearest the park are still closed and the 2027 rideshare zone is not yet announced.","Mill Avenue southbound and East Rio Salado Parkway stay closed until 11:59 p.m. on each festival day, so the vehicle waits on an open street, where police and event staff allow. It cannot stop wherever a map pin lands, and guests should not walk into a roadway to reach it.","If the group splits inside, the festival’s meeting point for separated guests is the Main Guest Services Tent. Anyone leaving early or going on elsewhere tells the transportation lead, so the return list stays right. If the night runs long, your chauffeur waits; extra time is billed hourly at the vehicle’s rate, and you can call or text us to extend.","For a multi-vehicle group, label each vehicle, its lead and its drop-off. A crew heading to Old Town and a VIP group heading to a resort should not rely on spotting a driver in a crowd."),G("How far ahead should Innings Festival transportation be booked?","Availability varies by day and by vehicle, so no fixed lead time applies: request a quote with the rider count, the pickup area and which of the 3 festival days you need, and the reservations team confirms what is open across the vehicles listed, updating the plan as the festival announces its 2027 details.","The first request needs the day or days, the hotel or home, a likely passenger count, the arrival you want against the noon gates, and the return. A group does not need every name to begin. It does need to say which group is riding: a festival crew, VIP guests or a big group or company outing.",`During the final 48 hours, confirm addresses, phone numbers and the festival’s newest instructions, including the 2027 rideshare zone and the city’s traffic notice once they are posted. Reach the reservations team at ${F} or ${M}. A ride booking never includes a festival ticket or wristband.`)],Co=[{question:"When is Innings Festival 2027?",answer:"Friday, February 26 through Sunday, February 28, 2027, at Tempe Beach Park & Arts Park in Tempe. The festival opens at 12 p.m. and closes at 10:30 p.m. each day."},{question:"What time does Innings Festival start?",answer:"The gates open at 12 p.m. (noon) on each festival day, and the festival closes at 10:30 p.m. The 2027 set times are announced closer to the date."},{question:"Where is Innings Festival?",answer:"At Tempe Beach Park & Arts Park, 80 West Rio Salado Parkway, Tempe, AZ 85281. The main entrance is at the northwest corner of Mill Avenue and Rio Salado Parkway; the secondary entrance is on West Rio Salado Parkway at West Lakeside Drive."},{question:"Where do you park for Innings Festival?",answer:"The festival has published no parking lot of its own for 2027. Drivers use Downtown Tempe’s paid garages, lots and meters; some garages post special event parking during events. With a chauffeured ride nobody drives or parks."},{question:"Where is the Innings Festival rideshare pickup?",answer:"The 2027 rideshare zone is not announced yet; the festival’s getting-home article says the information is coming. A chauffeured ride unloads and picks up where police and event staff allow, at a time set in advance."},{question:"Who is playing Innings Festival 2027?",answer:"The 2027 lineup is not announced yet. The festival’s lineup and schedule pages still show last year’s; check the official site for the 2027 announcement."},{question:"Can I leave Innings Festival and come back?",answer:"Yes, as often as you like until 7 p.m. local time. Your wristband is scanned and you go through security each time you re-enter."},{question:"What bags are allowed at Innings Festival?",answer:"A clutch or fanny pack up to 6 by 9 inches with no more than one pocket, a clear bag smaller than 12 by 6 by 12 inches, or a hydration pack emptied of liquid. Every bag is searched."},{question:"Can I take the light rail to Innings Festival?",answer:"Yes. The Valley Metro A line stops at the Mill Ave/3rd St station for Tempe Beach Park, and the Tempe streetcar stops at Tempe Beach Park/Rio Salado Parkway."},{question:"Can we book a ride for all three days?",answer:"Yes, one booking per day. Each festival day is its own ride, so a Friday-to-Sunday group books three rides, one for each day, and can ask for the same vehicle each time."}],Po={path:"/guides/innings-festival-transportation",title:"Innings Festival 2027: parking, rideshare and getting there",metaTitle:"Innings Festival 2027 Parking & Rides",description:"Innings Festival 2027 runs February 26–28 at Tempe Beach Park & Arts Park. The official dates and gate times, the 2027 road closures, parking, rideshare, light rail and the bag policy, and a chauffeured ride from Scottsdale so nobody drives, parks or waits at close.",metaDescription:"Feb 26–28 dates, noon gates, road closures and light rail, or a chauffeured ride",lastUpdated:ma,lastUpdatedLabel:T(ma),eyebrow:"Official dates: February 26–28, 2027",intro:`An Innings Festival ride from Scottsdale Sprinters starts with the festival’s own 2027 facts, a rider count and one transportation lead. Festival crews ride a Limo Party Sprinter or the party bus; VIP guests lead with the ${l(ne)} and the ${l(L)}; big groups and company outings take the executive Sprinter, the mini bus, the mini coach or the motorcoach. This guide uses only published facts, leaves the unannounced ones for closer to the date, and turns each festival day into a written pickup, drop-off and ride home.`,sections:$o,faqs:Co,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:l(L)},{href:"/fleet/limo-sprinter-13-scottsdale",label:l(Me)},{href:"/fleet/party-bus-28-scottsdale",label:l(qt)},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:To,fleetRows:wo},va="2026-09-25",Fo="https://www.m3ffest.com/",Mo="https://www.m3ffest.com/faqs",Eo="https://www.m3ffest.com/lineup-by-day",Do="https://www.m3ffest.com/ticket-types-1-1",Ro="https://www.valleymetro.org/maps-schedules/b",Io="https://www.phoenix.gov/administration/departments/parks/activities-facilities/city-parks/steele-indian-school-park.html",Ct={crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],big:["executive-sprinter-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"]},Pt={oldTown:22,kierland:27},xo=[...Ct.crews,...Ct.vip,...Ct.big].filter(ge),Wo=xo.map(e=>({slug:e,name:n[e],capacity:c[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),_="ultra-luxury-party-sprinter-scottsdale",oe="maybach-jet-sprinter-scottsdale",Ue="maybach-shuttle-sprinter-8",Ft="premium-suv-scottsdale",Be="limo-sprinter-13-scottsdale",Za="limo-sprinter-16-scottsdale",Ht="party-bus-28-scottsdale",ka="executive-sprinter-scottsdale",Go="executive-mini-bus-26-scottsdale",No="executive-luxury-bus-29-scottsdale",Sa="motorcoach-56",d=e=>n[e],H=e=>c[e];function Aa(e){return g(s[e].hourlyRateCents)}function Ta(e,t,a){return g(Math.round(s[e].hourlyRateCents*t/a))}function D(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Lo="When the last set ends, the crowd leaves at once, and rideshare prices and waits can climb when that many people request a car together.",_o=[{label:"M3F official site: M3F 2027 at Steele Indian School Park",href:Fo},{label:"M3F official FAQs: dates, parking, bag policy, re-entry and box office",href:Mo},{label:"M3F official lineup by day: Friday and Saturday, March 5–6",href:Eo},{label:"M3F official passes: general admission, VIP and Club Pass",href:Do},{label:"Valley Metro: B line stops and schedule",href:Ro},{label:"City of Phoenix: Steele Indian School Park",href:Io}],Uo=[D("Where do you park for M3F 2027?","M3F has no official festival parking for 2027: its FAQ tells guests to use Valley Metro, rideshare, or to park at 4041 N Central Ave, the one address it names; with a chauffeured ride nobody in the group drives, parks or walks back to a car after the last set.","The festival’s own FAQ answers the parking question in three lines: there is no official festival parking; use public transport (Valley Metro) or rideshare services; or park at 4041 N Central Ave. It publishes no lot map, no rate, no operator and no capacity for that address, so this guide prints none either.","Steele Indian School Park is a busy city park in central Phoenix, and on a festival day the streets around it fill with people arriving from every direction. The festival’s own advice, to come by light rail or rideshare, says as much. Anyone who drives should plan the parking before leaving home, not on arrival.","A chauffeured ride takes parking off the list. The chauffeur drops the group near the entrance, where police and event staff allow, and is booked for the ride home. Nobody circles for a space, pays for one, or walks back to it at the end of the night, and nobody has to stay sober to drive."),D("Where is the M3F rideshare and drop-off area?","M3F has not posted a 2027 rideshare zone: its FAQ tells guests to use rideshare services but names no pickup spot, and no limo or charter drop-off is published for March 5 and 6; a chauffeured ride unloads where police and event staff direct and meets the group at a time set in advance.","When the festival posts a rideshare zone, that zone is for rideshare cars. It is not a commercial-vehicle privilege, and a booked Sprinter, party bus or coach follows its own instruction on the day: the directions of Phoenix police and event staff, and the closures in place around the park.","The festival does name one entrance: its bike valet is near the entrance at N Central Ave. The chauffeur unloads as close to the entrance as the open streets and traffic staff allow, and the group walks the last stretch.","For the ride home, agree on one meeting point before anyone goes in, away from the exit crush. There is no re-entry, so the group leaves once. Outside, the transportation lead confirms where the vehicle is waiting before the group walks toward traffic."),D("When is M3F 2027, and what time does it start?","M3F 2027 is Friday, March 5 and Saturday, March 6, 2027, at Steele Indian School Park in Phoenix; the gate and set times are not announced yet, and the festival box office opens at 12 p.m. on Friday and 11 a.m. on Saturday, closing at 11 p.m. both days.","Every current official source agrees on the dates: the festival’s 2027 lineup poster (Friday 03/05/27 and Saturday 03/06/27), its lineup-by-day, music and passes pages, and the ticket seller the site links. One FAQ line prints the year as 2026, but its question says 2027 and the weekdays are 2027’s: March 5, 2027 is a Friday. Some search results still show an old page title with March 6 and 7; the festival’s current pages all say March 5 and 6.","The gate times and set times for 2027 are not published. The only times on the festival’s site are the box office’s: open festival weekend at Steele Indian School Park, from 12 p.m. on Friday and from 11 a.m. on Saturday, closing at 11 p.m. each day. Those are the box office’s hours, not the gates’. The countdown on this page counts to Friday, March 5, Arizona time, and says so.","Plan the pickup around the sets you want to see once the festival posts its schedule, then adjust. Your chauffeur works to the time you set, and the reservations team updates the plan when the gate times are announced."),D("Where is M3F, and which entrance do you use?","M3F is at Steele Indian School Park, 300 E Indian School Rd, Phoenix, AZ 85012, the 72-acre park at Central Avenue and Indian School Road; the festival’s FAQ places its bike valet near the entrance at N Central Ave, and it publishes no other entrance for 2027.","The address comes from the festival’s FAQ, and the ticket seller and the City of Phoenix list the same one. The city calls Steele Indian School Park the premiere special event park in central Phoenix.","The festival’s FAQ mentions one entrance, on N Central Ave, near the bike valet. A festival map for 2027 is not posted yet; when it is, check which entrance your pass uses. How each pass enters is the festival’s to describe, not ours.","Children 12 and under get in free with a ticketed adult, and the ticket seller lists the event as all ages, so a family group can ride together. Tell the reservations team if a child seat is needed."),D("Can you take the light rail to M3F?","Yes: the festival’s FAQ points guests to Valley Metro, and the B line runs up Central Avenue past the park, stopping at the Indian School/Central Ave station (stop 10006); the festival also offers bike valet near its N Central Ave entrance, so a pair staying near a station can skip the car.","The festival’s parking answer names Valley Metro first. Valley Metro’s B line schedule lists the Indian School/Central Ave station, stop number 10006, on its route along Central Avenue. Valley Metro fares apply; its site lists them and the service hours.","Transit is a good answer for two or three people who are staying near a station. It is a harder answer for a group of 10 coming from a Scottsdale resort, or for a crew that wants to arrive together and leave together after the last set. That is where a chauffeured ride earns its keep."),D("Is a chauffeured ride worth it from Scottsdale?",`The drive is about ${Pt.oldTown} minutes from Old Town Scottsdale without event traffic, so the ride is not about distance: it is no festival parking to find, no rideshare wait after the last set, 1 vehicle that keeps the group together, and a set pickup, with nobody in the group driving.`,`From Old Town Scottsdale to Steele Indian School Park is about ${Pt.oldTown} minutes by Google’s typical time, and about ${Pt.kierland} from Kierland. Nobody needs a chauffeur for the miles. The value is what a festival day does to them: no festival lot, streets full of people, and the same crowd leaving together at the end.`,Lo,"A booked vehicle turns that into a plan. One cabin carries everyone, so nobody is split across 3 rideshares or left to find their own way. The pickup time and place are set before anyone goes in. Nobody in the group has to drive, so nobody has to stop at one drink or leave early to fetch the car.","The honest limit: we cannot drive past closed streets or unload in a travel lane, and we cannot make the exit crowd move faster. The chauffeur is waiting where the open streets and traffic staff allow, and the group walks to it. For two people staying next to a station, the light rail may be the simpler choice."),D("What is the M3F bag policy?","The M3F bag policy allows clear plastic, vinyl or PVC bags up to 12 by 12 by 8 inches, fanny packs and wallets up to 5 by 7 inches that need not be clear, and empty single-pocket hydration packs; outside food and drink are not allowed, except empty water bottles.","Clear backpacks and handbags within 12 by 12 by 8 inches are allowed, as are small clutches, non-professional cameras, phones and GoPros, prescribed medication with a matching ID, sunglasses, hats, earplugs, sunscreen and bug spray. Water stations run throughout the festival, so bring the empty bottle.","Not allowed: totems, wagons, folding chairs and large backpacks; professional cameras and audio recording devices; outside food and drink; weapons and drugs; glass containers, lighters, drones and selfie sticks. The festival is fully cashless: every vendor takes credit and debit cards.","Anything the gate will not take can stay in the vehicle when it is booked by the hour. With no re-entry, though, it stays there until you leave for the night, so pack for the whole day before you go in."),D("Is there re-entry at M3F?","No: the M3F FAQ says there is no re-entry allowed, so each guest goes in once and leaves once on each of the 2 festival days; plan the arrival time, what to carry and the pickup before the group reaches the gate, because stepping out to the vehicle ends that guest’s day.","No re-entry changes how a day is planned. A group that wants dinner out before the late sets should eat before going in, or plan to leave for the night after dinner. Nobody runs back to the car for a jacket or a charger: what is not in the bag stays outside.","It also sets the shape of the booking. A vehicle booked by the hour waits for the whole group at the end; a group that splits, with some leaving early, can book a second pickup for the early leavers or keep one vehicle and one time for everyone. Tell the reservations team which you want."),D("Which vehicle fits an M3F group?",`Festival crews ride a Limo Party Sprinter or the ${H(Ht)}-seat party bus; VIP guests lead with the ${d(oe)}, then the ${d(_)}, our pick for M3F, the ${d(Ue)} and the Suburban; big groups and company outings take the ${d(ka)}, the mini bus, the mini coach or the ${H(Sa)}-seat motorcoach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Festival crews: the ${d(Be)}, the ${d(Za)} and the ${d(Ht)}. VIP guests: the ${d(oe)}, the ${d(_)}, which seats ${H(_)} at ${Aa(_)}/hr, the ${d(Ue)} and the ${d(Ft)}. Big groups and company outings: the ${d(ka)}, the ${d(Go)}, the ${d(No)} and the ${d(Sa)}.`,`A VIP party larger than the ${d(oe)} rides in two vehicles, one booking each for the same day and times: the ${d(oe)} with the ${d(Ue)} seats ${H(oe)+H(Ue)}, and with the ${d(Ft)} it seats ${H(oe)+H(Ft)}.`,"Count riders for each direction. The group that arrives for the early sets is not always the group that leaves after the last one. Anyone heading elsewhere after the festival comes off the return list before seats are assigned.",`Each booking covers one festival day. For both days, book each day as its own ride; the same vehicle can be requested for each. For a per-person view: 13 riders sharing the ${d(Be)} for 5 billed hours at ${Aa(Be)}/hr is about ${Ta(Be,5,13)} each before tax; ${H(_)} riders in the ${d(_)} for 6 hours is about ${Ta(_,6,H(_))} each. That is arithmetic, not a flat festival fare.`),D("How should the pickup after M3F work?","Use 2 checkpoints after M3F: the group gathers at the meeting point it chose before going in, then the transportation lead confirms where the vehicle is waiting before anyone walks toward traffic, because the 2027 rideshare zone and any charter pickup area are not yet announced.","The vehicle waits on an open street, where police and event staff allow. It cannot stop wherever a map pin lands, and guests should not walk into a roadway to reach it. Central Avenue carries both traffic and the light rail, so the exact spot is set on the day.","If the group splits inside, pick a landmark to regroup at before the last set, and charge phones before going in. Anyone leaving early or going on elsewhere tells the transportation lead, so the return list stays right. If the night runs long, your chauffeur waits; extra time is billed hourly at the vehicle’s rate, and you can call or text us to extend.","For a multi-vehicle group, label each vehicle, its lead and its drop-off. A crew heading to Old Town and a VIP group heading to a resort should not rely on spotting a driver in a crowd."),D("How far ahead should M3F transportation be booked?","Availability varies by day and by vehicle, so no fixed lead time applies: request a quote with the rider count, the pickup area and which of the 2 festival days you need, and the reservations team confirms what is open across the vehicles listed, updating the plan as the festival announces its 2027 details.","The first request needs the day or days, the hotel or home, a likely passenger count, the arrival you want, and the return. A group does not need every name to begin. It does need to say which group is riding: a festival crew, VIP guests or a big group or company outing.",`During the final 48 hours, confirm addresses, phone numbers and the festival’s newest instructions, including the gate times and any rideshare zone once they are posted. Reach the reservations team at ${F} or ${M}. A ride booking never includes a festival ticket or pass: those are sold by the festival, final sale.`)],Bo=[{question:"When is M3F 2027?",answer:"Friday, March 5 and Saturday, March 6, 2027, at Steele Indian School Park in Phoenix. The festival’s poster, lineup, passes and ticket pages all give those two days."},{question:"What time does M3F start?",answer:"The 2027 gate and set times are not announced yet. The festival box office opens at 12 p.m. on Friday and 11 a.m. on Saturday; those are its hours, not the gates’."},{question:"What is M3F?",answer:"M3F Music Festival is a two-day music and art festival at Steele Indian School Park in central Phoenix, with multiple stages and art installations. It also runs The Community Project, year-round programs for art, music and community."},{question:"Where is M3F?",answer:"At Steele Indian School Park, 300 E Indian School Rd, Phoenix, AZ 85012. The festival’s bike valet is near its entrance on N Central Ave."},{question:"Where do you park for M3F?",answer:"M3F has no official festival parking. Its FAQ says to use Valley Metro or rideshare, or to park at 4041 N Central Ave. With a chauffeured ride nobody drives or parks."},{question:"Is there a rideshare drop-off at M3F?",answer:"The festival tells guests to use rideshare services but has not posted a 2027 pickup zone. A chauffeured ride unloads and picks up where police and event staff allow, at a time set in advance."},{question:"Who is playing M3F 2027?",answer:"The 2027 lineup is on the festival’s own site, split into Friday and Saturday on its lineup-by-day page. Set times are not announced yet. This guide does not repeat the lineup."},{question:"What bags are allowed at M3F?",answer:"Clear plastic, vinyl or PVC bags up to 12 by 12 by 8 inches; fanny packs and wallets up to 5 by 7 inches, which need not be clear; and empty single-pocket hydration packs."},{question:"Can I leave M3F and come back?",answer:"No. The festival’s FAQ says there is no re-entry, so plan to go in once and leave once each day."},{question:"Can kids go to M3F?",answer:"Yes. Children 12 and under get in free with a ticketed adult, and the ticket seller lists the festival as all ages."},{question:"Can we book a ride for both days?",answer:"Yes, one booking per day. Each festival day is its own ride, so a Friday-and-Saturday group books two rides, one for each day, and can ask for the same vehicle each time."}],Oo={path:"/guides/m3f-festival-transportation",title:"M3F Festival 2027: parking, rideshare and getting there",metaTitle:"M3F Festival 2027 Parking & Rides",description:"M3F 2027 is Friday and Saturday, March 5–6, at Steele Indian School Park in Phoenix. The official dates, parking, rideshare, light rail, the bag policy and re-entry, and a chauffeured ride from Scottsdale so nobody drives, parks or chases a rideshare at the end.",metaDescription:"March 5–6 dates, no festival parking, light rail and bag rules, or a chauffeured ride",lastUpdated:va,lastUpdatedLabel:T(va),eyebrow:"Official dates: March 5–6, 2027",intro:`An M3F ride from Scottsdale Sprinters starts with the festival’s own 2027 facts, a rider count and one transportation lead. Festival crews ride a Limo Party Sprinter or the party bus; VIP guests lead with the ${d(oe)} and the ${d(_)}; big groups and company outings take the executive Sprinter, the mini bus, the mini coach or the motorcoach. This guide uses only published facts, leaves the unannounced ones for closer to the date, and turns each festival day into a written pickup, drop-off and ride home.`,sections:Uo,faqs:Bo,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:d(_)},{href:"/fleet/limo-sprinter-16-scottsdale",label:d(Za)},{href:"/fleet/party-bus-28-scottsdale",label:d(Ht)},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/service-areas/phoenix",label:"Phoenix service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:_o,fleetRows:Wo},$a="2026-09-25",qo="/guides/nba-all-star-weekend-2027",Mt={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],fans:["executive-sprinter-scottsdale","limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],corporate:["executive-luxury-bus-29-scottsdale","executive-white-sprinter-scottsdale","executive-mini-bus-26-scottsdale","motorcoach-56"]},Ho=[...Mt.vip,...Mt.fans,...Mt.corporate].filter(ge),Qa=Ho.map(e=>({slug:e,name:n[e],capacity:c[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),w="maybach-jet-sprinter-scottsdale",Ca="ultra-luxury-party-sprinter-scottsdale",Oe="maybach-shuttle-sprinter-8",qe="premium-suv-scottsdale",te="executive-sprinter-scottsdale",zo="executive-luxury-bus-29-scottsdale",Vo="motorcoach-56",m=e=>n[e],R=e=>c[e],Et=e=>g(s[e].hourlyRateCents);function Pa(e,t,a){return g(Math.round(s[e].hourlyRateCents*t/a))}const Jo=Math.max(...Qa.map(e=>e.capacity)),Xa="Your chauffeur waits; extra time is billed hourly at the vehicle’s rate — just call or text us to extend.",jo="https://www.nba.com/news/phoenix-suns-nba-all-star-2027-official-release",Yo="https://pr.nba.com/phoenix-to-host-nba-all-star-2027/",Ko="https://www.phoenix.gov/major-events.html",Zo="https://mortgagematchupcenter.com/plan-your-visit/transportation-parking/",Qo="https://mortgagematchupcenter.com/venue/accessibility-ada-information/",Xo="https://mortgagematchupcenter.com/",es="https://mortgagematchupcenter.com/news/phoenix-suns-and-phoenix-mercury-announce-landmark-naming-rights-partnership-with-mortgage-matchup/",ts=[{label:"NBA: Phoenix Suns to host NBA All-Star 2027 (official release)",href:jo},{label:"NBA Communications: Phoenix to host NBA All-Star 2027",href:Yo},{label:"City of Phoenix: major events, NBA All-Star 2027",href:Ko},{label:"Mortgage Matchup Center: transportation and parking",href:Zo},{label:"Mortgage Matchup Center: accessibility, drop-off and pickup",href:Qo},{label:"Mortgage Matchup Center: bag policy and parking",href:Xo},{label:"Mortgage Matchup Center: the arena’s new name",href:es}];function ee(e,t,...a){return{question:e,answer:t,paragraphs:a}}const as=[ee("When is NBA All-Star weekend 2027, and where is it?","NBA All-Star 2027 is in Phoenix from Friday, February 19 to Sunday, February 21, 2027. The 76th NBA All-Star Game is on Sunday, February 21, at Mortgage Matchup Center, home of the Phoenix Suns, at 201 East Jefferson Street in downtown Phoenix. Tip-off times are announced by the NBA closer to the date.","The NBA announced Phoenix as the host on March 7, 2024. Its release names the arena Footprint Center; it is the same building, renamed Mortgage Matchup Center by the Suns and the Mercury on October 2, 2025. Use that name when you book and when you give the address: 201 East Jefferson Street, Phoenix, AZ 85004, on the southeast corner of 1st Street and Jefferson.","As announced in March 2024, the on-court events start on Friday, February 19, with a showcase of top rookies and second-year players, then a Saturday night of contests on February 20, and the All-Star Game itself on Sunday, February 21. The NBA also plans a practice, a celebrity game and a fan fest at venues around Phoenix. Where and when each of those takes place is announced by the NBA closer to the date.","So this page prints no tip-off time, no Saturday venue and no fan-fest address. When the NBA publishes the 2027 schedule, the reservations team plans each pickup from it, not from a previous year’s weekend. Until then a quote can still hold the days, the hotel, the group size and the vehicle."),ee("Where do you park for the NBA All-Star Game, and where is drop-off?","For a game or event, Mortgage Matchup Center publishes 3rd Street, just south of Jefferson, at the green curb as its drop-off and pickup, and garages within walking distance bought ahead through ParkWhiz. The 2027 All-Star parking and traffic plan is announced closer to the date. With a chauffeured ride nobody drives or parks.","The arena’s own event-night plan, which is the one published now: several garages and lots within walking distance, with guests encouraged to buy parking in advance through ParkWhiz. Event parking is generally available from about 30 minutes before doors open, parking does not include in-and-out privileges, and availability, pricing and access may vary by event. The arena lists more than 700 on-site spaces and publishes no price.","Valet is available only for select ticketed guests and membership-based areas; it is not open to the general public. Vehicles cannot be parked or left unattended in the drop-off zones, so the curb on 3rd Street is a place to unload, not to wait. Drop-off for will call and the ticket office is on 1st Street, just north of Madison.","An All-Star weekend can bring its own street closures and a security perimeter around the arena. None is published for 2027, so this page does not guess one. Your chauffeur unloads at the arena’s published curb or where event and police staff direct, and the reservations team passes on any 2027 instruction the NBA or the city publishes."),ee("Where do rideshares drop off and pick up at Mortgage Matchup Center?","The arena lists 4 Lyft drop-off points: 1st Street at Jefferson by the arena plaza, South 2nd Street, South 3rd Street at the Phoenix Convention Center, and East Jefferson Street. Rideshare pickup is at South 3rd Street and East Jefferson Street, by the Phoenix Convention Center. A booked chauffeur uses the 3rd Street curb or where staff direct.","After a game every rideshare in downtown Phoenix is heading for the same corner. A chauffeured vehicle is booked before the weekend, so the group is not waiting on surge pricing or a car that cannot reach the pin. Name one meeting point before going in, and one person who counts heads before anyone walks to the curb.","Light rail is the other published option: the arena says light rail fare is included in a ticket to any game or event there, bus fare excepted. Stations and bus stops are on accessible routes. That helps a guest who is staying downtown; a group coming from a Scottsdale resort usually wants the door-to-door ride."),ee("Which vehicle fits an All-Star VIP, fan or corporate group?",`VIP and courtside guests lead with the ${m(w)}, which seats ${R(w)}, then the ${m(Ca)}, the ${m(Oe)} and the ${m(qe)}; friends and fan crews ride the ${m(te)} or a Limo Party Sprinter; corporate hosts take the mini coach, the white Sprinter, the mini bus or the full-size coach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in the page’s three groups. VIP and courtside guests: the ${m(w)}, our pick for All-Star weekend, seats ${R(w)} at ${Et(w)}/hr in a private jet cabin with Maybach massage recliners, a wet bar and a full partition, then the ${m(Ca)}, the ${m(Oe)} and the ${m(qe)}.`,`A VIP party larger than the ${m(w)} rides in two vehicles, one booking each for the same times: the ${m(w)} with the ${m(Oe)} seats ${R(w)+R(Oe)}, and with the ${m(qe)} it seats ${R(w)+R(qe)}. Friends and fan crews: the ${m(te)} and the two Limo Party Sprinters. Corporate hospitality: the ${m(zo)}, the Executive White Sprinter, the Mini Bus and the ${m(Vo)}, the largest in the table at ${Jo} seats.`,"Count riders for each direction. The ride to the game and the ride home are often different lists, and a guest who leaves with another host should come off the return manifest before seats are assigned. Arrive without bags where you can: the arena encourages it, allows small clutches and crossbody bags, and does not allow standard backpacks inside."),ee("How does pickup after the All-Star Game work downtown?","Plan 2 steps: the group gathers at one meeting point the chauffeur and the transportation lead agreed before tip-off, then walks to the vehicle together once the lead confirms where it is. No vehicle may wait in the arena’s drop-off zone, so the chauffeur clears the curb after drop-off and comes back for the group.",`What if the game runs late? ${Xa}`,"Book by the hour and the vehicle is yours for the whole block: the dinner before, the arena, the after-party and the ride back to the hotel. A ride there and a ride back is the other shape; it suits a group that knows it will leave with the crowd. Either way the chauffeur follows event and police staff on the day.","For more than one return wave, label each vehicle, its lead and its hotel. A VIP group heading to a resort and a client group heading to another hotel should not rely on spotting a driver in a crowd. The final sweep checks the manifest before the vehicle rolls."),ee("Can one booking cover the whole All-Star weekend?","Each day is its own booking by the hour, and one request can hold all 3 days, February 19 to 21: the reservations team quotes each day’s vehicle and hours together. Friday and Saturday times are announced by the NBA closer to the date, so those blocks stay flexible until the schedule is out.","A weekend plan often starts at the airport: a VIP guest landing at Phoenix Sky Harbor can be met there and driven to the hotel, and the rest of the weekend fills in around the game, with dinners, a hotel party and the fan events once the NBA names their venues.","Write one line per day: the pickup address and ready time, the destination, the return rule, and the name of the person who owns the headcount. Leave the unannounced lines open rather than copying last year’s weekend, and let the reservations team fill them in when the NBA publishes the 2027 schedule."),ee("How far ahead should All-Star weekend transportation be booked?",`No fixed lead time applies: availability for February 19 to 21 varies by vehicle, and the ${R(w)}-seat ${m(w)} is a single unit. Request a quote with the days, the hotel, the rider count and the group, and the reservations team confirms what is open and holds it in writing.`,"The first request needs the days, the lodging or pickup area, the likely passenger count and which group is riding: VIP and courtside guests, a fan crew or a corporate hospitality list. A group does not need every name to begin, but it should separate committed riders from possible ones.",`In the final 48 hours, verify addresses, contact numbers and the newest NBA and arena directions, and send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${F} or ${M}.`),ee("How is All-Star transportation priced per person?",`For ${R(w)} guests sharing the ${m(w)} across 5 billed hours, its published ${Et(w)}-per-hour rate works out to about ${Pa(w,5,R(w))} per person before tax for the whole shared ride; the price changes with the vehicle, the hours, the add-ons and the confirmed plan.`,`The same arithmetic for a fan crew of ${R(te)} in the ${m(te)} at ${Et(te)}/hr for 5 hours is about ${Pa(te,5,R(te))} each. It is hourly rate times billed hours, divided by riders, not a flat game-night fare. If fewer people ride, divide across fewer.`,"Every vehicle has a minimum number of hours, shown in the table. The ready-made packages on this page add extras from the published add-on list, and each one is priced by the same engine as the vehicle, so the number on the tile is the number at checkout, before tax.")],rs=[{question:"When is NBA All-Star weekend 2027?",answer:"Friday, February 19 to Sunday, February 21, 2027, in Phoenix. The NBA All-Star Game is on Sunday, February 21. The full weekend schedule and tip-off times are announced by the NBA closer to the date."},{question:"Where is the 2027 NBA All-Star Game?",answer:"At Mortgage Matchup Center, home of the Phoenix Suns, 201 East Jefferson Street, Phoenix, AZ 85004. The NBA’s 2024 announcement calls it Footprint Center; the arena was renamed in October 2025."},{question:"What time does NBA All-Star 2027 start?",answer:"Not yet announced. The NBA publishes tip-off times for the Friday, Saturday and Sunday events closer to the date. Book the day now and the reservations team sets the pickup time once the schedule is out."},{question:"Where do you park for the All-Star Game at Mortgage Matchup Center?",answer:"On a normal event night, in the garages and lots within walking distance, bought ahead through ParkWhiz, with no in-and-out. Valet is not open to the general public. The All-Star weekend parking plan is announced closer to the date."},{question:"Where is drop-off at Mortgage Matchup Center?",answer:"On 3rd Street, just south of Jefferson, at the green curb, for games and events. Vehicles cannot wait there, so a chauffeur unloads, clears the curb and comes back for the group at the time you set."},{question:"Is Mortgage Matchup Center the same as Footprint Center?",answer:"Yes. The Suns and the Mercury renamed Footprint Center as Mortgage Matchup Center on October 2, 2025. It is the same arena at 201 East Jefferson Street in downtown Phoenix."},{question:"What if the game runs late?",answer:Xa},{question:"Does a ride booking include All-Star tickets?",answer:"No. Buy tickets only through the NBA’s official channels; a ride booking does not include tickets, credentials or hospitality. Scottsdale Sprinters is not affiliated with the NBA, the Phoenix Suns or Mortgage Matchup Center."}],ns={path:qo,title:"NBA All-Star 2027 in Phoenix: the weekend, the arena and getting there",metaTitle:"NBA All-Star 2027 Weekend in Phoenix",description:"NBA All-Star 2027 is in Phoenix, February 19–21, with the All-Star Game on Sunday, February 21, at Mortgage Matchup Center. The official dates, what is announced and what is not, the arena’s parking, drop-off and rideshare points, and a chauffeured ride so nobody drives or parks.",metaDescription:"Feb 19–21 in Phoenix, the game at Mortgage Matchup Center, parking, drop-off, and a chauffeured ride",lastUpdated:$a,lastUpdatedLabel:T($a),eyebrow:"Official dates: February 19–21, 2027",intro:`An All-Star ride from Scottsdale Sprinters starts with the NBA’s own announcement, a realistic rider count and one transportation lead. VIP and courtside guests lead with the ${m(w)}; friends and fan crews ride the ${m(te)} or a Limo Party Sprinter; corporate hosts take the mini coach, the mini bus or the full-size coach. This guide uses only published NBA and arena facts, leaves the unannounced schedule for closer to the date, and turns each day of the weekend into a written pickup, arrival and return plan. Scottsdale Sprinters is not affiliated with the NBA, the Phoenix Suns or Mortgage Matchup Center.`,sections:as,faqs:rs,links:[{href:"/fleet/maybach-jet-sprinter-scottsdale",label:n[w]},{href:"/guides/venues/footprint-center",label:"Mortgage Matchup Center group arrival guide"},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/experiences/corporate-event",label:"Corporate event transportation planning"},{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:ts,fleetRows:Qa},Fa="2026-09-25",os="/guides/scottsdale-limo-service",Dt={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],nights:["pink-hummer-limo","limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],weddings:["chrysler-limo-10","executive-white-sprinter-scottsdale","executive-sprinter-scottsdale"]},ae="maybach-jet-sprinter-scottsdale",C="ultra-luxury-party-sprinter-scottsdale",ze="maybach-shuttle-sprinter-8",ye="premium-suv-scottsdale",S="pink-hummer-limo",ue="limo-sprinter-13-scottsdale",pe="limo-sprinter-16-scottsdale",k="chrysler-limo-10",Ve="executive-white-sprinter-scottsdale",ss="executive-sprinter-scottsdale",is=[...Dt.vip,...Dt.nights,...Dt.weddings].filter(ge),nt=is.map(e=>({slug:e,name:n[e],capacity:c[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),r=e=>n[e],b=e=>c[e],Ma=e=>g(s[e].hourlyRateCents);function Rt(e,t){const{hourlyRateCents:a,minimumHours:o}=s[e];return g(a*gr(t,o))}const er=nt.map(e=>e.hourlyRateCents),tr=g(Math.min(...er)),ar=g(Math.max(...er)),Ea=[...new Set(nt.map(e=>e.minimumHours))],rr=Ea.length===1?`a ${Ea[0]}-hour minimum on every limo here`:"the minimum hours shown for each limo",hs=Math.max(...nt.map(e=>e.capacity)),ls=`${fr.toFixed(1)}-star Google rating across ${mr.toLocaleString("en-US")} reviews`;function z(e,t,...a){return{question:e,answer:t,paragraphs:a}}const ds="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",cs=[{label:"City of Scottsdale, Transportation Safety Zone (Old Town)",href:ds}],us=[z("How much does a limo cost in Scottsdale?",`A Scottsdale limo from Scottsdale Sprinters is priced by the hour, from ${tr} to ${ar} an hour across the limos on this page, with ${rr}: the vehicle’s published hourly rate times your billable hours, plus ${Ua}% Arizona sales tax at checkout, with no per-mile charge, no service fee and no booking fee.`,`Four hours in the ${r(k)} comes to ${Rt(k,4)} before tax. Five hours in the ${r(S)} comes to ${Rt(S,5)}. Every card on this page prints its vehicle’s own rate from the same grid, so the number you see is the number checkout uses.`,`Longer bookings earn free hours that come off automatically: book 7 to 11 hours and one hour is free, 12 to 14 hours and two are free, 15 hours or more and three are free. A seven-hour night in the ${r(C)} bills six hours, ${Rt(C,7)} before tax.`,"A one-way ride is priced as a trip instead of by the hour, with no hourly minimum. Gratuity is optional and never added automatically."),z("Which Scottsdale limo fits your group?",`Pick by who is riding: VIP and ultra-luxury parties lead with the ${r(ae)}, then the ${r(C)}, the ${r(ze)} and the ${r(ye)}; nights out and bachelorettes ride the ${r(S)} or a Limo Party Sprinter; weddings, proms and executive groups take the ${r(k)} or an Executive Sprinter.`,`Seats, from the fleet grid: the ${r(S)} seats ${b(S)}, the ${r(pe)} ${b(pe)}, the ${r(C)} ${b(C)}, the ${r(ue)} ${b(ue)}, the ${r(Ve)} and the ${r(ss)} ${b(Ve)} each, the ${r(ae)} ${b(ae)}, the ${r(k)} and the ${r(ze)} ${b(k)} each, and the ${r(ye)} ${b(ye)}.`,`The table lists each limo with its seats, hourly rate and minimum. The largest limo here seats ${hs}. For a bigger group we plan two or more vehicles and quote them together; a VIP party larger than the ${r(ae)} can ride it with the ${r(ze)} or the ${r(ye)}, one booking each.`,"If your group is on the edge of a vehicle’s seats, tell us and we confirm the fit in writing before payment."),z("What is the Pink Hummer Limo?",`The ${r(S)} is our one-of-one pink stretch Hummer, the bachelorette mobile: ${b(S)} guests on handmade custom leather seats behind privacy-tinted windows, with a lit wet bar, a champagne bar, star lighting and a custom sound system, at ${Ma(S)} an hour.`,"It is our most popular ride for women: bachelorettes first, then girls’ birthdays, prom and any night out that celebrates the women in it. Ambient lighting runs outside as well as in, and a partition separates the cabin from the chauffeur.","There is one Pink Hummer, so it books by the date. If a pink party bus is what you searched for, the pink party bus guide explains why the pink ride here is a stretch Hummer limousine rather than a bus."),z("Do you have a classic stretch limo?",`Yes: the ${r(k)} is our classic stretch limousine, black outside with ambient lighting and privacy tint, up to ${b(k)} guests on classic leather seats, with a wet bar, a custom sound system and seventeen colour settings for the cabin lights, at ${Ma(k)} an hour.`,"It is the one for prom, anniversaries, date nights, concerts and the wedding exit: the long silhouette everybody turns to look at. A stretch limo is a sedan lengthened for a lounge cabin; the Pink Hummer is the same idea built on a Hummer, which is why it seats a bigger group."),z("What is a Limo Party Sprinter?",`A Limo Party Sprinter puts limo-style seating, a wet bar and party lighting in a Mercedes Sprinter: the ${r(ue)} seats ${b(ue)} under fiber-optic roof lights, the ${r(pe)} is our largest Sprinter with a star-roof ceiling for ${b(pe)}, and the ${r(C)} is the top of the line.`,`The ${r(C)} adds fiber-optic lighting with eighteen modes, laser lights, a fog machine, automatic doors and an intercom to your chauffeur, for up to ${b(C)}. It is also ultra-luxury, so it rides with the VIP group on this page.`,"The Limo Party Sprinters ride with the nights-out group, never with a corporate or family booking. For executive groups and weddings that want the room without the party lighting, the Executive Sprinters carry reclining leather seats and space for bags."),z("Where do Scottsdale limos pick up?","Anywhere in Scottsdale and the greater Phoenix area: your hotel, home, restaurant or venue, with every stop on an hourly booking included; in Old Town’s entertainment district, from 5 p.m. to 4 a.m. every night, hired vehicles load and unload only in the marked Passenger Convenience Areas.",`Old Town Scottsdale is where nights out start: dinner, the bars and the clubs, in the ${r(S)} or a Limo Party Sprinter. The City’s Transportation Safety Zone covers the entertainment district every night from 5 p.m. to 4 a.m.: through lanes stay clear, and hired vehicles stop only to load or unload at the marked Passenger Convenience Areas, so your chauffeur meets the group where the City allows a limo to load.`,`North Scottsdale books weddings at the resorts and desert venues along the 101, and dinners around Kierland and Scottsdale Quarter; the ${r(k)} and the ${r(Ve)} are the wedding picks. Central Scottsdale, Gainey Ranch and McCormick Ranch book anniversary dinners and small-group evenings in the ${r(ye)} or the ${r(ae)}. Paradise Valley estate events stage the vehicle at the property.`,"Stops on an hourly booking are complimentary, because you have already bought the time. On a one-way ride or a round trip, an added stop carries a fee shown on the quote."),z("Do you offer limo service in Phoenix?","Yes: we run chauffeured limos throughout Phoenix and the Valley, from the Biltmore to downtown Phoenix, Tempe, Mesa, Chandler, Gilbert and Glendale, with the same vehicles, rates and chauffeurs as in Scottsdale.","The drive is part of the hours you book, and your chauffeur plans the route around the Valley’s freeway traffic, so a Phoenix dinner and a Scottsdale nightcap can share one booking. On summer evenings the cabin is cooled before the group boards.","For a Phoenix wedding, a Tempe or ASU celebration, or a concert downtown, pick the group above and the limos that fit it appear with their rates."),z("Can you pick us up at Phoenix Sky Harbor in a limo?",`Yes. ${Ba} We also pick up at Scottsdale Airport and Phoenix-Mesa Gateway, and your chauffeur tracks your flight.`,"Airport rides are priced as a one-way trip with no hourly minimum. The airport transportation page has the full detail, from greeters to luggage."),z("Can you drink in a limo in Arizona?","Passengers 21 and over may bring their own alcohol, and we do not sell it; if anyone under 21 rides, no alcohol comes on that trip, which makes every prom ride alcohol-free, and there is no smoking, vaping or food inside any vehicle.","Arizona’s vehicle-for-hire open-container policy, A.R.S. § 4-251, is what allows adults to drink on board; the alcohol-laws guide covers the law itself. Anyone under 21 stays on soft drinks, and the chauffeur never drinks.","Prom rides follow a written zero-alcohol passenger policy, and a guardian contact can get pickup and drop-off updates; the prom night page has the full plan, from the photo stop to the ride home.")],ps=[{question:"How much does it cost to rent a limo in Scottsdale?",answer:`A limo is priced by the hour: the vehicle’s published hourly rate times your billable hours, from ${tr} to ${ar} an hour across the limos on this page. There is no per-mile charge, no service fee and no booking fee. Arizona sales tax of ${Ua}% is added at checkout, and gratuity is optional. Pick the limo above and the price is on the page.`},{question:"How much is a limo for 2 hours, 4 hours or a whole night?",answer:`An hourly booking has ${rr}, so a two-hour ride books the minimum; a one-way ride is priced as a trip instead, with no hourly minimum. Bookings of 7 hours or more earn free hours that come off automatically, so a seven-hour night bills six.`},{question:"How many people fit in a limo?",answer:`It depends on the limo: the ${r(S)} seats ${b(S)}, the ${r(pe)} seats ${b(pe)}, the ${r(C)} seats ${b(C)}, the ${r(ue)} seats ${b(ue)} and the ${r(k)} seats ${b(k)}. If your group is on the edge, tell us and we confirm the fit in writing.`},{question:"Can you drink in a limo?",answer:"If everyone drinking is 21 or over, yes: bring your own, because we do not sell alcohol. Nobody under 21 drinks, and if anyone under 21 rides, no alcohol comes on that trip. There is no smoking, vaping or food inside the vehicle."},{question:"How much do you tip a limo driver?",answer:"Gratuity is optional, is never added automatically, and goes 100% to your chauffeur. Add it at checkout or hand it over in person."},{question:"Can we book a limo for prom?",answer:`Yes. Prom rides follow a written zero-alcohol passenger policy, and a guardian contact can get pickup and drop-off updates. The ${r(k)} is the classic prom stretch; the ${r(Ve)} carries a bigger group.`},{question:"What is the difference between a limo, a stretch limo and a limo Sprinter?",answer:`The ${r(k)} is the classic stretch: the long black silhouette, up to ${b(k)} guests. The ${r(S)} is a stretch Hummer that seats a bigger group. Our Limo Party Sprinters put limo-style seating, a wet bar and party lighting in a Mercedes Sprinter.`},{question:"Is Scottsdale Sprinters a reputable limo company?",answer:`Every chauffeur is background and MVR checked, drug screened and trained, and the company is licensed and insured with commercial coverage on every vehicle. Guests give us a ${ls}.`},{question:"Do you pick up at Phoenix Sky Harbor?",answer:`Yes: Phoenix Sky Harbor (PHX), Scottsdale Airport (SCF) and Phoenix-Mesa Gateway (AZA). ${Ba} Your chauffeur tracks your flight.`},{question:"How far in advance should I book a limo?",answer:Vt},{question:"Do you serve Phoenix?",answer:"Yes. We run chauffeured limos throughout Scottsdale, Paradise Valley and the greater Phoenix area."},{question:"Can we decorate the limo or add a Just Married sign?",answer:"Yes, as priced add-ons you choose at checkout: Just Married signage, balloons and décor, a red carpet arrival and more. Anything vehicle-specific is confirmed in writing before payment."}],fs={path:os,title:"Limo service in Scottsdale and Phoenix",metaTitle:"Scottsdale Limo Service & Limo Rental",description:`Scottsdale limo service with a professional chauffeur on every booking: the ${r(S)}, the classic stretch ${r(k)}, the Limo Party Sprinters and the ${r(ae)}, each with its published hourly rate. Pick the group, see the price and reserve online, in Scottsdale and across Phoenix.`,metaDescription:"The Pink Hummer, a classic stretch, Limo Sprinters and the Maybach Jet, chauffeured, with the price on the page",lastUpdated:Fa,lastUpdatedLabel:T(Fa),intro:`Scottsdale limo service from Scottsdale Sprinters comes with a professional chauffeur on every booking, in Scottsdale and across Phoenix. Start with who is riding. VIP and ultra-luxury parties lead with the ${r(ae)}, then the ${r(C)}, the ${r(ze)} and the ${r(ye)}. Nights out and bachelorettes ride the one-of-one ${r(S)} or a Limo Party Sprinter. Weddings, proms and executive groups take the classic stretch, the ${r(k)}, or an Executive Sprinter. Every limo here shows its published hourly rate, and you can reach the reservations team at ${F} or ${M}.`,sections:us,faqs:ps,links:[{href:"/fleet/pink-hummer-limo",label:r(S)},{href:"/fleet/limo-sprinter-13-scottsdale",label:r(ue)},{href:"/fleet/limo-sprinter-16-scottsdale",label:r(pe)},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:r(C)},{href:"/fleet/maybach-jet-sprinter-scottsdale",label:r(ae)},{href:"/guides/pink-party-bus-scottsdale",label:"Pink party bus or pink limo?"},{href:"/guides/party-bus-vs-limo-vs-sprinter",label:"Party bus vs limo vs Sprinter"},{href:"/guides/party-bus-alcohol-laws-arizona",label:"Arizona alcohol rules on board"},{href:"/services/wedding-transportation-scottsdale",label:"Wedding limo and transportation"},{href:"/experiences/prom-night",label:"Prom night limo"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport limo pickups"},{href:"/service-areas/phoenix",label:"Phoenix service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:cs,fleetRows:nt},Da="2026-09-25",ms="/guides/venues/talking-stick-resort-amphitheatre",le="ultra-luxury-party-sprinter-scottsdale",It="maybach-jet-sprinter-scottsdale",gs="maybach-shuttle-sprinter-8",ys="premium-suv-scottsdale",de="limo-sprinter-13-scottsdale",xt="limo-sprinter-16-scottsdale",Wt="party-bus-28-scottsdale",ce="executive-sprinter-scottsdale",bs="executive-white-sprinter-scottsdale",Gt="executive-mini-bus-26-scottsdale",Nt="executive-luxury-bus-29-scottsdale",Lt="motorcoach-56",i=e=>n[e],V=e=>c[e],_t=e=>`${g(s[e].hourlyRateCents)} an hour with a ${s[e].minimumHours}-hour minimum`,Te="https://www.talkingstickresortamphitheatre.com",ws=`${Te}/visit`,vs=`${Te}/know-before-you-go`,ks=`${Te}/faq`,Ss=`${Te}/upgrades/parking`,As=`${Te}/accessibility`,Ts=`${Te}/shows`,$s="https://www.livenation.com/venue/KovZpZAE6vJA/talking-stick-resort-amphitheatre-events",Cs="https://www.prnewswire.com/news-releases/phoenix-music-venue-to-be-renamed-talking-stick-resort-amphitheatre-301719437.html",Ps=[{label:"Talking Stick Resort Amphitheatre, plan your visit",href:ws},{label:"Talking Stick Resort Amphitheatre, the need-to-know before you go",href:vs},{label:"Talking Stick Resort Amphitheatre, frequently asked questions",href:ks},{label:"Talking Stick Resort Amphitheatre, parking upgrades",href:Ss},{label:"Talking Stick Resort Amphitheatre, accessibility",href:As},{label:"Talking Stick Resort Amphitheatre, upcoming shows",href:Ts},{label:"Live Nation, Talking Stick Resort Amphitheatre events",href:$s},{label:"Live Nation, Phoenix music venue to be renamed Talking Stick Resort Amphitheatre (January 11, 2023)",href:Cs}],zt=["January","February","March","April","May","June","July","August","September","October","November","December"],Fs=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];function Ms(e){const[t,a,o]=e.split("-").map(Number);return`${Fs[new Date(Date.UTC(t,a-1,o)).getUTCDay()]}, ${zt[a-1]} ${o}, ${t}`}function Es(e){return`${Ms(e.date)}: ${e.title} (show ${Wa(`${e.date}T${e.starts}:00-07:00`)}).`}function J(e,t,...a){return{question:e,answer:t,paragraphs:a}}const N=Jt.filter(e=>e.date.startsWith("2026")),Ut=Jt.filter(e=>!e.date.startsWith("2026")),Ds=[J("How does parking work at Talking Stick Resort Amphitheatre?","Talking Stick Resort Amphitheatre’s parking lots typically open 30 minutes before the scheduled gate time, and gates usually open 60 to 90 minutes before the show. Parking is sold show by show on the venue’s parking page, and its upgrades include Premier Parking, a short walk from the gates, and Easy Out Parking near the West Gate (Gate 2) for the fastest exit.","Reserved Premier Parking is a guaranteed space at the front of the Premier lot, held all night whether you arrive early or late; it is for cars only. The venue also sells an oversized space for a limousine or an RV in the Premier lot. Every upgrade is limited.","No tailgating is allowed, and no overnight parking: an unauthorized vehicle on site before or after an event is towed at the owner’s expense. Accessible parking is inside Gate 3 and Gate 6 off Encanto Boulevard, first come, first served, for a state-issued placard or plate; the venue suggests arriving when the lots open.","The venue’s pages publish no parking price: parking is sold per show, and the box office handles parking refunds and upgrades."),J("Where is the drop-off and rideshare pickup at Talking Stick Resort Amphitheatre?","The venue’s drop-off and pick-up area is on the west side of Talking Stick Resort Amphitheatre, through Gate 3: tell parking staff you are dropping off and they show you the way. To pick up, arrive at least 45 minutes before the show ends, or you will not be able to enter. Rideshare riders meet their car on Palm Lane, on the southwest side of the venue.","That is the area a chauffeured group uses too. We tell parking staff we are dropping off, unload the group through Gate 3, and are back inside the pick-up area before the 45-minute cutoff, so the group walks out to its own vehicle instead of joining the rideshare line on Palm Lane.","A group that splits across cars also splits across lots, gates and exits. One vehicle arrives with everyone at once and leaves with everyone at once."),J("Where is Talking Stick Resort Amphitheatre, and is it at Talking Stick Resort?","Talking Stick Resort Amphitheatre is at 2121 North 83rd Avenue, Phoenix, AZ 85035, in Maryvale on the west side of Phoenix. It is not at Talking Stick Resort: the venue says plainly that it is not the same location as the Talking Stick Resort & Casino, which is in Scottsdale. Talking Stick Resort is the amphitheatre’s name-in-title sponsor.","Live Nation, which runs the venue, renamed it in January 2023; it was the Ak-Chin Pavilion before that. The venue has hosted concerts for over 30 years.","By Google’s typical drive time, measured on September 24, 2026 without show traffic, the amphitheatre is 16 minutes from downtown Phoenix, 20 minutes from Phoenix Sky Harbor, 29 minutes from Old Town Scottsdale, 34 minutes from the Talking Stick Resort casino and 38 minutes from Kierland. Show nights add the venue’s own traffic to the last mile."),J("What time do gates open at Talking Stick Resort Amphitheatre?","Gates at Talking Stick Resort Amphitheatre usually open 60 to 90 minutes before showtime, and the parking lots about 30 minutes before the gates. The exact gate and parking times for each show are posted on the venue’s Need-to-Know page closer to the date.","There are two main entry gates, the West Gate and the East Gate, and some shows open only one. The box office is open on show days only: the West Box Office from noon, the East Box Office about an hour before doors, card only.","Re-entry is not permitted: once you leave, you need a new ticket to come back in. Events are all ages unless the show says otherwise, and shows go on rain or shine, barring severe weather."),J("What is the Talking Stick Resort Amphitheatre bag policy?","Only small clutches, wristlets or fanny packs up to 6 by 9 inches, or clear plastic bags up to 12 by 12 by 6 inches, are allowed inside Talking Stick Resort Amphitheatre. All bags are subject to search at entry, with metal detectors and sometimes a pat-down.","Not allowed: backpacks and other bags outside the policy, coolers of any size, outside food or drink except factory-sealed water, alcohol, glass, cans, metal hydroflasks, lawn chairs, strollers, laser pointers, selfie sticks and aerosol sunscreen. Factory-sealed, unfrozen water up to one gallon per person is allowed, and refill stations are inside.","The venue is cash-free: guest services swap cash for a card at no charge. Settle bags at the hotel; a group that is dropped off has no car in the lot to go back to during the show."),J("How many people does Talking Stick Resort Amphitheatre hold, and how does the lawn work?","Live Nation describes Talking Stick Resort Amphitheatre as a 20,000-seat outdoor venue. The lawn is always first come, first served: a row or seat number on a lawn ticket is only for the box office’s tracking, and there are no assigned seats on the lawn.","Lawn chairs can be rented for most shows and are the only chairs allowed inside; blankets are not permitted at some shows. For a large party, the venue’s Premium Seating department sells VIP boxes, suites and clubs that hold more guests than the standard ticket limit.","For a group, the lawn decides the ride: arriving together at gate time is how a crew gets a spot together, and leaving together is how it gets home."),J("Which vehicle fits a Talking Stick Resort Amphitheatre group?",`Concert crews ride the ${i(de)}, the ${i(xt)} or the ${i(Wt)}. A VIP night takes the ${i(It)}, the ${i(le)}, the ${i(gs)} or the ${i(ys)}. Corporate and big groups take the ${i(ce)}, the ${i(bs)}, the ${i(Gt)}, the ${i(Nt)} or the ${i(Lt)}.`,`Seat counts are seated capacities from the fleet: the ${i(le)} seats ${V(le)}, the ${i(de)} ${V(de)}, the ${i(xt)} ${V(xt)}, the ${i(Wt)} ${V(Wt)} and the ${i(It)} ${V(It)}. The ${i(ce)} seats ${V(ce)}, the ${i(Gt)} ${V(Gt)}, the ${i(Nt)} ${V(Nt)} and the ${i(Lt)} ${V(Lt)}.`,`Our pick for a night on the lawn is the ${i(le)}, ${_t(le)}: fiber-optic lighting with eighteen modes, an ultra-premium sound system with subwoofers, a wet bar with champagne glass holders and a full partition with an intercom to your chauffeur. The ${i(de)} is ${_t(de)}, and the ${i(ce)} is ${_t(ce)}. Every rate prices the whole vehicle, before tax.`,"Count riders for the ride home as well as the ride there; the late list is the one that matters. For a group bigger than one vehicle, we plan two or more and quote them together."),J("How should a group plan the ride to a Talking Stick Resort Amphitheatre show?","Plan backwards from the show time. Gates usually open 60 to 90 minutes before the show, so a pickup that lands the group at the Gate 3 drop-off around gate time leaves room for the lines, the bag check and a spot on the lawn.","The ride home is the part to plan hardest. The venue lets pickups into its pick-up area only until 45 minutes before the show ends, so your chauffeur is in place before the encore and the group walks straight out to its vehicle.",`Book by the hour and the vehicle is yours for the whole night, dinner before the show included, or book a ride there and a ride back. Reach the reservations team at ${F} or ${M} with the show, the date, the pickup area and the rider count.`)],Rs=J("What’s coming up at Talking Stick Resort Amphitheatre?",`Talking Stick Resort Amphitheatre lists ${N.length} more shows this fall, from ${N[0].label} on ${zt[Number(N[0].date.slice(5,7))-1]} ${Number(N[0].date.slice(8))} to ${N[N.length-1].label} on ${zt[Number(N[N.length-1].date.slice(5,7))-1]} ${Number(N[N.length-1].date.slice(8))}, and ${Ut.length===1?`one 2027 show so far, ${Ut[0].label}`:`${Ut.length} 2027 shows so far`}. As the venue’s show list gave them on September 24, 2026:`,...Jt.map(Es),"Gate and parking times for each show are posted on the venue’s Need-to-Know page closer to the date. New shows are added to the venue’s calendar through the year, and it is the place to check before you book."),Is=[{question:"Where do you park at Talking Stick Resort Amphitheatre?",answer:"In the venue’s own lots, which typically open 30 minutes before the gates. Parking is sold per show, with Premier Parking a short walk from the gates and Easy Out Parking by the West Gate (Gate 2) for the fastest exit. No tailgating and no overnight parking."},{question:"How much is parking at Talking Stick Resort Amphitheatre?",answer:"The venue’s pages publish no price: parking is sold per show on the venue’s parking page. Premier, Reserved Premier and Easy Out spaces cost more and are limited."},{question:"Where is the rideshare pickup at Talking Stick Resort Amphitheatre?",answer:"On Palm Lane, on the southwest side of the venue. Drop-off is on the west side through Gate 3; tell parking staff you are dropping off."},{question:"Can a limo or party bus drop off at Talking Stick Resort Amphitheatre?",answer:"Yes, in the venue’s drop-off and pick-up area on the west side through Gate 3, as parking staff direct. For the ride home the vehicle must be in the pick-up area at least 45 minutes before the show ends, or it cannot enter."},{question:"Is Talking Stick Resort Amphitheatre at Talking Stick Resort?",answer:"No. The amphitheatre is at 2121 North 83rd Avenue in Phoenix; the Talking Stick Resort & Casino is in Scottsdale, about 34 minutes’ drive away. The venue says they are not the same location."},{question:"What time do gates open at Talking Stick Resort Amphitheatre?",answer:"Usually 60 to 90 minutes before showtime, with the lots about 30 minutes before the gates. Exact times are posted for each show on the venue’s Need-to-Know page."},{question:"What is the Talking Stick Resort Amphitheatre bag policy?",answer:"Small clutches, wristlets or fanny packs up to 6 by 9 inches, or clear bags up to 12 by 12 by 6 inches. No backpacks, coolers or lawn chairs of your own."},{question:"Can you tailgate at Talking Stick Resort Amphitheatre?",answer:"No. The venue allows no tailgating and no overnight parking."},{question:"How many people does Talking Stick Resort Amphitheatre hold?",answer:"Live Nation describes it as a 20,000-seat outdoor venue, with a first-come, first-served lawn."},{question:"Can you leave and come back in at Talking Stick Resort Amphitheatre?",answer:"No. Re-entry is not permitted; leaving means a new ticket to come back in."}],xs={path:ms,title:"Talking Stick Resort Amphitheatre: Parking, Upcoming Shows and Concert Rides",metaTitle:"Talking Stick Amphitheatre Parking",description:"Talking Stick Resort Amphitheatre in Phoenix, not the Scottsdale casino: how the parking works, the Gate 3 drop-off and the Palm Lane rideshare pickup, gate times, the bag policy, the lawn, the upcoming shows, and a chauffeured ride so nobody drives or parks.",metaDescription:"Lots, gates, the Gate 3 drop-off and a chauffeured ride",lastUpdated:Da,lastUpdatedLabel:T(Da),eyebrow:"Phoenix · Maryvale",intro:"Scottsdale Sprinters’ short answer on Talking Stick Resort Amphitheatre: it is the outdoor concert venue at 2121 North 83rd Avenue in Phoenix, not the Talking Stick Resort casino in Scottsdale. Its lots typically open 30 minutes before the gates, and the gates usually 60 to 90 minutes before the show. The drop-off and pick-up area is on the west side through Gate 3, and rideshare pickup is on Palm Lane. For a group, one chauffeured vehicle replaces the lot, the pickup line and the drive home.",sections:[...Ds,Rs],faqs:Is,links:[{href:"/guides/venues/talking-stick-resort",label:"Talking Stick Resort group arrival guide"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:"/service-areas/phoenix",label:"Phoenix service area"},{href:`/fleet/${le}`,label:i(le)},{href:`/fleet/${de}`,label:i(de)},{href:`/fleet/${ce}`,label:i(ce)},{href:"/pricing",label:"Published hourly pricing"}],sources:Ps},Ra=Object.assign({"./asu-gcu-graduation-transportation.ts":Sn,"./barrett-jackson-transportation.ts":Va,"./cactus-league-spring-training.ts":qn,"./chase-field.ts":Yr,"./desert-diamond-arena.ts":lo,"./footprint-center.ts":sn,"./innings-festival-transportation.ts":Po,"./m3f-festival-transportation.ts":Oo,"./nba-all-star-weekend-2027.ts":ns,"./scottsdale-limo-service.ts":fs,"./state-farm-stadium.ts":tn,"./talking-stick-resort-amphitheatre.ts":xs}),_s=Object.keys(Ra).sort().map(e=>Ra[e]);export{Ls as B,Yr as C,_s as F,sn as M,Ns as P,tn as S};
